let pendingSubmitChangeId = null;
let pendingBatchSubmitChangeIds = [];
let changeReviewActiveTab = 'pending';
let pendingChangeReviewId = null;
let selectedChangeReviewIds = new Set();
let selectedChangeApplyIds = new Set();
