/** 教师开课学时统计 · Teaching Load 演示数据（对齐学院 Excel 示意表；学期与开课时间设置一致） */
const TEACHER_TEACHING_LOAD_MAX_TERMS = 6;
const TEACHER_TEACHING_LOAD_DEMO = {
  terms: ['202402', '202404', '202409', '202502', '202504', '202509', '202602', '202604', '202609'],
  teachers: [
    { name: 'Dr. Kim Yun Jin', hours: [15, 138, 120, 0, 114, 106, 90, 132, 0] },
    { name: 'Dr. Lim Chee Hoong', hours: [90, 120, 105, 30, 0, 135, 60, 165, 45] },
    { name: 'Dr. Chep Lee Lu Siang', hours: [105, 120, 90, 30, 90, 0, 75, 153, 60] },
    { name: 'Mr. Wong Guo Lin', hours: [75, 90, 80, 30, 60, 114, 45, 90, 30] },
    { name: 'Dr. Tan Hong Yien', hours: [90, 105, 95, 60, 75, 122, 60, 90, 45] },
    { name: 'Dr. Aslam Muhammad Shahzad', hours: [60, 120, 100, 30, 90, 165, 75, 83, 60] }
  ]
};

/** @type {string[]|null} null 表示尚未初始化，首次进入按当前开课学期默认单选 */
let teacherTeachingLoadSelectedTerms = null;

function formatTeacherTeachingLoadTermLabel(termCode) {
  const code = String(termCode || '');
  const short = code.length >= 4 ? code.slice(-4) : code;
  return `${short} semester`;
}

function formatTeacherTeachingLoadHours(value) {
  const n = Number(value);
  if (!Number.isFinite(n)) return '—';
  return Number.isInteger(n) ? String(n) : n.toFixed(1);
}

function getTeacherTeachingLoadAvailableTerms() {
  return TEACHER_TEACHING_LOAD_DEMO.terms.slice();
}

function getDefaultTeacherTeachingLoadTerms() {
  const available = getTeacherTeachingLoadAvailableTerms();
  const def = getDefaultOfferingTermCode();
  if (def && available.includes(def)) return [def];
  return available.length ? [available[available.length - 1]] : [];
}

function ensureTeacherTeachingLoadSelectedTerms() {
  const available = getTeacherTeachingLoadAvailableTerms();
  if (!teacherTeachingLoadSelectedTerms) {
    teacherTeachingLoadSelectedTerms = getDefaultTeacherTeachingLoadTerms();
  } else {
    teacherTeachingLoadSelectedTerms = teacherTeachingLoadSelectedTerms.filter(t => available.includes(t));
    if (!teacherTeachingLoadSelectedTerms.length) {
      teacherTeachingLoadSelectedTerms = getDefaultTeacherTeachingLoadTerms();
    }
  }
  return teacherTeachingLoadSelectedTerms.slice(0, TEACHER_TEACHING_LOAD_MAX_TERMS);
}

function getTeacherTeachingLoadTermIndices(selectedTerms) {
  const all = TEACHER_TEACHING_LOAD_DEMO.terms;
  return selectedTerms.map(term => all.indexOf(term)).filter(idx => idx >= 0);
}

function ensureTeacherTeachingLoadTermMultiselect() {
  const options = document.getElementById('teacher-load-filter-term-options');
  if (!options) return;
  const selected = new Set(ensureTeacherTeachingLoadSelectedTerms());
  options.innerHTML = getTeacherTeachingLoadAvailableTerms().map(term =>
    `<label class="clo-multiselect-option">
      <input type="checkbox" class="teacher-load-term-check" value="${escapeHtml(term)}" ${selected.has(term) ? 'checked' : ''} onchange="onTeacherTeachingLoadTermToggle(this)">
      <span>${escapeHtml(formatCourseTermDisplay(term))}</span>
    </label>`
  ).join('');
  updateTeacherTeachingLoadTermDisplay();
}

function getTeacherTeachingLoadTermChecks() {
  return [...document.querySelectorAll('#teacher-load-filter-term-options .teacher-load-term-check')];
}

function updateTeacherTeachingLoadTermDisplay() {
  const display = document.getElementById('teacher-load-filter-term-display');
  if (!display) return;
  const selected = ensureTeacherTeachingLoadSelectedTerms();
  if (selected.length) {
    display.textContent = selected.map(formatCourseTermDisplay).join('、');
    display.classList.remove('placeholder');
  } else {
    display.textContent = '请选择';
    display.classList.add('placeholder');
  }
}

function onTeacherTeachingLoadTermToggle(checkbox) {
  if (!checkbox) return;
  const checked = getTeacherTeachingLoadTermChecks().filter(el => el.checked).map(el => el.value);
  if (checkbox.checked && checked.length > TEACHER_TEACHING_LOAD_MAX_TERMS) {
    checkbox.checked = false;
    alert(`最多同时展示 ${TEACHER_TEACHING_LOAD_MAX_TERMS} 个学期`);
    return;
  }
  if (!checked.length) {
    checkbox.checked = true;
    alert('请至少选择 1 个开课学期');
    return;
  }
  teacherTeachingLoadSelectedTerms = getTeacherTeachingLoadTermChecks()
    .filter(el => el.checked)
    .map(el => el.value);
  updateTeacherTeachingLoadTermDisplay();
}

function toggleTeacherTeachingLoadTermDropdown(event) {
  event.stopPropagation();
  const dd = document.getElementById('teacher-load-filter-term-dropdown');
  if (!dd) return;
  const willOpen = dd.hidden;
  closeTeacherTeachingLoadTermDropdown();
  if (willOpen) {
    ensureTeacherTeachingLoadTermMultiselect();
    dd.hidden = false;
  }
}

function closeTeacherTeachingLoadTermDropdown() {
  const dd = document.getElementById('teacher-load-filter-term-dropdown');
  if (dd) dd.hidden = true;
}

function getFilteredTeacherTeachingLoadRows() {
  const q = (document.getElementById('teacher-load-filter-name')?.value || '').trim().toLowerCase();
  return TEACHER_TEACHING_LOAD_DEMO.teachers.filter(row => {
    if (!q) return true;
    return String(row.name || '').toLowerCase().includes(q);
  });
}

function queryTeacherTeachingLoadPage() {
  closeTeacherTeachingLoadTermDropdown();
  renderCourseTeacherTeachingLoadPage();
}

function resetTeacherTeachingLoadFilters() {
  const input = document.getElementById('teacher-load-filter-name');
  if (input) input.value = '';
  teacherTeachingLoadSelectedTerms = getDefaultTeacherTeachingLoadTerms();
  ensureTeacherTeachingLoadTermMultiselect();
  closeTeacherTeachingLoadTermDropdown();
  renderCourseTeacherTeachingLoadPage();
}

function renderCourseTeacherTeachingLoadPage() {
  const head = document.getElementById('teacher-teaching-load-head');
  const body = document.getElementById('teacher-teaching-load-body');
  const foot = document.getElementById('teacher-teaching-load-foot');
  if (!head || !body || !foot) return;
  ensureTeacherTeachingLoadTermMultiselect();
  const terms = ensureTeacherTeachingLoadSelectedTerms();
  const termIndices = getTeacherTeachingLoadTermIndices(terms);
  const rows = getFilteredTeacherTeachingLoadRows();
  const termColCount = terms.length;
  head.innerHTML = `
    <tr>
      <th class="teacher-load-title" colspan="${2 + termColCount}">Teaching Load (hour)</th>
    </tr>
    <tr>
      <th class="col-index col-center">序号</th>
      <th class="col-name">Name</th>
      ${terms.map(term => `<th class="col-term col-center">${escapeHtml(formatTeacherTeachingLoadTermLabel(term))}</th>`).join('')}
    </tr>`;
  if (!rows.length) {
    body.innerHTML = `<tr><td colspan="${2 + termColCount}" class="text-muted" style="text-align:center;padding:24px">暂无教师学时数据</td></tr>`;
    foot.innerHTML = '';
    return;
  }
  body.innerHTML = rows.map((row, idx) => `<tr>
      <td class="col-index col-center">${idx + 1}</td>
      <td class="col-name">${escapeHtml(row.name)}</td>
      ${termIndices.map(termIdx => `<td class="col-term col-center">${escapeHtml(formatTeacherTeachingLoadHours(row.hours?.[termIdx]))}</td>`).join('')}
    </tr>`).join('');
  const totals = termIndices.map(termIdx =>
    rows.reduce((sum, row) => sum + (Number(row.hours?.[termIdx]) || 0), 0)
  );
  const averages = totals.map(total => (rows.length ? total / rows.length : 0));
  foot.innerHTML = `
    <tr class="is-total">
      <td class="col-index col-center"></td>
      <td class="col-name">Grand Total</td>
      ${totals.map(v => `<td class="col-term col-center">${escapeHtml(formatTeacherTeachingLoadHours(v))}</td>`).join('')}
    </tr>
    <tr class="is-average">
      <td class="col-index col-center"></td>
      <td class="col-name">AVERAGE</td>
      ${averages.map(v => `<td class="col-term col-center">${escapeHtml(Number(v).toFixed(1))}</td>`).join('')}
    </tr>`;
}

// ── 通识选修 · 需求 / 配额（方案 A） ──
/**
 * 专业代码 → 文/商/理（挂在专业；学院本身无文商理类别）
 * Arts: CHS/ENG/ADT/COS/JRN · Business: ACC/ECM/FIN/HMT/IBU
 * Science: CAMS/SCDS/SECE/SEEAI/SMP/STCM 下各专业
 */
const PROGRAMME_GE_STREAM_MAP = {
  CHS: 'arts', ENG: 'arts',
  ADT: 'arts', COS: 'arts', JRN: 'arts',
  ACC: 'business', ECM: 'business', FIN: 'business', HMT: 'business', IBU: 'business',
  MBT: 'science', MEC: 'science',
  CST: 'science', CYS: 'science', DMT: 'science', DSC: 'science', SWE: 'science',
  CME: 'science', EGE: 'science',
  AIT: 'science', EEE: 'science', ERA: 'science',
  MAT: 'science', PHY: 'science',
  TCM: 'science'
};

const GE_OFFERING_CROSS_RULE_NOTE =
  '文科学生可选商科、理科 GE；商科学生可选文科、理科 GE；理科学生可选文科、商科 GE（不可同大类）。';

const GE_OFFERING_DEMAND_BY_TERM = {};
const GE_OFFERING_QUOTA_BY_TERM = {};

function getProgrammeGeStream(programmeCodeOrKey) {
  if (!programmeCodeOrKey) return 'science';
  const raw = String(programmeCodeOrKey);
  const code = (PROGRAMMES[raw]?.code || raw).toUpperCase();
  return PROGRAMME_GE_STREAM_MAP[code] || 'science';
}

function buildGeOfferingDemandMock(termCode) {
  // batches: { programmeCode, intake, students }
  const bySchool = [
    {
      schoolCode: 'SASS',
      batches: [
        { programmeCode: 'ENG', intake: '2023/09', students: 70 },
        { programmeCode: 'CHS', intake: '2024/02', students: 50 }
      ]
    },
    {
      schoolCode: 'SOC',
      batches: [
        { programmeCode: 'JRN', intake: '2023/09', students: 55 },
        { programmeCode: 'ADT', intake: '2024/02', students: 50 },
        { programmeCode: 'COS', intake: '2023/09', students: 55 }
      ]
    },
    {
      schoolCode: 'SEM',
      batches: [
        { programmeCode: 'ACC', intake: '2023/09', students: 80 },
        { programmeCode: 'FIN', intake: '2023/09', students: 75 },
        { programmeCode: 'IBU', intake: '2024/02', students: 65 },
        { programmeCode: 'ECM', intake: '2023/09', students: 60 }
      ]
    },
    {
      schoolCode: 'SEEAI',
      batches: [
        { programmeCode: 'AIT', intake: '2023/09', students: 80 },
        { programmeCode: 'EEE', intake: '2024/02', students: 60 },
        { programmeCode: 'ERA', intake: '2023/09', students: 60 }
      ]
    },
    {
      schoolCode: 'SCDS',
      batches: [
        { programmeCode: 'CST', intake: '2023/09', students: 90 },
        { programmeCode: 'SWE', intake: '2024/02', students: 75 },
        { programmeCode: 'DSC', intake: '2023/09', students: 75 }
      ]
    },
    {
      schoolCode: 'SMP',
      batches: [
        { programmeCode: 'MAT', intake: '2023/09', students: 50 },
        { programmeCode: 'PHY', intake: '2024/02', students: 40 }
      ]
    },
    {
      schoolCode: 'SECE',
      batches: [
        { programmeCode: 'CME', intake: '2023/09', students: 60 },
        { programmeCode: 'EGE', intake: '2024/02', students: 50 }
      ]
    },
    {
      schoolCode: 'CAMS',
      batches: [
        { programmeCode: 'MBT', intake: '2023/09', students: 40 },
        { programmeCode: 'MEC', intake: '2024/02', students: 30 }
      ]
    },
    {
      schoolCode: 'STCM',
      batches: [
        { programmeCode: 'TCM', intake: '2022/09', students: 55 }
      ]
    }
  ].map(row => {
    const students = row.batches.reduce((n, b) => n + (b.students || 0), 0);
    return {
      schoolCode: row.schoolCode,
      students,
      batches: row.batches.map(b => `${b.programmeCode} ${b.intake}`),
      batchDetails: row.batches.map(b => ({
        ...b,
        stream: getProgrammeGeStream(b.programmeCode)
      }))
    };
  });
  const byStream = { arts: 0, business: 0, science: 0 };
  bySchool.forEach(row => {
    (row.batchDetails || []).forEach(b => {
      byStream[b.stream] = (byStream[b.stream] || 0) + (b.students || 0);
    });
  });
  const totalStudents = bySchool.reduce((sum, row) => sum + row.students, 0);
  return {
    termCode,
    totalStudents,
    bySchool,
    byStream,
    crossRuleNote: GE_OFFERING_CROSS_RULE_NOTE,
    isMock: true
  };
}

function ensureGeOfferingDemand(termCode) {
  if (!termCode) return null;
  const cached = GE_OFFERING_DEMAND_BY_TERM[termCode];
  // 旧 mock 按学院挂 stream，无 batchDetails → 重建为按专业大类汇总
  if (!cached || !Array.isArray(cached.bySchool?.[0]?.batchDetails)) {
    GE_OFFERING_DEMAND_BY_TERM[termCode] = buildGeOfferingDemandMock(termCode);
  }
  return GE_OFFERING_DEMAND_BY_TERM[termCode];
}

function getGeOfferingSectionPlannedGroupCount(sec) {
  if (!sec) return 0;
  const fromGroups = Array.isArray(sec.groups) ? sec.groups.length : 0;
  const planned = Number(sec.plannedGroupCount);
  const n = Math.max(fromGroups, Number.isFinite(planned) && planned > 0 ? planned : 0);
  return n > 0 ? n : 1;
}

function getGeOfferingActualGroupsBySchool(termCode) {
  if (!termCode) return {};
  const prev = COURSE_OFFERING_PLAN_STORE;
  syncCourseOfferingPlanStoreFromTerm(termCode);
  const map = {};
  (COURSE_OFFERING_PLAN_STORE?.sections || [])
    .filter(s => s.offeringType === 'ge')
    .forEach(sec => {
      ensureGeOfferingSectionFields(sec);
      const unit = resolveGeOfferingSectionOfferingUnit(sec);
      if (!unit) return;
      map[unit] = (map[unit] || 0) + getGeOfferingSectionPlannedGroupCount(sec);
    });
  if (prev?.termCode && prev.termCode !== termCode) {
    syncCourseOfferingPlanStoreFromTerm(prev.termCode);
  } else if (prev) {
    COURSE_OFFERING_PLAN_STORE = prev;
  }
  return map;
}

function buildDefaultGeOfferingQuota(termCode) {
  const actual = getGeOfferingActualGroupsBySchool(termCode);
  const colleges = (SCHOOL_CODES || []).map(schoolCode => {
    let minGroups = 2;
    // 演示：SEEAI 保底比当前已开多 1 组，便于演示「差 1 组不可提交」
    if (schoolCode === 'SEEAI') {
      minGroups = Math.max(2, (actual.SEEAI || 0) + 1);
    } else if (schoolCode === 'SEM') {
      minGroups = 3;
    }
    return { schoolCode, minGroups };
  });
  return { termCode, colleges };
}

function ensureGeOfferingQuota(termCode) {
  if (!termCode) return null;
  if (!GE_OFFERING_QUOTA_BY_TERM[termCode]) {
    GE_OFFERING_QUOTA_BY_TERM[termCode] = buildDefaultGeOfferingQuota(termCode);
  } else {
    // 兼容旧缓存：去掉学院 stream / 统筹参数字段
    const q = GE_OFFERING_QUOTA_BY_TERM[termCode];
    delete q.refGroupSize;
    delete q.categoryTotals;
    if (Array.isArray(q.colleges)) {
      q.colleges = q.colleges.map(c => ({
        schoolCode: c.schoolCode,
        minGroups: Number(c.minGroups) || 0
      }));
    }
  }
  return GE_OFFERING_QUOTA_BY_TERM[termCode];
}

function getGeOfferingQuotaCollege(termCode, schoolCode) {
  const quota = ensureGeOfferingQuota(termCode);
  return quota?.colleges?.find(c => c.schoolCode === schoolCode) || null;
}

function getGeOfferingQuotaProgressRows(termCode) {
  const quota = ensureGeOfferingQuota(termCode);
  if (!quota) return [];
  const actual = getGeOfferingActualGroupsBySchool(termCode);
  return (quota.colleges || []).map(c => {
    const actualGroups = actual[c.schoolCode] || 0;
    const minGroups = Number(c.minGroups) || 0;
    return {
      schoolCode: c.schoolCode,
      minGroups,
      actualGroups,
      met: actualGroups >= minGroups,
      shortfall: Math.max(0, minGroups - actualGroups)
    };
  });
}

function collectGeOfferingQuotaShortfallsForSections(secs, termCode) {
  const units = [...new Set(
    (secs || []).map(sec => resolveGeOfferingSectionOfferingUnit(ensureGeOfferingSectionFields(sec))).filter(Boolean)
  )];
  if (!units.length) return [];
  const rows = getGeOfferingQuotaProgressRows(termCode);
  return rows.filter(r => units.includes(r.schoolCode) && !r.met);
}

