function syncMajorOfferingEditDrawerReadOnly(sec) {
  const locked = isMajorOfferingPlanEditLocked(sec);
  const drawer = document.getElementById('drawer-major-offering-edit');
  drawer?.classList.toggle('is-readonly', locked);
  syncMajorOfferingReadonlyHint(drawer?.querySelector('.drawer-body'), sec, 'major-offering-edit-readonly-hint', {
    isLocked: isMajorOfferingPlanEditLocked,
    getMessage: getMajorOfferingPlanEditLockMessage
  });
  const confirmBtn = drawer?.querySelector('.drawer-foot .btn-primary');
  if (confirmBtn) {
    confirmBtn.hidden = locked;
    confirmBtn.disabled = locked;
  }
  const cancelBtn = drawer?.querySelector('.drawer-foot .btn-ghost');
  if (cancelBtn) cancelBtn.textContent = locked ? '关闭' : '取消';
  const titleEl = drawer?.querySelector('.drawer-head h3');
  if (titleEl) titleEl.textContent = locked ? '查看教学任务' : '修改教学任务';
  // if (confirmBtn) { confirmBtn.hidden = false; confirmBtn.disabled = locked; } // 原只读仍显示置灰确定
  // if (cancelBtn) cancelBtn.textContent = '取消'; // 原只读与编辑共用取消文案
  ['mos-edit-teaching-code'].forEach(id => {
    const el = document.getElementById(id);
    if (!el) return;
    if (locked) {
      el.readOnly = true;
      el.classList.add('readonly');
    } else if (id === 'mos-edit-teaching-code') {
      el.readOnly = false;
      el.classList.remove('readonly');
    }
  });
  // ['mos-edit-teaching-code', 'mos-edit-remark'].forEach ... // mos-edit-remark 随教师安排模块隐藏
  ['mos-edit-enrollment-type', 'mos-edit-is-scheduled', 'mos-edit-is-venue-scheduled',
    'mos-edit-is-attendance', 'mos-edit-is-grade-entry', 'mos-edit-is-exam-scheduled',
    'mos-edit-support-history'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.disabled = locked;
  });
  const reservedEl = document.getElementById('mos-edit-reserved-spots');
  if (reservedEl) {
    reservedEl.readOnly = locked;
    reservedEl.disabled = locked;
    reservedEl.classList.toggle('readonly', locked);
  }
  // drawer?.querySelector('#mos-edit-venue-types-multiselect .clo-multiselect-trigger')
  //   ?.toggleAttribute('disabled', locked); // 原场地类型选择，字段已从抽屉移除
  drawer?.querySelectorAll('.input-with-btn .btn').forEach(btn => {
    btn.toggleAttribute('disabled', locked);
  });
  syncMajorOfferingEditStudentTotalField(sec);
}

function formatTeacherAssignmentsSummary(assignments) {
  if (!assignments?.length) return '';
  return assignments.map(t => `${t.name} (${t.staffId})`).join('、');
}

function formatTeacherHourTypesDisplay(h) {
  if (Array.isArray(h?.hourTypes) && h.hourTypes.length) return h.hourTypes.join('、');
  return h?.hourType || '—';
}

function normalizeTeacherHourFields(h, sec) {
  if (!h) return h;
  if (!Array.isArray(h.hourTypes) || !h.hourTypes.length) {
    const raw = String(h.hourType || '').trim();
    if (raw.includes('理论') && raw.includes('实践')) h.hourTypes = ['Lecture', 'Practical'];
    else if (raw.includes('&')) h.hourTypes = raw.split('&').map(s => s.trim()).filter(Boolean);
    else if (raw) h.hourTypes = [raw];
    else h.hourTypes = ['Lecture'];
  }
  if (h.mergeHours == null) h.mergeHours = false;
  if (!h.weekRange && sec?.weekRange) h.weekRange = sec.weekRange;
  h.hourType = formatTeacherHourTypesDisplay(h);
  return h;
}

function ensureTeacherAssignmentRowFields(ta) {
  if (!ta) return ta;
  if (ta.isCoordinator == null) ta.isCoordinator = false;
  if (ta.countTeachingHours == null) ta.countTeachingHours = true;
  return ta;
}

function ensureSectionTeacherAssignments(sec) {
  if (!sec) return [];
  if (!Array.isArray(sec.teacherAssignments)) sec.teacherAssignments = [];
  if (!sec.teacherAssignments.length) {
    sec.teacherAssignments.push({
      id: `ta-${majorOfferingTeacherAssignSeq++}`,
      staffId: '2001210010',
      name: '肖云',
      role: '主讲',
      isGradeSubmitter: true,
      isCoordinator: false,
      countTeachingHours: true,
      expanded: true,
      hours: [{
        id: `tah-${majorOfferingTeacherHourSeq++}`,
        hourTypes: ['Lecture', 'Practical'],
        weekRange: sec.weekRange || '1-12',
        hours: sec.totalHours || 48,
        mergeHours: false,
        hourType: 'Lecture、Practical',
        // hourType: '理论学时&实践学时', // 原单行文本
        // teachingCodeType: ''
      }]
    });
  }
  sec.teacherAssignments.forEach(ta => {
    ensureTeacherAssignmentRowFields(ta);
    (ta.hours || []).forEach(h => normalizeTeacherHourFields(h, sec));
  });
  return sec.teacherAssignments;
}

