function removeGroupAssignFormTeacher(staffId) {
  const wasCoordinator = groupAssignFormTeachers.find(t => t.staffId === staffId)?.isCoordinator;
  groupAssignFormTeachers = groupAssignFormTeachers.filter(t => t.staffId !== staffId);
  if (wasCoordinator && groupAssignFormTeachers.length === 1) {
    groupAssignFormTeachers[0].isCoordinator = true;
  }
  refreshGroupAssignFormPanels();
}

function openGroupAssignTeacherPicker() {
  if (groupAssignFormTeachers.length >= GROUP_ASSIGN_MAX_TEACHERS) {
    alert(`每条教师安排最多 ${GROUP_ASSIGN_MAX_TEACHERS} 名授课教师。`);
    return;
  }
  teacherPickerContext = 'groupAssign';
  majorOfferingTeacherPickerSelected.clear();
  // const roleSel = document.getElementById('teacher-picker-role'); // 原弹窗内分配角色
  // if (roleSel) roleSel.value = '主讲';
  const sec = getOfferingGroupingSection();
  const offeringUnit = resolveMajorOfferingSectionOfferingUnit(sec);
  const supportUnits = getMajorOfferingSectionSupportUnits(sec);
  const titleEl = document.getElementById('teacher-picker-title');
  if (titleEl) {
    if (offeringUnit && supportUnits.length) {
      titleEl.textContent = `选择授课教师（开课单位：${offeringUnit}；Support：${supportUnits.join('、')}）`;
    } else if (offeringUnit) {
      titleEl.textContent = `选择授课教师（开课单位：${offeringUnit}）`;
    } else {
      titleEl.textContent = '选择授课教师';
    }
  }
  resetListPage('majorOfferingTeacherPicker');
  ['teacher-picker-filter-staff-id', 'teacher-picker-filter-name'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.value = '';
  });
  ['teacher-picker-filter-type', 'teacher-picker-filter-gender'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.value = '';
  });
  ensureMajorOfferingTeacherPickerDeptFilter();
  syncGroupAssignTeacherPickerOfferingUnitFilter();
  syncTeacherPickerSimultaneousVisibility();
  renderMajorOfferingTeacherPickerModal();
  openModal('modal-major-teacher-picker');
}

function confirmGroupAssignTeacherPickerModal() {
  const keys = [...majorOfferingTeacherPickerSelected];
  if (!keys.length) {
    alert('请至少勾选一名教师。');
    return;
  }
  const remaining = GROUP_ASSIGN_MAX_TEACHERS - groupAssignFormTeachers.length;
  if (remaining <= 0) {
    alert(`每条教师安排最多 ${GROUP_ASSIGN_MAX_TEACHERS} 名授课教师。`);
    return;
  }
  if (teacherPickerContext === 'groupAssign' && getGroupAssignFormSelectedGroupIds().length > 1) {
    const sel = document.getElementById('teacher-picker-simultaneous');
    const val = sel?.value || '';
    if (val !== 'yes' && val !== 'no') {
      alert('已多选小组，请选择是否同时多组授课。');
      sel?.focus();
      return;
    }
    setGroupAssignFormSimultaneousGroups(val === 'yes');
  } else {
    groupAssignFormSimultaneousGroups = null;
  }
  const sec = getOfferingGroupingSection();
  const allowedUnits = getGroupAssignTeacherPickerAllowedUnits();
  const poolMap = new Map(buildMockTeacherPickerPool().map(t => [t.key, t]));
  const existingIds = new Set(groupAssignFormTeachers.map(t => t.staffId));
  const candidates = [];
  keys.forEach(key => {
    const pick = poolMap.get(key);
    if (!pick || existingIds.has(pick.staffId)) return;
    if (allowedUnits.length && !allowedUnits.includes(pick.departmentCode)) return;
    if (candidates.some(c => c.staffId === pick.staffId)) return;
    candidates.push(pick);
  });
  if (candidates.length > remaining) {
    alert(`每条教师安排最多 ${GROUP_ASSIGN_MAX_TEACHERS} 名授课教师，当前已有 ${groupAssignFormTeachers.length} 名，还可添加 ${remaining} 名。`);
    return;
  }
  let added = 0;
  candidates.forEach(pick => {
    groupAssignFormTeachers.push(enrichGroupAssignFormTeacher({
      staffId: pick.staffId,
      name: pick.name,
      teacherType: pick.teacherType,
      departmentCode: pick.departmentCode
    }, sec));
    // groupAssignFormTeachers.push({ staffId, name, role: '' }); // 原需手动选择授课角色
    existingIds.add(pick.staffId);
    added += 1;
  });
  closeMajorOfferingTeacherPickerModal();
  syncGroupAssignFormTeachersWithSectionCoordinator(sec);
  refreshGroupAssignFormPanels();
  syncGroupAssignHoursSummary();
  if (added) {
    const multiHint = getGroupAssignFormSelectedGroupIds().length > 1
      ? (groupAssignFormSimultaneousGroups === true
        ? '（已设为同时多组授课，学时只计一次）'
        : '（已设为各小组分别计入学时）')
      : '';
    alert(`已添加 ${added} 名授课教师${multiHint}。`);
  }
}

// function onGroupAssignGroupPickToggle() {
//   refreshGroupAssignFormPanels();
