function formatGroupAssignPlanWeeklyWarnMessage(summaries) {
  const list = Array.isArray(summaries) ? summaries : (summaries ? [summaries] : []);
  return formatGroupAssignPlanWeeklyWarnDisplayMessage(list);
  // return formatGroupAssignPlanWeeklyWarnShortMessage(summary?.planWeekly); // 原无小组名称
}

function getGroupAssignPlanWeeklyWarnHint(sec, editId, hourType, weeklyHours, weekRange) {
  const summaries = buildGroupAssignPlanWeeklyWarnSummaries(sec, editId, hourType, weeklyHours, weekRange);
  if (!summaries.length) return '';
  return formatGroupAssignPlanWeeklyWarnDisplayMessage(summaries, { saving: true });
  // return formatGroupAssignPlanWeeklyWarnShortMessage(summaries[0].planWeekly); // 原无小组名称
}

function getGroupAssignRecordedHoursOverHint(sec, hourType, editId, currentHours) {
  const typeTotal = getGroupAssignHourTypeTotal(sec, hourType);
  if (!typeTotal) return '';
  const targetGroupIds = getGroupAssignFormScopeGroupIds(sec);
  if (!targetGroupIds.length) return '';
  const lines = targetGroupIds.map(gid => {
    const recorded = sumGroupAssignRecordedHoursForGroupByType(sec, gid, hourType, editId);
    const totalAfter = recorded + currentHours;
    if (totalAfter <= typeTotal) return '';
    const label = formatGroupAssignScopeGroupLabel(sec, gid);
    return `${label}：${totalAfter}/${typeTotal}`;
  }).filter(Boolean);
  if (!lines.length) return '';
  if (lines.length === 1) {
    return `${hourType}含本次录入已超过总数（${lines[0]}），仍可保存。`;
  }
  return `以下小组${hourType}含本次录入已超过总数，仍可保存：${lines.join('；')}`;
}

function bindGroupAssignFormFieldEvents() {
  const whEl = document.getElementById('group-assign-weekly-hours');
  if (!whEl || whEl.dataset.boundSync) return;
  whEl.dataset.boundSync = '1';
  whEl.addEventListener('input', scheduleGroupAssignHoursSummarySync);
  whEl.addEventListener('change', syncGroupAssignHoursSummary);
}

let groupAssignHoursSummarySyncTimer = null;
let groupAssignWeekRangeDraft = new Set();
let groupAssignWeekPickerAllowedWeeks = null;
let groupAssignWeekPickerMaxWeek = MAJOR_OFFERING_MAX_WEEKS;

function syncOfferingSectionHoursConsistency(sec) {
  if (!sec) return;
  const meta = getCatalogOfferingMeta(sec.catalogId);
  if (sec.theoryHours == null || sec.theoryHours === '') sec.theoryHours = meta.theoryHours;
  if (sec.tutorialHours == null || sec.tutorialHours === '') sec.tutorialHours = meta.tutorialHours;
  if (sec.practiceHours == null || sec.practiceHours === '') sec.practiceHours = meta.practiceHours;
  if (sec.otherHours == null || sec.otherHours === '') sec.otherHours = meta.otherHours;
  const theory = Number(sec.theoryHours) || 0;
  const tutorial = Number(sec.tutorialHours) || 0;
  const practice = Number(sec.practiceHours) || 0;
  const other = Number(sec.otherHours) || 0;
  const sum = theory + tutorial + practice + other;
  const total = Number(sec.totalHours);
  if (Number.isFinite(total) && total >= 0 && sum !== total) {
    sec.practiceHours = Math.max(0, total - theory - tutorial - other);
  } else if ((!Number.isFinite(total) || total <= 0) && sum > 0) {
    sec.totalHours = sum;
  }
}

function getOfferingSectionClassifiedHoursTotal(sec) {
  if (!sec) return 0;
  return OFFERING_GROUP_HOUR_SUMMARY_TYPES.reduce((sum, ht) => {
    const n = Number(getOfferingSectionHoursByType(sec, ht));
    return sum + (Number.isFinite(n) ? n : 0);
  }, 0);
}

function formatNullableNumberDisplay(value) {
  return value == null || value === '' ? '—' : String(value);
}

function getOfferingSectionHoursTotalForAssign(sec) {
  return getOfferingSectionClassifiedHoursTotal(sec);
}

function finalizeCourseLevelAssignStatus(recorded, planned, hasAssignment) {
  const base = {
    planned,
    recorded,
    hasAssignment: !!hasAssignment || recorded > 0
  };
  if (!base.hasAssignment) {
    return { ...base, status: 'none', statusLabel: '未排', arrangedLabel: '未排' };
  }
  // 计划学时为 0 时仍可安排（计为超学时）；有计划时不足 / 超出均可见
  if (recorded > planned) {
    return { ...base, status: 'over', statusLabel: '超出', arrangedLabel: '已排' };
  }
  if (planned > 0 && recorded < planned) {
    return { ...base, status: 'under', statusLabel: '不足', arrangedLabel: '已排' };
  }
  return { ...base, status: 'ok', statusLabel: '达标', arrangedLabel: '已排' };
}

function buildCourseLevelAssignStatusSummary(sec, editId = '', draftHourType = '', draftHours = 0) {
  const planned = getOfferingSectionClassifiedHoursTotal(sec);
  const merged = isSectionGroupAssignHoursMerged(sec);
  if (merged) {
    let recorded = sumGroupAssignRecordedHoursByType(sec, GROUP_ASSIGN_MERGED_HOUR_TYPE, editId);
    if (draftHourType === GROUP_ASSIGN_MERGED_HOUR_TYPE) recorded += draftHours;
    const hasAssignment = (sec.groupAssignments || []).some(row =>
      row.hourType === GROUP_ASSIGN_MERGED_HOUR_TYPE && (!editId || row.id !== editId)
    ) || draftHours > 0;
    return finalizeCourseLevelAssignStatus(recorded, planned, hasAssignment);
  }
  const types = getSectionGroupAssignModeHourTypes(sec).filter(ht => ht !== GROUP_ASSIGN_MERGED_HOUR_TYPE);
  if (!types.length) return finalizeCourseLevelAssignStatus(0, planned, false);
  let anyOver = false;
  let anyUnder = false;
  let totalRecorded = 0;
  let hasAnyAssignment = false;
  types.forEach(ht => {
    let recorded = sumGroupAssignRecordedHoursByType(sec, ht, editId);
    if (ht === draftHourType) recorded += draftHours;
    const typePlanned = getGroupAssignHourTypeTotal(sec, ht);
    totalRecorded += recorded;
    if (recorded > 0) hasAnyAssignment = true;
    if (recorded > typePlanned) anyOver = true;
    else if (typePlanned > 0 && recorded < typePlanned) anyUnder = true;
  });
  if (!hasAnyAssignment && draftHours <= 0) {
    return finalizeCourseLevelAssignStatus(0, planned, false);
  }
  if (anyOver) {
    return { planned, recorded: totalRecorded, hasAssignment: true, status: 'over', statusLabel: '超出', arrangedLabel: '已排' };
  }
  if (anyUnder) {
    return { planned, recorded: totalRecorded, hasAssignment: true, status: 'under', statusLabel: '不足', arrangedLabel: '已排' };
  }
  return { planned, recorded: totalRecorded, hasAssignment: true, status: 'ok', statusLabel: '达标', arrangedLabel: '已排' };
}

function getGroupAssignCourseLevelStatus(recorded, planned) {
  if (recorded > planned) return { key: 'over', label: '超出' };
  if (planned > 0 && recorded < planned) return { key: 'under', label: '不足' };
  return { key: 'ok', label: '达标' };
}

function buildGroupAssignCourseLevelRows(sec, editId = '', draftHourType = '', draftHours = 0) {
  const merged = isSectionGroupAssignHoursMerged(sec);
  const hourTypes = merged ? [GROUP_ASSIGN_MERGED_HOUR_TYPE] : [draftHourType].filter(Boolean);
  return hourTypes.map(hourType => {
    const planned = getGroupAssignHourTypeTotal(sec, hourType);
    const saved = sumGroupAssignRecordedHoursByType(sec, hourType, editId);
    const recorded = saved + (hourType === draftHourType ? (Number(draftHours) || 0) : 0);
    const remaining = Math.max(0, planned - recorded);
    const status = getGroupAssignCourseLevelStatus(recorded, planned);
    return { hourType, planned, recorded, remaining, status };
  });
}

function getGroupAssignCourseLevelAggregateStatus(rows) {
  if (rows.some(row => row.status.key === 'over')) return { key: 'over', label: '超出' };
  if (rows.some(row => row.status.key === 'under')) return { key: 'under', label: '不足' };
  return { key: rows.length ? 'ok' : 'none', label: rows.length ? '达标' : '未排' };
}

function renderGroupAssignCourseLevelDisplayHtml(sec, rows) {
  if (!rows.length) return '<span class="text-muted">暂无学时类型</span>';
  const courseLabel = sec?.name || '课程班';
  return `<div class="table-scroll group-assign-course-level-table-wrap">
    <table class="data-table compact group-assign-course-level-table">
      <thead><tr>
        <th>课程班</th>
        <th class="col-center">学时类型</th>
        <th class="col-center">已录入学时</th>
        <th class="col-center">剩余学时</th>
        <th class="col-center">状态</th>
      </tr></thead>
      <tbody>${rows.map(row => `<tr>
        <td title="${escapeHtml(courseLabel)}">${escapeHtml(courseLabel)}</td>
        <td class="col-center">${escapeHtml(getGroupAssignHourTypeDisplayLabel(sec, row.hourType))}</td>
        <td class="col-center"><span class="group-assign-group-pick-hours is-${row.status.key === 'over' ? 'over' : row.status.key === 'under' ? 'under' : 'full'}">${row.recorded}/${row.planned}</span></td>
        <td class="col-center"><span class="group-assign-group-pick-hours is-${row.status.key === 'over' ? 'over' : row.status.key === 'under' ? 'under' : 'full'}">${row.remaining}</span></td>
        <td class="col-center"><span class="offering-group-status-badge is-${row.status.key}">${escapeHtml(row.status.label)}</span></td>
      </tr>`).join('')}</tbody>
    </table>
  </div>`;
}

function syncGroupAssignCourseLevelDisplay(sec = getOfferingGroupingSection()) {
  const el = document.getElementById('group-assign-course-level-display');
  const courseWrap = document.getElementById('group-assign-course-level-wrap');
  if (!el || !sec || (sec.groups || []).length) return;
  const editId = document.getElementById('group-assign-edit-id')?.value || '';
  const hourType = getGroupAssignFormHourType(sec);
  const weeklyHours = parseGroupAssignWeeklyHoursInput();
  const weekRange = document.getElementById('group-assign-week-range')?.value.trim() || '';
  const draftHours = weeklyHours != null && weeklyHours > 0
    ? calcGroupAssignRowHours(weeklyHours, weekRange, sec)
    : 0;
  const rows = buildGroupAssignCourseLevelRows(sec, editId, hourType, draftHours);
  const summary = getGroupAssignCourseLevelAggregateStatus(rows);
  el.className = `group-assign-course-level-display is-status-${summary.key}`;
  el.innerHTML = renderGroupAssignCourseLevelDisplayHtml(sec, rows);
  if (courseWrap) courseWrap.dataset.status = summary.key;
}

function ensureSectionGroupAssignHoursMode(sec) {
  if (!sec) return;
  const validModes = new Set([
    GROUP_ASSIGN_HOURS_MODE_ALL,
    GROUP_ASSIGN_HOURS_MODE_PARTIAL,
    GROUP_ASSIGN_HOURS_MODE_SEPARATE
  ]);
  if (validModes.has(sec.groupAssignHoursMode)) {
    sec.mergeGroupAssignHours = sec.groupAssignHoursMode === GROUP_ASSIGN_HOURS_MODE_ALL;
    if (sec.groupAssignHoursMode === GROUP_ASSIGN_HOURS_MODE_PARTIAL) {
      ensureSectionGroupAssignPartialMergeGroups(sec);
      migrateLegacyPartialMergedAssignmentHourTypes(sec);
    }
    return;
  }
  const rows = sec.groupAssignments || [];
  if (sec.mergeGroupAssignHours === true || rows.some(a => a.hourType === GROUP_ASSIGN_MERGED_HOUR_TYPE)) {
    sec.groupAssignHoursMode = GROUP_ASSIGN_HOURS_MODE_ALL;
  } else if (rows.some(a => isGroupAssignPartialMergedHourType(a.hourType))) {
    sec.groupAssignHoursMode = GROUP_ASSIGN_HOURS_MODE_PARTIAL;
    ensureSectionGroupAssignPartialMergeGroups(sec);
    migrateLegacyPartialMergedAssignmentHourTypes(sec);
  } else if (sec.mergeGroupAssignHours === false || rows.length) {
    sec.groupAssignHoursMode = GROUP_ASSIGN_HOURS_MODE_SEPARATE;
  } else {
    sec.groupAssignHoursMode = GROUP_ASSIGN_HOURS_MODE_DEFAULT;
  }
  sec.mergeGroupAssignHours = sec.groupAssignHoursMode === GROUP_ASSIGN_HOURS_MODE_ALL;
}

function getSectionGroupAssignHoursMode(sec) {
  ensureSectionGroupAssignHoursMode(sec);
  return sec?.groupAssignHoursMode || GROUP_ASSIGN_HOURS_MODE_DEFAULT;
}

function setSectionGroupAssignHoursMode(sec, mode, partialMergeGroups) {
  if (!sec) return;
  const next = mode === GROUP_ASSIGN_HOURS_MODE_PARTIAL || mode === GROUP_ASSIGN_HOURS_MODE_SEPARATE
    ? mode
    : GROUP_ASSIGN_HOURS_MODE_ALL;
  sec.groupAssignHoursMode = next;
  sec.mergeGroupAssignHours = next === GROUP_ASSIGN_HOURS_MODE_ALL;
  if (next === GROUP_ASSIGN_HOURS_MODE_PARTIAL) {
    sec.groupAssignPartialMergeGroups = normalizeSectionGroupAssignPartialMergeGroups(
      partialMergeGroups ?? sec.groupAssignPartialMergeGroups ?? sec.groupAssignPartialMergeTypes
    );
    ensureSectionGroupAssignPartialMergeGroups(sec);
    delete sec.groupAssignPartialMergeTypes;
  }
}

function isSectionGroupAssignHoursMerged(sec) {
  return getSectionGroupAssignHoursMode(sec) === GROUP_ASSIGN_HOURS_MODE_ALL;
}

function isSectionGroupAssignHoursPartial(sec) {
  return getSectionGroupAssignHoursMode(sec) === GROUP_ASSIGN_HOURS_MODE_PARTIAL;
}

function isSectionGroupAssignHoursModeLocked(sec) {
  return (sec?.groupAssignments || []).length > 0;
}

function resetSectionGroupAssignHoursModeIfEmpty(sec) {
  if (!sec || (sec.groupAssignments || []).length) return;
  delete sec.mergeGroupAssignHours;
  delete sec.groupAssignHoursMode;
  delete sec.groupAssignPartialMergeTypes;
  delete sec.groupAssignPartialMergeGroups;
}

function isGroupAssignPartialMergedHourType(hourType) {
  if (!hourType) return false;
  if (hourType === GROUP_ASSIGN_PARTIAL_MERGED_HOUR_TYPE
    || hourType === GROUP_ASSIGN_PARTIAL_MERGED_HOUR_TYPE_LEGACY) return true;
  return /^部分合并学时（.+）$/.test(String(hourType));
}

function normalizeSectionGroupAssignPartialMergeTypes(types) {
  const selected = new Set(
    (Array.isArray(types) ? types : []).filter(ht => OFFERING_GROUP_HOUR_SUMMARY_TYPES.includes(ht))
  );
  return OFFERING_GROUP_HOUR_SUMMARY_TYPES.filter(ht => selected.has(ht));
}

function normalizeSectionGroupAssignPartialMergeGroups(groups) {
  const used = new Set();
  const result = [];
  const input = Array.isArray(groups) && groups.length && typeof groups[0] === 'string'
    ? [groups]
    : (Array.isArray(groups) ? groups : []);
  input.forEach(group => {
    const normalized = normalizeSectionGroupAssignPartialMergeTypes(group)
      .filter(ht => !used.has(ht));
    if (normalized.length < 2) return;
    normalized.forEach(ht => used.add(ht));
    result.push(normalized);
  });
  return result;
}

function ensureSectionGroupAssignPartialMergeGroups(sec) {
  if (!sec) return GROUP_ASSIGN_PARTIAL_MERGE_GROUPS_DEFAULT.map(g => g.slice());
  let groups = normalizeSectionGroupAssignPartialMergeGroups(
    sec.groupAssignPartialMergeGroups ?? sec.groupAssignPartialMergeTypes
  );
  if (!groups.length) groups = GROUP_ASSIGN_PARTIAL_MERGE_GROUPS_DEFAULT.map(g => g.slice());
  sec.groupAssignPartialMergeGroups = groups;
  delete sec.groupAssignPartialMergeTypes;
  return sec.groupAssignPartialMergeGroups;
}

function getSectionGroupAssignPartialMergeGroups(sec) {
  return ensureSectionGroupAssignPartialMergeGroups(sec);
}

function getSectionGroupAssignPartialSeparateTypes(sec) {
  const merged = new Set(getSectionGroupAssignPartialMergeGroups(sec).flat());
  return OFFERING_GROUP_HOUR_SUMMARY_TYPES.filter(ht => !merged.has(ht));
}

function formatGroupAssignPartialMergeHourTypeShort(types) {
  const ordered = normalizeSectionGroupAssignPartialMergeTypes(types);
  return ordered.map(ht => String(ht).replace(/学时$/, '')).join('、');
}

function buildGroupAssignPartialMergeHourType(types) {
  const short = formatGroupAssignPartialMergeHourTypeShort(types);
  return short
    ? `${GROUP_ASSIGN_PARTIAL_MERGED_HOUR_TYPE}（${short}）`
    : GROUP_ASSIGN_PARTIAL_MERGED_HOUR_TYPE;
}

function parseGroupAssignPartialMergeHourTypeSources(hourType) {
  if (hourType === GROUP_ASSIGN_PARTIAL_MERGED_HOUR_TYPE_LEGACY
    || hourType === GROUP_ASSIGN_PARTIAL_MERGED_HOUR_TYPE) {
    return GROUP_ASSIGN_PARTIAL_MERGE_TYPES_DEFAULT.slice();
  }
  const m = String(hourType || '').match(/^部分合并学时（(.+)）$/);
  if (!m) return null;
  const parts = m[1].split('、').map(s => s.trim()).filter(Boolean);
  const mapped = parts.map(part => (
    OFFERING_GROUP_HOUR_SUMMARY_TYPES.find(ht =>
      ht === part || ht === `${part}学时` || String(ht).replace(/学时$/, '') === part
    )
  )).filter(Boolean);
  return normalizeSectionGroupAssignPartialMergeTypes(mapped);
}

function getSectionGroupAssignPartialMergeSourcesForHourType(sec, hourType) {
  const parsed = parseGroupAssignPartialMergeHourTypeSources(hourType);
  if (parsed?.length) return parsed;
  const groups = getSectionGroupAssignPartialMergeGroups(sec);
  if (groups.length === 1 && (
    hourType === GROUP_ASSIGN_PARTIAL_MERGED_HOUR_TYPE
    || hourType === GROUP_ASSIGN_PARTIAL_MERGED_HOUR_TYPE_LEGACY
  )) {
    return groups[0].slice();
  }
  return [];
}

function migrateLegacyPartialMergedAssignmentHourTypes(sec) {
  // 勿调用 isSectionGroupAssignHoursPartial：其经 getSectionGroupAssignHoursMode
  // 会再次进入 ensureSectionGroupAssignHoursMode，形成无限递归。
  if (!sec || sec.groupAssignHoursMode !== GROUP_ASSIGN_HOURS_MODE_PARTIAL) return;
  const groups = getSectionGroupAssignPartialMergeGroups(sec);
  if (groups.length !== 1) return;
  const key = buildGroupAssignPartialMergeHourType(groups[0]);
  (sec.groupAssignments || []).forEach(row => {
    if (row.hourType === GROUP_ASSIGN_PARTIAL_MERGED_HOUR_TYPE
      || row.hourType === GROUP_ASSIGN_PARTIAL_MERGED_HOUR_TYPE_LEGACY) {
      row.hourType = key;
    }
  });
}

function getSectionGroupAssignPartialMergedHours(sec, hourTypeOrTypes) {
  const types = Array.isArray(hourTypeOrTypes)
    ? normalizeSectionGroupAssignPartialMergeTypes(hourTypeOrTypes)
    : getSectionGroupAssignPartialMergeSourcesForHourType(sec, hourTypeOrTypes || GROUP_ASSIGN_PARTIAL_MERGED_HOUR_TYPE);
  return types.reduce(
    (sum, ht) => sum + (Number(getOfferingSectionHoursByType(sec, ht)) || 0),
    0
  );
}

function getGroupAssignHourTypeDisplayLabel(sec, hourType) {
  if (isGroupAssignPartialMergedHourType(hourType)) {
    const sources = getSectionGroupAssignPartialMergeSourcesForHourType(sec, hourType);
    if (sources.length) return formatGroupAssignPartialMergeHourTypeShort(sources) || '—';
    const m = String(hourType || '').match(/^部分合并学时（(.+)）$/);
    if (m?.[1]) return m[1];
    return hourType || '—';
  }
  return hourType || '—';
}

/** 当前学时模式下用于安排/校验/展示的学时类型列表 */
function getSectionGroupAssignModeHourTypes(sec) {
  const mode = getSectionGroupAssignHoursMode(sec);
  if (mode === GROUP_ASSIGN_HOURS_MODE_ALL) return [GROUP_ASSIGN_MERGED_HOUR_TYPE];
  if (mode === GROUP_ASSIGN_HOURS_MODE_PARTIAL) {
    return [
      ...getSectionGroupAssignPartialMergeGroups(sec).map(buildGroupAssignPartialMergeHourType),
      ...getSectionGroupAssignPartialSeparateTypes(sec)
    ];
  }
  return getOfferingSectionArrangeableHourTypes(sec);
}

function getSectionGroupAssignRequiredModeHourTypes(sec) {
  return getSectionGroupAssignModeHourTypes(sec).filter(ht =>
    isOfferingSectionHourTypeRequiredForSubmit(sec, ht)
  );
}

function cloneGroupAssignPartialMergeGroupsDraft(groups) {
  return (groups || []).map(g => normalizeSectionGroupAssignPartialMergeTypes(g));
}

function getGroupAssignPartialMergeDraftUsedTypes(exceptIndex = -1) {
  const used = new Set();
  groupAssignPartialMergeGroupsDraft.forEach((group, idx) => {
    if (idx === exceptIndex) return;
    (group || []).forEach(ht => used.add(ht));
  });
  return used;
}

function getGroupAssignPartialMergeDraftSeparateTypes() {
  const used = getGroupAssignPartialMergeDraftUsedTypes();
  return OFFERING_GROUP_HOUR_SUMMARY_TYPES.filter(ht => !used.has(ht));
}

function syncGroupAssignPartialMergeSeparateHint() {
  const el = document.getElementById('group-assign-partial-merge-separate-hint');
  if (!el) return;
  const separate = getGroupAssignPartialMergeDraftSeparateTypes();
  el.textContent = separate.length
    ? `未入组、将单独安排：${separate.join('、')}`
    : '当前学时类型均已入组合并';
}

function renderGroupAssignPartialMergeGroupsDraft() {
  const wrap = document.getElementById('group-assign-partial-merge-groups');
  if (!wrap) return;
  const locked = groupAssignPartialMergeGroupsDraftLocked;
  if (!groupAssignPartialMergeGroupsDraft.length) {
    groupAssignPartialMergeGroupsDraft = [[]];
  }
  wrap.innerHTML = groupAssignPartialMergeGroupsDraft.map((group, groupIndex) => {
    const selected = new Set(group || []);
    const usedElsewhere = getGroupAssignPartialMergeDraftUsedTypes(groupIndex);
    const typeChecks = OFFERING_GROUP_HOUR_SUMMARY_TYPES.map(ht => {
      const checked = selected.has(ht) ? ' checked' : '';
      const taken = usedElsewhere.has(ht);
      const disabled = locked || taken ? ' disabled' : '';
      const cls = taken ? ' is-used-elsewhere' : '';
      return `<label class="group-assign-partial-merge-type${cls}">
        <input type="checkbox" class="group-assign-partial-merge-type-check"
          data-group-index="${groupIndex}" value="${escapeHtml(ht)}"${checked}${disabled}
          onchange="onGroupAssignPartialMergeTypeToggle(${groupIndex}, '${escapeHtml(ht)}', this.checked)">
        <span>${escapeHtml(ht)}</span>
      </label>`;
    }).join('');
    const removeBtn = locked || groupAssignPartialMergeGroupsDraft.length <= 1
      ? ''
      : `<button type="button" class="btn btn-ghost btn-sm btn-danger-text" onclick="removeGroupAssignPartialMergeGroupDraft(${groupIndex})">删除</button>`;
    return `<div class="group-assign-partial-merge-group" data-group-index="${groupIndex}">
      <div class="group-assign-partial-merge-group-head">
        <span class="group-assign-partial-merge-group-title">合并组 ${groupIndex + 1}</span>
        ${removeBtn}
      </div>
      <div class="group-assign-partial-merge-group-types">${typeChecks}</div>
    </div>`;
  }).join('');
  const addBtn = document.getElementById('group-assign-partial-merge-add-group');
  if (addBtn) {
    const free = getGroupAssignPartialMergeDraftSeparateTypes().length;
    addBtn.disabled = locked || free < 2;
    addBtn.title = free < 2 ? '至少还需 2 种未入组学时才能新增合并组' : '添加合并组';
  }
  syncGroupAssignPartialMergeSeparateHint();
}

function onGroupAssignPartialMergeTypeToggle(groupIndex, hourType, checked) {
  if (groupAssignPartialMergeGroupsDraftLocked) return;
  if (!OFFERING_GROUP_HOUR_SUMMARY_TYPES.includes(hourType)) return;
  const group = groupAssignPartialMergeGroupsDraft[groupIndex];
  if (!group) return;
  const set = new Set(group);
  if (checked) {
    // 同一类型只能属于一组
    groupAssignPartialMergeGroupsDraft.forEach((g, idx) => {
      if (idx === groupIndex) return;
      groupAssignPartialMergeGroupsDraft[idx] = g.filter(ht => ht !== hourType);
    });
    set.add(hourType);
  } else {
    set.delete(hourType);
  }
  groupAssignPartialMergeGroupsDraft[groupIndex] = OFFERING_GROUP_HOUR_SUMMARY_TYPES.filter(ht => set.has(ht));
  renderGroupAssignPartialMergeGroupsDraft();
}

function addGroupAssignPartialMergeGroupDraft() {
  if (groupAssignPartialMergeGroupsDraftLocked) return;
  if (getGroupAssignPartialMergeDraftSeparateTypes().length < 2) {
    alert('至少还需 2 种未入组学时才能新增合并组。');
    return;
  }
  groupAssignPartialMergeGroupsDraft.push([]);
  renderGroupAssignPartialMergeGroupsDraft();
}

function removeGroupAssignPartialMergeGroupDraft(groupIndex) {
  if (groupAssignPartialMergeGroupsDraftLocked) return;
  if (groupAssignPartialMergeGroupsDraft.length <= 1) return;
  groupAssignPartialMergeGroupsDraft.splice(groupIndex, 1);
  renderGroupAssignPartialMergeGroupsDraft();
}

function syncGroupAssignHourTypeSettingsPartialPicks() {
  const wrap = document.getElementById('group-assign-partial-merge-types-wrap');
  if (!wrap) return;
  const mode = document.querySelector('input[name="group-assign-hours-mode"]:checked')?.value;
  wrap.hidden = mode !== GROUP_ASSIGN_HOURS_MODE_PARTIAL;
  if (mode === GROUP_ASSIGN_HOURS_MODE_PARTIAL) {
    if (!groupAssignPartialMergeGroupsDraft.length) {
      groupAssignPartialMergeGroupsDraft = [[]];
    }
    renderGroupAssignPartialMergeGroupsDraft();
  }
}

function openGroupAssignHourTypeSettings() {
  const sec = getOfferingGroupingSection();
  if (!sec) return;
  if (!assertOfferingGroupingEditable('学时类型设置')) return;
  ensureSectionGroupAssignHoursMode(sec);
  const mode = getSectionGroupAssignHoursMode(sec);
  const locked = isSectionGroupAssignHoursModeLocked(sec);
  groupAssignPartialMergeGroupsDraftLocked = locked;
  const savedGroups = Array.isArray(sec.groupAssignPartialMergeGroups)
    ? sec.groupAssignPartialMergeGroups
    : null;
  groupAssignPartialMergeGroupsDraft = (mode === GROUP_ASSIGN_HOURS_MODE_PARTIAL && savedGroups?.length)
    ? cloneGroupAssignPartialMergeGroupsDraft(savedGroups)
    : [[]];
  document.querySelectorAll('input[name="group-assign-hours-mode"]').forEach(el => {
    el.checked = el.value === mode;
    el.disabled = locked;
  });
  syncGroupAssignHourTypeSettingsPartialPicks();
  const hintEl = document.getElementById('group-assign-hour-type-settings-hint');
  if (hintEl) {
    hintEl.textContent = locked
      ? '已安排教师后不可修改；如需调整请先删除全部教师安排后重新设置。'
      : '设置本课程安排教师时的学时合并方式。可建多组合并（如理论+实践、辅导+其他）；保存后安排教师将按此设定进行。';
  }
  const saveBtn = document.getElementById('group-assign-hour-type-settings-save');
  if (saveBtn) saveBtn.disabled = locked;
  openModal('modal-group-assign-hour-type-settings');
}

function saveGroupAssignHourTypeSettings() {
  const sec = getOfferingGroupingSection();
  if (!sec) return;
  if (isSectionGroupAssignHoursModeLocked(sec)) {
    alert('已安排教师后不可修改学时类型设置；如需调整请先删除全部教师安排。');
    return;
  }
  const checked = document.querySelector('input[name="group-assign-hours-mode"]:checked');
  const mode = checked?.value || GROUP_ASSIGN_HOURS_MODE_DEFAULT;
  if (mode === GROUP_ASSIGN_HOURS_MODE_PARTIAL) {
    const groups = normalizeSectionGroupAssignPartialMergeGroups(groupAssignPartialMergeGroupsDraft);
    if (!groups.length) {
      alert('请至少配置 1 个合并组，且每组至少勾选 2 种学时类型。');
      return;
    }
    const incomplete = groupAssignPartialMergeGroupsDraft.some(g =>
      normalizeSectionGroupAssignPartialMergeTypes(g).length > 0
      && normalizeSectionGroupAssignPartialMergeTypes(g).length < 2
    );
    if (incomplete) {
      alert('每个合并组请至少勾选 2 种学时类型，或删除空组/不足两组。');
      return;
    }
    setSectionGroupAssignHoursMode(sec, mode, groups);
  } else {
    setSectionGroupAssignHoursMode(sec, mode);
  }
  closeModal('modal-group-assign-hour-type-settings');
  renderOfferingGroupingPanel();
  // switchOfferingGroupingTab('teacher'); // 原保存后强制切到教师安排 Tab
  syncOfferingGroupingTeacherToolbar(sec);
  renderCourseOfferingMajorPage();
}

function getGroupAssignFormHourType(sec) {
  if (isSectionGroupAssignHoursMerged(sec)) return GROUP_ASSIGN_MERGED_HOUR_TYPE;
  const modeTypes = getSectionGroupAssignModeHourTypes(sec);
  const selected = getGroupAssignSelectedHourType();
  if (selected && modeTypes.includes(selected)) return selected;
  return modeTypes[0] || '';
}

function isGroupAssignFormHourTypeValid(sec, hourType) {
  if (!sec || !hourType) return false;
  if (isSectionGroupAssignHoursMerged(sec)) return hourType === GROUP_ASSIGN_MERGED_HOUR_TYPE;
  return getSectionGroupAssignModeHourTypes(sec).includes(hourType);
}

function getGroupAssignHourTypeTotal(sec, hourType) {
  if (hourType === GROUP_ASSIGN_MERGED_HOUR_TYPE) return getOfferingSectionHoursTotalForAssign(sec);
  if (isGroupAssignPartialMergedHourType(hourType)) return getSectionGroupAssignPartialMergedHours(sec, hourType);
  return Number(getOfferingSectionHoursByType(sec, hourType)) || 0;
}

function isGroupAssignRowActive(sec, row) {
  if (!row?.hourType) return false;
  if (isSectionGroupAssignHoursMerged(sec)) return row.hourType === GROUP_ASSIGN_MERGED_HOUR_TYPE;
  if (isSectionGroupAssignHoursPartial(sec)) {
    const modeTypes = getSectionGroupAssignModeHourTypes(sec);
    if (modeTypes.includes(row.hourType)) return true;
    if (!isGroupAssignPartialMergedHourType(row.hourType)) return false;
    const rebuilt = buildGroupAssignPartialMergeHourType(
      getSectionGroupAssignPartialMergeSourcesForHourType(sec, row.hourType)
    );
    return modeTypes.includes(rebuilt);
  }
  return isOfferingSectionHourTypeArrangeable(sec, row.hourType)
    && OFFERING_GROUP_HOUR_SUMMARY_TYPES.includes(row.hourType);
}

function filterActiveGroupAssignments(sec, assignments) {
  return (assignments || []).filter(row => isGroupAssignRowActive(sec, row));
}

function canSectionArrangeGroupAssignTeachers(sec) {
  if (!sec) return false;
  // 学时全 0 也可安排教师（允许超学时）；不再要求计划学时 > 0
  return true;
  // if (isSectionGroupAssignHoursMerged(sec)) return getOfferingSectionHoursTotalForAssign(sec) > 0;
  // return getOfferingSectionArrangeableHourTypes(sec).length > 0;
}

function syncGroupAssignHourTypeModeUI() {
  const sec = getOfferingGroupingSection();
  const hourTypeWrap = document.getElementById('group-assign-hour-type-wrap');
  const typeTotalLabel = document.getElementById('group-assign-type-total-label');
  const merged = isSectionGroupAssignHoursMerged(sec);
  if (hourTypeWrap) {
    hourTypeWrap.hidden = merged;
    hourTypeWrap.querySelectorAll('.group-assign-hour-type-radio').forEach(el => {
      el.disabled = merged;
    });
  }
  if (merged) {
    document.getElementById('group-assign-hour-type-picks') && (document.getElementById('group-assign-hour-type-picks').innerHTML = '');
  } else if (sec) {
    populateGroupAssignHourTypePicks(sec, getGroupAssignSelectedHourType());
  }
  if (typeTotalLabel) {
    typeTotalLabel.textContent = merged
      ? '课程总学时'
      : (isSectionGroupAssignHoursPartial(sec) ? '该合并类型学时总数' : '该类型学时总数');
  }
  syncGroupAssignHoursSummary();
  syncGroupAssignCourseLevelDisplay(sec);
}

/** @deprecated 兼容旧调用，改走 syncGroupAssignHourTypeModeUI */
function syncGroupAssignMergeHoursMode() {
  syncGroupAssignHourTypeModeUI();
}

function getGroupAssignSelectedHourType() {
  const checked = document.querySelector('.group-assign-hour-type-radio:checked:not(:disabled)');
  return checked?.value || '';
}

function setGroupAssignSelectedHourType(value) {
  let matched = false;
  document.querySelectorAll('.group-assign-hour-type-radio').forEach(el => {
    const selected = el.value === value && !el.disabled;
    el.checked = selected;
    el.closest('tr')?.classList.toggle('is-selected', selected);
    if (selected) matched = true;
  });
  if (!matched) {
    const first = document.querySelector('.group-assign-hour-type-radio:not(:disabled)');
    if (first) {
      first.checked = true;
      first.closest('tr')?.classList.add('is-selected');
    }
  }
}

function populateGroupAssignHourTypePicks(sec, selectedHourType) {
  const wrap = document.getElementById('group-assign-hour-type-picks');
  if (!wrap || !sec) return;
  if (isSectionGroupAssignHoursMerged(sec)) {
    wrap.innerHTML = '';
    return;
  }
  const pickTypes = getSectionGroupAssignModeHourTypes(sec);
  const current = selectedHourType && pickTypes.includes(selectedHourType)
    ? selectedHourType
    : (pickTypes[0] || '');
  const rows = pickTypes.map(ht => {
    const enabled = isOfferingSectionHourTypeArrangeable(sec, ht);
    const hours = getGroupAssignHourTypeTotal(sec, ht) ?? 0;
    const checked = ht === current && enabled ? ' checked' : '';
    const disabled = enabled ? '' : ' disabled';
    const rowClass = enabled ? '' : ' is-disabled';
    const selectedClass = ht === current && enabled ? ' is-selected' : '';
    return `<tr class="group-assign-hour-type-row${rowClass}${selectedClass}" data-hour-type="${escapeHtml(ht)}" onclick="selectGroupAssignHourTypeRow(event, this.dataset.hourType)">
      <td class="col-check" onclick="event.stopPropagation()">
        <input type="radio" class="group-assign-hour-type-radio" name="group-assign-hour-type" value="${escapeHtml(ht)}" data-hour-type="${escapeHtml(ht)}"${checked}${disabled} onchange="syncGroupAssignHoursByType()">
      </td>
      <td>${escapeHtml(getGroupAssignHourTypeDisplayLabel(sec, ht))}</td>
      <td class="col-center">${hours}</td>
    </tr>`;
  }).join('');
  wrap.innerHTML = `<div class="table-scroll group-assign-hour-type-picks-table-wrap">
    <table class="data-table compact group-assign-hour-type-picks-table">
      <thead><tr>
        <th class="col-check"></th>
        <th>学时类型</th>
        <th class="col-center">课程学时</th>
      </tr></thead>
      <tbody>${rows}</tbody>
    </table>
  </div>`;
  if (current) setGroupAssignSelectedHourType(current);
}

function selectGroupAssignHourTypeRow(ev, hourType) {
  if (isSectionGroupAssignHoursMerged(getOfferingGroupingSection())) return;
  if (ev?.target?.closest?.('input, button, a, label')) return;
  const target = String(hourType || '');
  const radio = [...document.querySelectorAll('.group-assign-hour-type-radio:not(:disabled)')]
    .find(el => el.value === target || el.dataset.hourType === target);
  if (!radio) return;
  radio.checked = true;
  syncGroupAssignHoursByType();
}

function ensureGroupAssignWeekPickerGrid(maxWeek) {
  const grid = document.getElementById('group-assign-week-picker-grid');
  if (!grid) return;
  const limit = maxWeek || groupAssignWeekPickerMaxWeek || MAJOR_OFFERING_MAX_WEEKS;
  if (grid.dataset.built === '1' && Number(grid.dataset.maxWeeks) === limit) {
    updateGroupAssignWeekPickerCellStates();
    return;
  }
  grid.innerHTML = Array.from({ length: limit }, (_, i) => {
    const week = i + 1;
    return `<button type="button" class="week-picker-cell" data-week="${week}" onclick="toggleGroupAssignWeekCell(${week})">${week}</button>`;
  }).join('');
  grid.dataset.built = '1';
  grid.dataset.maxWeeks = String(limit);
  updateGroupAssignWeekPickerCellStates();
}

function updateGroupAssignWeekPickerCellStates() {
  const allowed = groupAssignWeekPickerAllowedWeeks;
  document.querySelectorAll('#group-assign-week-picker-grid .week-picker-cell').forEach(el => {
    const week = Number(el.dataset.week);
    const isAllowed = !allowed || allowed.has(week);
    el.classList.toggle('is-disabled', !isAllowed);
    el.disabled = !isAllowed;
    if (!isAllowed) groupAssignWeekRangeDraft.delete(week);
    el.classList.toggle('selected', groupAssignWeekRangeDraft.has(week));
  });
}

function syncGroupAssignWeekRangeFromDraft(updateDisplay = true) {
  const displayEl = document.getElementById('group-assign-week-range');
  if (updateDisplay && displayEl && document.activeElement !== displayEl) {
    displayEl.value = formatWeeksSegmentDisplay([...groupAssignWeekRangeDraft].sort((a, b) => a - b));
    displayEl.classList.remove('is-invalid');
  }
  updateGroupAssignWeekPickerCellStates();
  if (updateDisplay) {
    document.querySelectorAll('input[name="group-assign-week-preset"]').forEach(el => { el.checked = false; });
  }
}

function initGroupAssignInlineWeekPicker(sec, currentValue = '') {
  const sectionWeeks = getSectionSelectedWeeks(sec);
  const allowedWeeks = sectionWeeks.length ? sectionWeeks : getDefaultSectionSelectedWeeks(sec);
  groupAssignWeekPickerMaxWeek = getSectionTermTeachingWeeks(sec);
  groupAssignWeekPickerAllowedWeeks = new Set(allowedWeeks);
  const clamped = clampGroupAssignWeekRangeToSection(sec, currentValue || sec?.weekRange || getDefaultSectionWeekRange(sec));
  if (clamped && isValidWeekRangeInput(clamped)) {
    groupAssignWeekRangeDraft = new Set(
      clampWeeksToAllowed(parseWeekRangeToWeeks(clamped, groupAssignWeekPickerMaxWeek), groupAssignWeekPickerAllowedWeeks)
    );
  } else {
    groupAssignWeekRangeDraft = new Set(allowedWeeks);
  }
  ensureGroupAssignWeekPickerGrid(groupAssignWeekPickerMaxWeek);
  syncGroupAssignWeekRangeFromDraft();
}

function toggleGroupAssignWeekCell(week) {
  if (groupAssignWeekPickerAllowedWeeks && !groupAssignWeekPickerAllowedWeeks.has(week)) return;
  if (groupAssignWeekRangeDraft.has(week)) groupAssignWeekRangeDraft.delete(week);
  else groupAssignWeekRangeDraft.add(week);
  syncGroupAssignWeekRangeFromDraft();
}

function applyGroupAssignWeekRangePreset(preset) {
  groupAssignWeekRangeDraft = new Set();
  const allowed = groupAssignWeekPickerAllowedWeeks;
  const maxWeek = groupAssignWeekPickerMaxWeek || MAJOR_OFFERING_MAX_WEEKS;
  for (let w = 1; w <= maxWeek; w++) {
    if (allowed && !allowed.has(w)) continue;
    if (preset === 'all') groupAssignWeekRangeDraft.add(w);
    else if (preset === 'odd' && w % 2 === 1) groupAssignWeekRangeDraft.add(w);
    else if (preset === 'even' && w % 2 === 0) groupAssignWeekRangeDraft.add(w);
  }
  syncGroupAssignWeekRangeFromDraft();
  syncGroupAssignHoursSummary();
}

function clearGroupAssignWeekRangeDraft() {
  groupAssignWeekRangeDraft = new Set();
  syncGroupAssignWeekRangeFromDraft();
  syncGroupAssignHoursSummary();
}

function onGroupAssignWeekRangeInput() {
  const el = document.getElementById('group-assign-week-range');
  if (!el) return;
  const raw = el.value.trim();
  if (!raw) {
    groupAssignWeekRangeDraft = new Set();
    el.classList.remove('is-invalid');
    syncGroupAssignWeekRangeFromDraft(false);
    document.querySelectorAll('input[name="group-assign-week-preset"]').forEach(r => { r.checked = false; });
    syncGroupAssignHoursSummary();
    return;
  }
  if (!isValidWeekRangeInput(raw)) {
    el.classList.add('is-invalid');
    return;
  }
  el.classList.remove('is-invalid');
  groupAssignWeekRangeDraft = new Set(
    clampWeeksToAllowed(
      parseWeekRangeToWeeks(raw, groupAssignWeekPickerMaxWeek),
      groupAssignWeekPickerAllowedWeeks
    )
  );
  document.querySelectorAll('input[name="group-assign-week-preset"]').forEach(r => { r.checked = false; });
  syncGroupAssignWeekRangeFromDraft(false);
  syncGroupAssignHoursSummary();
}

function onGroupAssignWeekRangeInputBlur() {
  const el = document.getElementById('group-assign-week-range');
  if (!el) return;
  const raw = el.value.trim();
  if (!raw || !isValidWeekRangeInput(raw)) return;
  el.value = formatWeeksSegmentDisplay(parseWeekRangeToWeeks(raw, groupAssignWeekPickerMaxWeek));
}

function syncGroupAssignFormScopeFields(sec = getOfferingGroupingSection()) {
  const hasGroups = !!(sec?.groups?.length);
  const groupsWrap = document.getElementById('group-assign-groups-wrap');
  const courseWrap = document.getElementById('group-assign-course-level-wrap');
  if (groupsWrap) groupsWrap.hidden = !hasGroups;
  if (courseWrap) courseWrap.hidden = hasGroups;
  syncGroupAssignCourseLevelDisplay(sec);
}

function scheduleGroupAssignHoursSummarySync() {
  if (groupAssignHoursSummarySyncTimer) clearTimeout(groupAssignHoursSummarySyncTimer);
  groupAssignHoursSummarySyncTimer = setTimeout(() => {
    groupAssignHoursSummarySyncTimer = null;
    syncGroupAssignHoursSummary();
  }, 0);
}

function syncGroupAssignHoursSummary() {
  const sec = getOfferingGroupingSection();
  const hourType = getGroupAssignFormHourType(sec);
  const editIdEl = document.getElementById('group-assign-edit-id');
  const weekRangeEl = document.getElementById('group-assign-week-range');
  const planEl = document.getElementById('group-assign-plan-weekly-hours');
  const typeTotalEl = document.getElementById('group-assign-type-total-hours');
  const recordedEl = document.getElementById('group-assign-recorded-hours');
  const recordedWarnEl = document.getElementById('group-assign-recorded-hours-warn');
  const recordedField = recordedEl?.closest('.form-field');
  // const hintEl = document.getElementById('group-assign-recorded-hours-hint'); // 原独立 hint，已合并至输入框
  const warnEl = document.getElementById('group-assign-weekly-warn');
  const weeklyField = document.getElementById('group-assign-weekly-hours')?.closest('.form-field');

  const editId = editIdEl?.value || '';
  const planWeekly = sec ? getGroupAssignPlanWeeklyHours(sec) : 0;
  const typeTotal = sec ? getGroupAssignHourTypeTotal(sec, hourType) : 0;
  // const recorded = sec ? sumGroupAssignRecordedHoursByType(sec, hourType, editId) : 0; // 原按课程汇总，无法体现各组已录入学时差异
  const weeklyHours = parseGroupAssignWeeklyHoursInput();
  const weekRange = weekRangeEl?.value.trim() || '';
  const currentHours = sec && weeklyHours != null && weeklyHours > 0
    ? calcGroupAssignRowHours(weeklyHours, weekRange, sec)
    : 0;
  const groupSummaries = buildGroupAssignRecordedHoursSummaries(sec, hourType, editId, currentHours);

  if (planEl) planEl.value = formatNullableNumberDisplay(planWeekly);
  if (typeTotalEl) typeTotalEl.value = formatNullableNumberDisplay(typeTotal);
  syncGroupAssignGroupPickHoursBadges(sec, hourType, editId, currentHours);
  // syncGroupAssignGroupPickHoursBadges(sec, hourType, editId); // 原未传入含本次录入学时，上方 x/30 不随周学时变化
  const overType = groupSummaries.some(s => s.over);
  const underType = !overType && groupSummaries.some(s => s.under);
  if (recordedEl) {
    recordedEl.value = formatNullableNumberDisplay(currentHours);
    // if (!groupSummaries.length) {
    //   recordedEl.value = '—';
    // } else {
    //   const fmtRecorded = s => (typeTotal ? `${s.totalAfter} / ${typeTotal}` : String(s.totalAfter));
    //   recordedEl.value = groupSummaries.length === 1
    //     ? fmtRecorded(groupSummaries[0])
    //     : groupSummaries.map(fmtRecorded).join('；');
    // } // 原展示各组含累计 x/30，改仅展示本次录入总学时（周学时 × 起止周数）
  }
  recordedField?.classList.toggle('has-recorded-exceed-warn', overType);
  recordedField?.classList.toggle('has-recorded-under-warn', underType);
  if (recordedWarnEl) {
    recordedWarnEl.classList.remove('is-over', 'is-under');
    const overLines = groupSummaries.filter(s => s.over);
    const underLines = groupSummaries.filter(s => s.under);
    if (overLines.length) {
      recordedWarnEl.classList.add('is-over');
      if (overLines.length === 1) {
        recordedWarnEl.textContent = `${overLines[0].label}：${hourType}含本次录入 ${overLines[0].totalAfter} 已超过总数 ${typeTotal}，仍可保存。`;
      } else {
        recordedWarnEl.innerHTML = [
          `以下小组${escapeHtml(hourType)}含本次录入已超过总数，仍可保存：`,
          ...overLines.map(s => `${escapeHtml(s.label)}：含本次 ${s.totalAfter}/${typeTotal}`)
        ].join('<br>');
      }
      recordedWarnEl.classList.remove('is-empty');
    } else if (underLines.length) {
      recordedWarnEl.classList.add('is-under');
      if (underLines.length === 1) {
        const s = underLines[0];
        recordedWarnEl.textContent = `${s.label}：${hourType}含本次录入 ${s.totalAfter}/${typeTotal}，尚未录满，仍可保存。`;
      } else {
        recordedWarnEl.innerHTML = [
          `以下小组${escapeHtml(hourType)}含本次录入尚未录满，仍可保存：`,
          ...underLines.map(s => `${escapeHtml(s.label)}：含本次 ${s.totalAfter}/${typeTotal}`)
        ].join('<br>');
      }
      recordedWarnEl.classList.remove('is-empty');
    } else {
      recordedWarnEl.textContent = '\u00a0';
      recordedWarnEl.classList.add('is-empty');
    }
  }
  // if (recordedEl) recordedEl.value = typeTotal ? `${recorded} / ${typeTotal}` : String(recorded); // 原仅展示已录入，与 hint 重复
  // hint 已合并至 #group-assign-recorded-hours 输入框，不再单独展示

  const planWarnSummaries = buildGroupAssignPlanWeeklyWarnSummaries(
    sec, editId, hourType, weeklyHours, weekRange
  );
  const overPlan = planWarnSummaries.length > 0;
  // const overPlan = weeklyHours != null && weeklyHours > 0 && planWeekly > 0 && weeklyHours > planWeekly; // 原仅本类型周学时比较
  weeklyField?.classList.toggle('has-plan-exceed-warn', overPlan);
  if (warnEl) {
    if (planWarnSummaries.length) {
      warnEl.textContent = formatGroupAssignPlanWeeklyWarnDisplayMessage(planWarnSummaries);
      // warnEl.textContent = formatGroupAssignPlanWeeklyWarnShortMessage(planWarnSummaries[0].planWeekly); // 原无小组名称
      warnEl.classList.remove('is-empty');
    } else {
      warnEl.textContent = '\u00a0';
      warnEl.classList.add('is-empty');
    }
    // warnEl.hidden = false; // 原 hidden 切换导致布局跳动，mousedown 在输入框、mouseup 落在遮罩时会误关弹窗
  }
  syncGroupAssignCourseLevelDisplay(sec);
  // const exceedWrap = document.getElementById('group-assign-plan-exceed-wrap'); // 原独立警示行，插入导致弹窗滚动跳动
}

function getOfferingSectionHoursByType(sec, hourType) {
  const map = {
    '理论学时': sec?.theoryHours,
    '辅导学时': sec?.tutorialHours,
    '实践学时': sec?.practiceHours,
    '其他学时': sec?.otherHours
  };
  return map[hourType];
}

function isOfferingSectionHourTypeArrangeable(sec, hourType) {
  if (!sec || !hourType) return false;
  if (hourType === GROUP_ASSIGN_MERGED_HOUR_TYPE) return true;
  if (isGroupAssignPartialMergedHourType(hourType)) return true;
  if (!OFFERING_GROUP_HOUR_SUMMARY_TYPES.includes(hourType)) return false;
  // 计划学时为 0 仍可安排（允许超学时）；原先 Number(hours) > 0 会挡住论文课等 0 学时课
  return true;
  // const hours = getOfferingSectionHoursByType(sec, hourType);
  // return hours != null && hours !== '' && Number(hours) > 0;
}

function getOfferingSectionArrangeableHourTypes(sec) {
  return OFFERING_GROUP_HOUR_SUMMARY_TYPES.filter(ht => isOfferingSectionHourTypeArrangeable(sec, ht));
}

/** 计划学时 > 0 的类型才强制齐套；0 学时可安排但不强制 */
function isOfferingSectionHourTypeRequiredForSubmit(sec, hourType) {
  if (hourType === GROUP_ASSIGN_MERGED_HOUR_TYPE || isGroupAssignPartialMergedHourType(hourType)) {
    return getGroupAssignHourTypeTotal(sec, hourType) > 0;
  }
  return (Number(getOfferingSectionHoursByType(sec, hourType)) || 0) > 0;
}

function sanitizeSectionGroupAssignments(sec) {
  if (!sec) return;
  migrateLegacySectionScopeToExplicitGroups(sec);
  ensureSectionGroupAssignHoursMode(sec);
  // normalizeGroupAssignSectionScope(sec); // 原将全选转为 section 并自动囊括后续新增小组，改仅保留保存时显式 groupIds
  if (!sec.groupAssignments?.length) return;
  sec.groupAssignments = sec.groupAssignments.filter(a =>
    isGroupAssignRowActive(sec, a)
  );
  sec.groupAssignments.forEach(row => {
    const clamped = clampGroupAssignWeekRangeToSection(sec, row.weekRange);
    if (clamped) row.weekRange = clamped;
    // if (clamped && clamped !== row.weekRange) { row.weekRange = clamped; ... } // 原仅字符串不等时修正，现统一 clamp
    if (row.weeklyHours != null && row.weeklyHours !== '') {
      row.hours = calcGroupAssignRowHours(row.weeklyHours, row.weekRange, sec);
    }
  });
}

function applyGroupAssignRowExplicitGroupIds(row, sec, groupIds) {
  if (!row || !groupIds?.length) return;
  row.groupIds = [...groupIds];
  row.deliveryScope = 'group';
  row.groupId = groupIds[0] || '';
  row._scopeGroupIdsSnapshotted = true;
  if (groupIds.length === 1) {
    const g = sec?.groups?.find(x => x.id === groupIds[0]);
    if (g) row.groupName = g.name;
  } else if (!row.groupName || row.groupName === sec?.name) {
    row.groupName = '全体小组';
  }
}

function isGroupAssignRowCourseLevelScope(row) {
  if (!row) return false;
  const ids = getGroupAssignRowGroupIds(row);
  if (row.deliveryScope === 'section' && !ids.length) return true;
  if (!ids.length && row.deliveryScope === 'group') return true;
  return false;
}

function clearCourseLevelGroupAssignmentsWhenGroupingBegins(sec, { priorGroupCount = null } = {}) {
  if (!sec?.groups?.length) return;
  if (priorGroupCount != null && priorGroupCount > 0) {
    migrateLegacySectionScopeToExplicitGroups(sec);
    return;
  }
  const hadCourseLevel = (sec.groupAssignments || []).some(r => isGroupAssignRowCourseLevelScope(r));
  if (!hadCourseLevel) {
    migrateLegacySectionScopeToExplicitGroups(sec);
    return;
  }
  sec.groupAssignments = (sec.groupAssignments || []).filter(r => !isGroupAssignRowCourseLevelScope(r));
  resetSectionGroupAssignHoursModeIfEmpty(sec);
  syncSectionCoordinatorsFromAssignments(sec);
  refreshSectionCoordinatorAfterAssignmentChange(sec);
}

function migrateLegacySectionScopeToExplicitGroups(sec) {
  const allIds = (sec?.groups || []).map(g => g.id);
  if (!allIds.length) return;
  sec.groupAssignments = (sec.groupAssignments || []).filter(row => {
    if (isGroupAssignRowCourseLevelScope(row)) return false;
    return getGroupAssignRowGroupIds(row).length > 0;
  });
  (sec.groupAssignments || []).forEach(row => {
    const ids = getGroupAssignRowGroupIds(row);
    if (row.deliveryScope !== 'section' || row._scopeGroupIdsSnapshotted) return;
    applyGroupAssignRowExplicitGroupIds(row, sec, row.groupIds?.length ? row.groupIds : ids);
  });
}

function applyGroupAssignSectionScopeRowFields(row, sec) {
  if (!row || !sec) return;
  row.deliveryScope = 'section';
  row.groupId = '';
  row.groupIds = [];
  row.groupName = '全体小组';
  row.studentCount = sec.estimatedStudents ?? 0;
  row.programmeBatch = getSectionMergedBatchLabelDisplayFull(sec);
}

function normalizeGroupAssignSectionScope(sec) {
  // const allIds = getGroupAssignFormAllGroupIds(sec); ... // 原全选转 section 并自动囊括新增小组，已停用
}

function expandGroupAssignmentsAfterGroupsAdded(sec, previousGroupIds) {
  const priorGroupCount = Array.isArray(previousGroupIds) ? previousGroupIds.length : null;
  clearCourseLevelGroupAssignmentsWhenGroupingBegins(sec, { priorGroupCount });
}

function refreshGroupAssignGroupPicksIfSelectAll(sec = getOfferingGroupingSection()) {
  // const modal = document.getElementById('modal-group-assign-form'); ... // 原全选态下新增小组自动勾选，已停用
}

function refreshGroupAssignHourTypeOptions(sec = getOfferingGroupingSection()) {
  populateGroupAssignHourTypePicks(sec, getGroupAssignSelectedHourType());
}

function getGroupAssignRowGroupIds(row) {
  if (Array.isArray(row?.groupIds) && row.groupIds.length) return row.groupIds;
  // if (row?.deliveryScope === 'section') return []; // 原 section 返回空由 matches 匹配全部小组，改仅显式 groupIds
  return row?.groupId ? [row.groupId] : [];
}

function groupAssignRowMatchesGroup(row, groupId) {
  if (!groupId) return false;
  const ids = getGroupAssignRowGroupIds(row);
  if (row?.deliveryScope === 'section') {
    return ids.length ? ids.includes(groupId) : true;
  }
  return ids.includes(groupId);
}

function formatGroupAssignScopeLabel(row) {
  if (row?.deliveryScope === 'section') return '全体小组';
  const ids = getGroupAssignRowGroupIds(row);
  if (ids.length > 1) return '指定小组（多个）';
  return '指定小组';
}

function getGroupAssignRowGroupLabels(row, sec) {
  const ids = getGroupAssignRowGroupIds(row);
  if (row?.deliveryScope === 'section' && !ids.length) {
    if (!sec?.groups?.length) return [sec?.name || '课程'];
    return (sec?.groups || []).map(g => formatMajorOfferingGroupName(sec.name, g.name));
  }
  if (!ids.length) return [];
  return ids.map(id => {
    const g = sec?.groups?.find(x => x.id === id);
    return g ? formatMajorOfferingGroupName(sec.name, g.name) : id;
  });
}

function formatGroupAssignGroupsLabel(row, sec) {
  const labels = getGroupAssignRowGroupLabels(row, sec);
  if (!labels.length) return '—';
  if (row?.deliveryScope === 'section') return joinUniqueLabels(labels, 3);
  return labels.join('、');
  // if (row?.deliveryScope === 'section') return 'All Groups'; // 原全体小组合班展示
  // if (row?.deliveryScope === 'section') return '全体'; // 原中文展示
}

function formatGroupAssignGroupsSummaryCell(row, sec) {
  const labels = getGroupAssignRowGroupLabels(row, sec);
  if (!labels.length) return '—';
  if (labels.length === 1) return escapeHtml(labels[0]);
  return `<div class="offering-hour-summary-groups">${labels.map(label =>
    `<span class="offering-hour-summary-group-line">${escapeHtml(label)}</span>`
  ).join('')}</div>`;
}

function formatGroupAssignWeeklyHoursDisplay(row) {
  return row?.weeklyHours != null && row.weeklyHours !== '' ? String(row.weeklyHours) : '—';
}

function formatGroupAssignSimultaneousGroupsDisplay(row) {
  return row?.simultaneousGroups ? '是' : '否';
}

function renderOfferingHourSummaryAssignRow(row, idx, sec) {
  return `<tr>
    <td class="col-index col-center">${idx + 1}</td>
    <td class="col-teacher">${formatGroupAssignTeacherSummaryCell(row, 22, sec)}</td>
    <td class="col-center col-simultaneous">${escapeHtml(formatGroupAssignSimultaneousGroupsDisplay(row))}</td>
    <td class="col-groups">${formatGroupAssignGroupsSummaryCell(row, sec)}</td>
    <td class="col-center col-weekly-hours">${escapeHtml(formatGroupAssignWeeklyHoursDisplay(row))}</td>
    <td class="col-center col-week"><code>${escapeHtml(row.weekRange || '—')}</code></td>
    <td class="actions col-sticky-actions"><a href="#" onclick="openOfferingHourSummaryAssignDetail('${row.id}');return false">Details</a></td>
  </tr>`;
}

function getGroupAssignFormAllGroupIds(sec = getOfferingGroupingSection()) {
  const groups = sec?.groups || [];
  return groups.length ? groups.map(g => g.id) : ['__course__'];
}

function resolveGroupAssignFormScope(sec = getOfferingGroupingSection()) {
  const groups = sec?.groups || [];
  if (!groups.length) {
    return { deliveryScope: 'section', groupIds: [] };
  }
  const selectedIds = getGroupAssignFormSelectedGroupIds();
  if (!selectedIds.length) {
    return { deliveryScope: 'group', groupIds: [] };
  }
  return { deliveryScope: 'group', groupIds: selectedIds };
  // const isAllSelected = ... return { deliveryScope: 'section', groupIds: [] }; // 原全选存 section 并自动囊括后续新增小组
}

// function selectAllGroupAssignGroups() {
//   document.querySelectorAll('.group-assign-group-check').forEach(el => { el.checked = true; });
// } // 原全选按钮，已移除

function syncGroupAssignHoursByType() {
  const sec = getOfferingGroupingSection();
  if (!sec || isSectionGroupAssignHoursMerged(sec)) return;
  const hourType = getGroupAssignSelectedHourType();
  document.querySelectorAll('.group-assign-hour-type-row').forEach(row => {
    const radio = row.querySelector('.group-assign-hour-type-radio');
    row.classList.toggle('is-selected', !!radio?.checked);
  });
  if (!document.getElementById('group-assign-edit-id')?.value) {
    const preserved = getGroupAssignFormSelectedGroupIds();
    if (preserved.length) {
      populateGroupAssignGroupPicks(sec, preserved);
    } else if (offeringGroupingSelectedGroupId && (sec.groups || []).length) {
      populateGroupAssignGroupPicks(sec, [offeringGroupingSelectedGroupId]);
    }
  }
  syncGroupAssignHoursSummary();
}

function populateGroupAssignGroupPicks(sec, selectedIds = []) {
  const wrap = document.getElementById('group-assign-group-picks');
  if (!wrap) return;
  const groups = sec?.groups || [];
  if (!groups.length) {
    wrap.innerHTML = '';
    return;
  }
  const selectedSet = new Set(selectedIds);
  const rows = groups.map(g => {
    const label = formatMajorOfferingGroupName(sec.name, g.name);
    const checked = selectedSet.has(g.id) ? ' checked' : '';
    return `<tr class="group-assign-group-pick-row${selectedSet.has(g.id) ? ' is-selected' : ''}" onclick="selectGroupAssignGroupPickRow(event, '${escapeHtml(g.id)}')">
      <td class="col-check" onclick="event.stopPropagation()">
        <input type="checkbox" class="group-assign-group-check" value="${escapeHtml(g.id)}"${checked} onchange="syncGroupAssignGroupPickSelection(); syncGroupAssignHoursSummary()">
      </td>
      <td>${escapeHtml(label)}</td>
      <td class="col-center"><span class="group-assign-group-pick-type" data-group-id="${escapeHtml(g.id)}">—</span></td>
      <td class="col-center"><span class="group-assign-group-pick-hours" data-group-id="${escapeHtml(g.id)}">—</span></td>
      <td class="col-center"><span class="group-assign-group-pick-hours group-assign-group-pick-remaining" data-group-id="${escapeHtml(g.id)}">—</span></td>
      <td class="col-center"><span class="offering-group-status-badge group-assign-group-pick-status" data-group-id="${escapeHtml(g.id)}">—</span></td>
    </tr>`;
  }).join('');
  wrap.innerHTML = `<div class="table-scroll group-assign-group-picks-table-wrap">
    <table class="data-table compact group-assign-group-picks-table">
      <thead><tr>
        <th class="col-check"><input type="checkbox" id="group-assign-groups-check-all" aria-label="全选小组" onchange="toggleGroupAssignGroupsCheckAll(this.checked)"></th>
        <th>小组</th>
        <th class="col-center">学时类型</th>
        <th class="col-center">已录入学时</th>
        <th class="col-center">剩余学时</th>
        <th class="col-center">状态</th>
      </tr></thead>
      <tbody>${rows}</tbody>
    </table>
  </div>`;
  syncGroupAssignGroupPickSelection();
}

function syncGroupAssignGroupPickSelection() {
  document.querySelectorAll('.group-assign-group-pick-row').forEach(row => {
    const checkbox = row.querySelector('.group-assign-group-check');
    row.classList.toggle('is-selected', !!checkbox?.checked);
  });
  const checkAll = document.getElementById('group-assign-groups-check-all');
  const selectable = document.querySelectorAll('.group-assign-group-check');
  if (checkAll && selectable.length) {
    const checkedOnPage = [...selectable].filter(el => el.checked).length;
    checkAll.checked = checkedOnPage === selectable.length;
    checkAll.indeterminate = checkedOnPage > 0 && checkedOnPage < selectable.length;
    groupAssignFormSelectAll = checkAll.checked;
  } else {
    groupAssignFormSelectAll = false;
    if (checkAll) {
      checkAll.checked = false;
      checkAll.indeterminate = false;
    }
  }
  const multi = getGroupAssignFormSelectedGroupIds().length > 1;
  if (!multi) groupAssignFormSimultaneousGroups = null;
}

function selectGroupAssignGroupPickRow(ev, groupId) {
  if (ev.target.closest('input, button, a, label')) return;
  const checkbox = document.querySelector(`.group-assign-group-check[value="${CSS.escape(groupId)}"]`);
  if (!checkbox) return;
  checkbox.checked = !checkbox.checked;
  syncGroupAssignGroupPickSelection();
  syncGroupAssignHoursSummary();
}

function toggleGroupAssignGroupsCheckAll(checked) {
  groupAssignFormSelectAll = checked;
  document.querySelectorAll('.group-assign-group-check').forEach(el => { el.checked = checked; });
  syncGroupAssignGroupPickSelection();
  syncGroupAssignHoursSummary();
}

function toggleGroupAssignGroupPickRow(ev, groupId) {
  selectGroupAssignGroupPickRow(ev, groupId);
}

