  // document.querySelectorAll('.offering-group-tab').forEach ... toggleAttribute hidden 原 inline，已抽 syncOfferingGroupingTabVisibility
  sec.isGrouped = (sec.groups?.length || 0) > 0;
  autosaveOfferingGroupingStructure();
