const SCHEDULE_ROOM_DEMO_PENDING_VERSION = 'v3';
/** 排教室左侧联排节次上限（连续合并不超过 3 节） */
const SCHEDULE_ROOM_LINKED_PERIOD_MAX = 3;
/** 排教室「按时间排」列表：每个星期目标小组数（学时单元行数） */
const SCHEDULE_ROOM_WEEKDAY_TARGET_GROUP_COUNT = 10;
