function renderScheduleTimetableGrid(term, tasks, activeTaskId, weekFilter) {
  const mount = scheduleDetailEl('schedule-timetable-grid');
  if (!mount) return;
  const periods = ensureSchedulePeriods(term);
  if (!periods.length) {
    mount.innerHTML = '<p class="text-muted" style="padding:16px">请先在「课表节次维护」中配置节次</p>';
    return;
  }
  const filterWeeks = weekFilter !== undefined ? weekFilter : getScheduleDetailTimetableWeekFilter();
  const roomScopeCtx = scheduleBatchDetailContext;
  const roomScopedMenu = scheduleDetailPhase === 'room'
    && roomScopeCtx
    && (roomScopeCtx.type === 'weekday' || roomScopeCtx.type === 'venueType');
  // 按时间/场地类型排教室详情固定显示七天，便于周末行落地
  const weekdays = (roomScopedMenu || scheduleShowWeekend)
    ? SCHEDULE_WEEKDAYS
    : SCHEDULE_WEEKDAYS.filter(w => w.value <= 5);
  // 排教室侧：仅左侧课程列表选中时按课程（及学时类型）过滤；仅点节次选中时仍显示周次内全部课程
  const filterByCourseList = scheduleDetailPhase === 'room' && activeTaskId && scheduleActiveFromCourseList;
  const displayTasks = filterByCourseList
    ? tasks.filter(t => t.id === activeTaskId)
    : tasks;
  const activeHourKeyForGrid = filterByCourseList
    ? normalizeScheduleHourKey(scheduleActiveHourType || getScheduleActiveHourKey() || '')
    : '';
  const isRoomGrid = scheduleDetailPhase === 'room';
  const occupancy = new Map(); // time: weekday-period；room: room|period
  displayTasks.forEach(task => {
    const colorIdx = getTaskScheduleColorIndex(task.id);
    normalizeTaskTimeSlots(task).forEach(slot => {
      if (!slotMatchesWeekFilter(slot, task, filterWeeks)) return;
      if (
        activeHourKeyForGrid
        && activeHourKeyForGrid !== 'merged'
        && getScheduleSlotHourKey(task, slot) !== activeHourKeyForGrid
      ) return;
      // 按时间/场地类型作用域：课表仅显示匹配节次
      if (roomScopedMenu && !scheduleRoomSlotMatchesDetailScope(slot, task, roomScopeCtx)) return;
      const cellPayload = {
        taskId: task.id,
        task,
        slot,
        title: `${task.code} ${task.name || ''} · ${formatScheduleSlotWeeksForCard(slot, task) || slot.weeks || task.weeks || ''}`,
        colorIdx
      };
      if (isRoomGrid) {
        const roomName = String(slot.room || '').trim();
        if (!roomName) return;
        for (let p = slot.periodFrom; p <= (slot.periodTo || slot.periodFrom); p++) {
          const key = `${roomName}|${p}`;
          if (!occupancy.has(key)) occupancy.set(key, []);
          occupancy.get(key).push(cellPayload);
        }
        return;
      }
      for (let p = slot.periodFrom; p <= (slot.periodTo || slot.periodFrom); p++) {
        const key = `${slot.weekday}-${p}`;
        if (!occupancy.has(key)) occupancy.set(key, []);
        occupancy.get(key).push(cellPayload);
      }
    });
  });
  const activeTask = tasks.find(t => t.id === activeTaskId) || null;
  const conflictKeys = getScheduleConflictCellKeys(tasks, activeTask);
  const axisMaxCols = {};
  if (isRoomGrid) {
    periods.forEach(p => { axisMaxCols[p.periodNo] = 1; });
    getScheduleRoomTimetableRows().forEach(r => {
      periods.forEach(p => {
        const n = (occupancy.get(`${r.room}|${p.periodNo}`) || []).length;
        if (n) axisMaxCols[p.periodNo] = Math.max(axisMaxCols[p.periodNo], Math.min(n, 3));
      });
    });
  } else {
    weekdays.forEach(w => { axisMaxCols[w.value] = 1; });
    periods.forEach(p => {
      weekdays.forEach(w => {
        const n = (occupancy.get(`${w.value}-${p.periodNo}`) || []).length;
        if (n) axisMaxCols[w.value] = Math.max(axisMaxCols[w.value], Math.min(n, 3));
      });
    });
  }

  const renderBlocks = (cells, colCount, dayCols, weekday, periodNo, roomName, opts = {}) => {
    const colspan = Math.max(1, Number(opts.colspan) || 1);
    const conf = conflictKeys.get(`${weekday}-${periodNo}`);
    const cls = ['schedule-grid-cell'];
    if (colspan > 1) cls.push('is-room-linked-span');
    if (cells.length) {
      cls.push('is-occupied');
      if (cells.some(c => scheduleSelectedSlotIds.has(c.slot.id))) cls.push('is-slot-selected');
      if (isRoomGrid) {
        if (scheduleActiveFromCourseList && cells.some(c => c.taskId === activeTaskId)) {
          cls.push('is-active-course');
        }
      } else if (cells.some(c => c.taskId === activeTaskId)) {
        cls.push('is-active-course');
      } else if (activeTaskId) {
        cls.push('is-blocked');
      }
    } else if (activeTaskId && !isRoomGrid) {
      cls.push('is-active-target');
    }
    const paintPrimary = getScheduleConflictPaintPrimary(conf);
    let roomCellState = opts.roomCellState || 'empty';
    if (isRoomGrid) {
      if (roomName) {
        if (!opts.roomCellState) {
          roomCellState = getScheduleRoomCellState(roomName, weekday, periodNo, tasks, filterWeeks);
        }
        if (roomCellState === 'locked') cls.push('is-room-cell-locked');
        else if (roomCellState === 'pending') cls.push('is-room-cell-pending');
        else if (hasScheduleRoomTimetableCourseContext()) {
          cls.push('is-room-cell-empty');
          const periodNeed = getScheduleActiveRoomPeriodNeed();
          if (isScheduleRoomPeriodInCourseTime(periodNo, periodNeed)) {
            cls.push('is-active-target');
          } else {
            cls.push('is-room-cell-outside-time');
          }
        }
      }
      if (conf?.hasConflict || paintPrimary) {
        cls.push('is-conflict');
        if (paintPrimary) cls.push(`is-conflict-${paintPrimary}`);
      }
    } else if (conf && scheduleConflictAffectsGrid(conf)) {
      cls.push('is-conflict');
      if (paintPrimary) cls.push(`is-conflict-${paintPrimary}`);
    }
    const clickHandler = isRoomGrid && roomName
      ? ''
      : `onScheduleGridCellClick(${weekday},${periodNo},event)`;
    const colspanAttr = colspan > 1 ? ` colspan="${colspan}"` : '';
    const spanAttr = colspan > 1 ? ` data-period-span="${colspan}"` : '';
    let cellHtml = `<td class="${cls.join(' ')}" style="--sch-cols:${colCount};--sch-day-cols:${dayCols}" data-weekday="${weekday}" data-period="${periodNo}"${spanAttr}${roomName ? ` data-room="${escapeHtml(roomName)}"` : ''}${colspanAttr}${clickHandler ? ` onclick="${clickHandler}"` : ''}>`;
    if (isRoomGrid && roomName && (roomCellState === 'locked' || roomCellState === 'pending')) {
      let holdEntries = opts.holdEntries;
      if (!holdEntries) {
        holdEntries = getScheduleRoomHoldCellEntries(roomName, weekday, periodNo, tasks, filterWeeks, roomCellState);
      }
      if (!holdEntries.length && cells.length) {
        holdEntries = cells.map(c => ({ task: c.task, slot: c.slot }));
      }
      if (holdEntries.length) {
        cellHtml += buildScheduleRoomHoldCellContent(holdEntries, roomCellState);
      }
    } else if (cells.length) {
      cellHtml += `<div class="schedule-grid-multi" style="--sch-cols:${colCount}">`;
      const cellHasSelection = cells.some(c => scheduleSelectedSlotIds.has(c.slot.id));
      cells.forEach(cell => {
        const slotOn = scheduleSelectedSlotIds.has(cell.slot.id);
        const blockCls = [
          'schedule-grid-block',
          `is-c${cell.colorIdx}`,
          'schedule-grid-block-rich',
          slotOn ? 'is-slot-selected-block' : '',
          cellHasSelection && !slotOn ? 'is-slot-sibling-block' : ''
        ].filter(Boolean).join(' ');
        const inner = buildScheduleGridBlockLines(cell.task, cell.slot);
        cellHtml += `<span class="${blockCls}" title="${escapeHtml(cell.title)}" data-task-id="${escapeHtml(cell.task.id)}" data-slot-id="${escapeHtml(cell.slot.id)}">${inner}</span>`;
      });
      cellHtml += '</div>';
    }
    cellHtml += '</td>';
    return cellHtml;
  };

  let html;
  if (isRoomGrid) {
    // 行=教室；横标题=节次；教室软件后=备注
    const roomRows = getScheduleRoomTimetableRows();
    const lockIndex = buildScheduleLockedRoomOwnerIndex();
    const hasCourseCtx = hasScheduleRoomTimetableCourseContext();
    const periodNeed = getScheduleActiveRoomPeriodNeed();
    // 教室列表始终展示全部节次列；选中课程节次仅用于匹配排序与待定占用
    const gridPeriods = periods;
    const metaColCount = 8;
    const selectedRooms = new Set();
    scheduleSelectedSlotIds.forEach(id => {
      displayTasks.forEach(t => {
        normalizeTaskTimeSlots(t).forEach(s => {
          if (s.id === id && s.room) selectedRooms.add(String(s.room).trim());
        });
      });
    });
    pendingRoomsFromHold(selectedRooms);
    const defaultWd = roomScopeCtx?.type === 'weekday'
      ? Number(roomScopeCtx.weekday)
      : (periodNeed?.weekday || getScheduleSelectedSlot()?.weekday || weekdays[0]?.value || 1);
    html = `<table class="schedule-grid-table schedule-detail-grid-table is-room-period-cols" style="--sch-day-count:${gridPeriods.length}"><thead><tr>`;
    html += '<th class="sch-room-meta sch-room-meta-room">教室</th>';
    html += '<th class="sch-room-meta sch-room-meta-seats">有效座位数</th>';
    html += '<th class="sch-room-meta sch-room-meta-rtype">教室类型</th>';
    html += '<th class="sch-room-meta sch-room-meta-vtype">场地类型</th>';
    html += '<th class="sch-room-meta sch-room-meta-building">楼栋</th>';
    html += '<th class="sch-room-meta sch-room-meta-equip">教室设备</th>';
    html += '<th class="sch-room-meta sch-room-meta-soft">教室软件</th>';
    html += '<th class="sch-room-meta sch-room-meta-remark sch-room-remark">备注</th>';
    gridPeriods.forEach(p => {
      html += `<th style="--sch-cols:${axisMaxCols[p.periodNo] || 1}"><span>${p.periodNo}</span><small>${escapeHtml(p.startTime)}-${escapeHtml(p.endTime)}</small></th>`;
    });
    html += '</tr></thead><tbody>';
    if (!roomRows.length) {
      const lockedRooms = hasCourseCtx
        ? (scheduleRoomFilterLockedRooms.length
          ? scheduleRoomFilterLockedRooms
          : getScheduleActiveRoomLockedRooms())
        : [];
      const cardVenueTypes = hasCourseCtx ? getScheduleActiveRoomCardVenueTypes() : [];
      const emptyMsg = scheduleRoomTimetableFilterApplied && !scheduleRoomTimetableFilterApplied.lockedRoomUnion
        ? '暂无匹配筛选条件的教室'
        : (lockedRooms.length
          ? `暂无匹配锁定教室（${lockedRooms.join('、')}）`
          : (cardVenueTypes.length
            ? `暂无匹配场地类型（${formatScheduleVenueTypesLabel(cardVenueTypes)}）的未锁定教室`
            : (hasCourseCtx ? '暂无未锁定的可用教室' : '暂无教室数据')));
      html += `<tr><td colspan="${metaColCount + gridPeriods.length}" class="text-muted" style="text-align:center;padding:16px">${escapeHtml(emptyMsg)}</td></tr>`;
    } else {
      roomRows.forEach(r => {
        const roomType = r.roomType || r.classroomTypeZh || r.classroomType || '—';
        const venueCat = getVenueCategoryForClassroomType(roomType) || mapScheduleVenueTypeValue(roomType);
        const venueLabel = venueCat ? getScheduleVenueTypeLabel(venueCat) : '—';
        const seats = r.availableSeats ?? r.seats ?? r.capacity ?? '—';
        const locked = isScheduleRoomLockedByOthers(r.room, lockIndex);
        const rowLockCls = locked ? ' is-room-row-locked' : ' is-room-row-pending';
        const rowActive = selectedRooms.has(String(r.room || '').trim()) ? ' is-room-row-active' : '';
        html += `<tr class="${(rowActive + rowLockCls).trim()}" data-room="${escapeHtml(r.room || '')}">`;
        html += `<th scope="row" class="sch-room-meta sch-room-meta-room"><code>${escapeHtml(r.room || '—')}</code></th>`;
        html += `<td class="sch-room-meta sch-room-meta-seats">${escapeHtml(String(seats))}</td>`;
        html += `<td class="sch-room-meta sch-room-meta-rtype">${escapeHtml(roomType)}</td>`;
        html += `<td class="sch-room-meta sch-room-meta-vtype">${escapeHtml(venueLabel)}</td>`;
        html += `<td class="sch-room-meta sch-room-meta-building">${escapeHtml(r.building || '—')}</td>`;
        html += `<td class="sch-room-meta sch-room-meta-equip">${escapeHtml(r.equipment || '—')}</td>`;
        html += `<td class="sch-room-meta sch-room-meta-soft">${escapeHtml(r.software || '—')}</td>`;
        const roomRemark = getScheduleRoomInfoRemark(r);
        html += `<td class="sch-room-meta sch-room-meta-remark sch-room-remark" title="${escapeHtml(roomRemark || '—')}">${escapeHtml(roomRemark || '—')}</td>`;
        // 联排节次：起点格 colspan 合并为一张卡片，中间/尾部格跳过
        const coveredPeriods = new Set();
        gridPeriods.forEach(p => {
          if (coveredPeriods.has(p.periodNo)) return;
          const cells = occupancy.get(`${r.room}|${p.periodNo}`) || [];
          const wd = Number(cells[0]?.slot?.weekday)
            || Number(getScheduleRoomHoldCellEntries(r.room, defaultWd, p.periodNo, tasks, filterWeeks, 'any')[0]?.slot?.weekday)
            || defaultWd;
          const spanInfo = resolveScheduleRoomLinkedCellSpan(
            r.room, wd, p.periodNo, tasks, filterWeeks, cells
          );
          if (spanInfo.isContinuation) return;
          const span = Math.max(1, Number(spanInfo.span) || 1);
          for (let i = 1; i < span; i++) coveredPeriods.add(p.periodNo + i);
          const colCount = cells.length ? Math.min(cells.length, 3) : 1;
          const dayCols = axisMaxCols[p.periodNo] || 1;
          html += renderBlocks(cells, colCount, dayCols, wd, p.periodNo, r.room, {
            colspan: span,
            roomCellState: spanInfo.state,
            holdEntries: spanInfo.entries
          });
        });
        html += '</tr>';
      });
    }
    html += '</tbody></table>';
  } else {
    // --sch-day-count：单列初始日列宽按当前显示星期数均分；多卡片时列宽=单列宽×列数，超出横向滚动
    html = `<table class="schedule-grid-table schedule-detail-grid-table" style="--sch-day-count:${weekdays.length}"><thead><tr><th class="schedule-grid-period-col">节次</th>`;
    weekdays.forEach(w => {
      html += `<th style="--sch-cols:${axisMaxCols[w.value]}">${w.label}</th>`;
    });
    html += '</tr></thead><tbody>';
    periods.forEach(p => {
      html += `<tr><td class="schedule-grid-period-col"><span>${p.periodNo}</span><small>${escapeHtml(p.startTime)}-${escapeHtml(p.endTime)}</small></td>`;
      weekdays.forEach(w => {
        const cells = occupancy.get(`${w.value}-${p.periodNo}`) || [];
        const colCount = cells.length ? Math.min(cells.length, 3) : 1;
        html += renderBlocks(cells, colCount, axisMaxCols[w.value] || 1, w.value, p.periodNo);
      });
      html += '</tr>';
    });
    html += '</tbody></table>';
  }
  mount.innerHTML = html;
  bindScheduleTimetableContextMenu(mount);
  if (isRoomGrid) bindScheduleRoomGridCellClicks(mount);
  initScheduleGridDragSelect();
}

/** 排教室课表：委托点击节次格（避免教室名嵌入 onclick 引号截断） */
function bindScheduleRoomGridCellClicks(mount) {
  if (!mount || mount.dataset.roomGridClickBound === '1') return;
  mount.dataset.roomGridClickBound = '1';
  mount.addEventListener('click', e => {
    if (scheduleDetailPhase !== 'room') return;
    const cell = e.target.closest('td.schedule-grid-cell[data-room]');
    if (!cell?.dataset?.room) return;
    onScheduleRoomGridCellClick(
      cell.dataset.room,
      Number(cell.dataset.weekday),
      Number(cell.dataset.period),
      e
    );
  });
}

/** 将当前相位的课表卡片显示设置写回勾选（时间/教室页克隆后 ID 重复，须走 scheduleDetailEl） */
function syncScheduleViewSettingControls() {
  const weekend = scheduleDetailEl('sch-show-weekend');
  if (weekend) weekend.checked = !!scheduleShowWeekend;
  const isRoom = scheduleDetailPhase === 'room';
  const fields = getScheduleCardFields();
  const map = {
    'sch-card-name': !!fields.name,
    'sch-card-weeks': !!fields.weeks,
    'sch-card-teacher': !!fields.teacherId,
    'sch-card-room': isRoom ? false : !!fields.room,
    'sch-card-group': !!fields.group,
    'sch-card-hourtype': isRoom ? false : !!fields.hourType
  };
  Object.entries(map).forEach(([id, on]) => {
    const el = scheduleDetailEl(id);
    if (el) el.checked = on;
  });
  const code = scheduleDetailEl('sch-card-code');
  if (code) code.checked = true;
  const cardRoomOpt = scheduleDetailEl('sch-card-room')?.closest('.schedule-view-opt');
  const cardHourTypeOpt = scheduleDetailEl('sch-card-hourtype')?.closest('.schedule-view-opt');
  if (cardRoomOpt) cardRoomOpt.hidden = isRoom;
  if (cardHourTypeOpt) cardHourTypeOpt.hidden = isRoom;
}

function onScheduleViewSettingChange() {
  // 教室详情为时间页克隆，存在重复 id；须读当前激活详情页内的控件
  scheduleShowWeekend = !!scheduleDetailEl('sch-show-weekend')?.checked;
  const phaseKey = scheduleDetailPhase === 'room' ? 'room' : 'time';
  const isRoom = phaseKey === 'room';
  scheduleCardFieldsByPhase[phaseKey] = {
    code: true,
    name: !!scheduleDetailEl('sch-card-name')?.checked,
    weeks: !!scheduleDetailEl('sch-card-weeks')?.checked,
    teacherId: !!scheduleDetailEl('sch-card-teacher')?.checked,
    room: isRoom ? false : !!scheduleDetailEl('sch-card-room')?.checked,
    group: !!scheduleDetailEl('sch-card-group')?.checked,
    hourType: isRoom ? false : !!scheduleDetailEl('sch-card-hourtype')?.checked,
    hours: false
  };
  const ctx = scheduleBatchDetailContext;
  if (!ctx) return;
  const term = getActiveOfferingTermSetting()?.termCode || getSelectedScheduleTimeSettingTerm();
  const tasks = getScheduleDetailTasks();
  renderScheduleTimetableGrid(term, tasks, scheduleActiveTaskId);
}

/** 课程起止周展示：优先该学时单元教师安排起止周，与上方周次格子回显同源 */
function getScheduleCourseWeeksLabel(task, hourKey) {
  if (!task) return '—';
  const key = hourKey || getScheduleActiveHourKey() || getPrimaryHourKey(task);
  const ctx = getScheduleUnitAssignmentContext(task, key);
  const sec = getScheduleOfferingSection(task);
  if (ctx.teachingWeeks?.length) return formatWeeksSegmentDisplay(ctx.teachingWeeks);
  if (ctx.weekRange) {
    const weeks = parseWeekRangeToWeeks(ctx.weekRange, getSectionTermTeachingWeeks(sec));
    if (weeks.length) return formatWeeksSegmentDisplay(weeks);
    return ctx.weekRange;
  }
  if (sec) return getSectionWeekRangeDisplay(sec);
  const weeks = getScheduleCourseViewWeeks(task, key);
  if (!weeks.length) return task.weeks || '—';
  return formatWeeksSegmentDisplay(weeks);
}

function getScheduleUnitRows(tasks) {
  const rows = [];
  tasks.forEach(task => {
    getScheduleTaskHourTypeBreakdown(task).forEach(u => {
      rows.push({ task, unit: u, unitId: scheduleUnitId(task.id, u.key) });
    });
  });
  return rows;
}

/** 课程是否已有排时间节次（weekday + period） */
function taskHasScheduledTimeSlots(task) {
  return normalizeTaskTimeSlots(task).some(s => s.weekday && s.periodFrom);
}

/** 排教室左侧合并卡片缓存（mergeId → card） */
let scheduleRoomMergedCardsById = new Map();

/** 排教室详情作用域：节次是否属于当前星期/场地类型 */
function scheduleRoomSlotMatchesDetailScope(slot, task, ctx) {
  if (!slot?.weekday || !slot?.periodFrom) return false;
  if (!scheduleRoomSlotIsAssignable(slot, task)) return false;
  const scope = ctx || scheduleBatchDetailContext;
  if (!scope || (scope.phase || scheduleDetailPhase) !== 'room') return true;
  if (scope.type === 'weekday') {
    return Number(slot.weekday) === Number(scope.weekday);
  }
  if (scope.type === 'venueType') {
    return resolveScheduleSlotVenueTypes(slot, task).includes(scope.venueType);
  }
  return true;
}

/** 教师合并键：工号优先，否则姓名 */
function getScheduleTaskTeacherMergeKey(task) {
  const ids = (typeof getScheduleTaskTeacherEntries === 'function'
    ? getScheduleTaskTeacherEntries(task)
    : []
  ).map(e => e.staffId || e.name).filter(Boolean).sort();
  if (ids.length) return ids.join('|');
  return String(formatScheduleTeacherNames(task) || '').trim() || '—';
}

/** 单门课的小组名 / 总人数 / 计划人数 / 上限人数 */
function getScheduleTaskGroupHeadcountInfo(task, hourKey) {
  const sec = getScheduleOfferingSection(task);
  const groups = hourKey != null
    ? getScheduleUnitGroups(task, hourKey)
    : (sec?.groups?.length ? [...sec.groups] : []);
  const names = groups.map(g => String(g?.name || '').trim()).filter(Boolean);
  const groupTotal = groups.reduce((sum, g) => {
    const roster = Number(g?.studentCount);
    const cap = Number(g?.capacityLimit);
    const n = Number.isFinite(roster) && roster > 0
      ? Math.floor(roster)
      : (Number.isFinite(cap) && cap > 0 ? Math.floor(cap) : 0);
    return sum + n;
  }, 0);
  const planned = Number(sec?.estimatedStudents ?? sec?.studentCount);
  const limit = groups.reduce((sum, g) => sum + (Number(g?.capacityLimit) > 0 ? Math.floor(Number(g.capacityLimit)) : 0), 0)
    || (Number.isFinite(planned) ? Math.floor(planned) : 0);
  return {
    names: names.length ? names : getScheduleTaskGroupNames(task),
    groupTotal,
    planned: Number.isFinite(planned) && planned > 0 ? Math.floor(planned) : 0,
    limit
  };
}

/** 节次时段文案：周一 第1-3节 08:00-11:00 */
function formatScheduleRoomSlotTimeLabel(slot, term) {
  const day = getScheduleWeekdayLabel(slot?.weekday);
  const periodText = formatScheduleSlotPeriodLabel(slot);
  const periods = ensureSchedulePeriods(term || getActiveOfferingTermSetting()?.termCode || getSelectedScheduleTimeSettingTerm());
  const from = Number(slot?.periodFrom);
  const to = Number(slot?.periodTo || slot?.periodFrom);
  const pFrom = periods.find(p => Number(p.periodNo) === from);
  const pTo = periods.find(p => Number(p.periodNo) === to) || pFrom;
  const clock = pFrom && pTo
    ? `${pFrom.startTime || ''}-${pTo.endTime || ''}`.replace(/^-|-$/g, '')
    : '';
  const tail = [periodText, clock].filter(Boolean).join(' ');
  return [day, tail].filter(Boolean).join(' ');
}

/** 同一课程同天：将连续节次合并为大节次（如第1-3节）；联排不超过 SCHEDULE_ROOM_LINKED_PERIOD_MAX */
function mergeConsecutiveScheduleRoomSlotEntries(flatEntries) {
  const byCourseDay = new Map();
  flatEntries.forEach(e => {
    const key = [e.weeks, e.weekday, e.teacherKey, e.code].join('|');
    if (!byCourseDay.has(key)) byCourseDay.set(key, []);
    byCourseDay.get(key).push(e);
  });
  const out = [];
  const maxLink = SCHEDULE_ROOM_LINKED_PERIOD_MAX;
  byCourseDay.forEach(list => {
    list.sort((a, b) => a.periodFrom - b.periodFrom || a.periodTo - b.periodTo);
    let chunk = null;
    const startChunk = (e) => ({
      weeks: e.weeks,
      weekday: e.weekday,
      teacherKey: e.teacherKey,
      teacherLabel: formatScheduleTeacherNames(e.task),
      periodFrom: e.periodFrom,
      // 单条节次若跨度过大，展示侧钳制到联排上限
      periodTo: Math.min(e.periodTo, e.periodFrom + maxLink - 1),
      entries: [{ task: e.task, slot: e.slot }]
    });
    list.forEach(e => {
      if (!chunk) {
        chunk = startChunk(e);
        return;
      }
      const nextTo = Math.max(chunk.periodTo, e.periodTo);
      const canLink = e.periodFrom <= chunk.periodTo + 1
        && (nextTo - chunk.periodFrom + 1) <= maxLink;
      if (canLink) {
        chunk.periodTo = nextTo;
        chunk.entries.push({ task: e.task, slot: e.slot });
      } else {
        out.push(chunk);
        chunk = startChunk(e);
      }
    });
    if (chunk) out.push(chunk);
  });
  return out;
}

/** 同一起止周、同大节次、同教师：合并不同课程到一张卡片 */
function mergeSameTimeScheduleRoomSlotChunks(chunks) {
  const map = new Map();
  chunks.forEach(chunk => {
    const key = [chunk.weeks, chunk.weekday, chunk.periodFrom, chunk.periodTo, chunk.teacherKey].join('|');
    if (!map.has(key)) {
      map.set(key, {
        mergeId: `rmerge:${key}`,
        mergeKey: key,
        weeks: chunk.weeks,
        weekday: chunk.weekday,
        periodFrom: chunk.periodFrom,
        periodTo: chunk.periodTo,
        teacherKey: chunk.teacherKey,
        teacherLabel: chunk.teacherLabel,
        entries: [...chunk.entries]
      });
    } else {
      map.get(key).entries.push(...chunk.entries);
    }
  });
  return [...map.values()];
}

/**
 * 排教室左侧：按课程×节次生成卡片。
 * 同课程连续节次合并为大节次（联排不超过 3 节）；同大节次、同教师的不同课程各占一行（课程号反斜杠拼接）。
 * 「不选择教室」节次不进入。
 */
function buildScheduleRoomMergedSlotCards(tasks) {
  const ctx = scheduleBatchDetailContext;
  const flat = [];
  (tasks || []).forEach(task => {
    if (typeof isScheduleTaskSchedulable === 'function' && !isScheduleTaskSchedulable(task)) return;
    normalizeTaskTimeSlots(task).forEach(slot => {
      if (!slot?.weekday || !slot?.periodFrom) return;
      if (!scheduleRoomSlotIsAssignable(slot, task)) return;
      if (!scheduleRoomSlotMatchesDetailScope(slot, task, ctx)) return;
      const weekFilter = getScheduleDetailTimetableWeekFilter();
      if (weekFilter.length && !slotMatchesWeekFilter(slot, task, weekFilter)) return;
      flat.push({
        task,
        slot,
        weeks: String(slot.weeks || task.weeks || '').trim() || '—',
        weekday: Number(slot.weekday),
        periodFrom: Number(slot.periodFrom),
        periodTo: Number(slot.periodTo || slot.periodFrom),
        teacherKey: getScheduleTaskTeacherMergeKey(task),
        code: String(formatScheduleCourseCode(task.code) || task.id || '').toUpperCase()
      });
    });
  });
  const mergedChunks = mergeConsecutiveScheduleRoomSlotEntries(flat);
  const mapValues = mergeSameTimeScheduleRoomSlotChunks(mergedChunks);
  const cards = mapValues.map(card => {
    const summary = summarizeScheduleRoomMergedEntries(card.entries);
    const nameParts = [];
    card.entries.forEach(e => {
      const n = String(e.task.name || '').trim();
      if (n && !nameParts.includes(n)) nameParts.push(n);
    });
    let done = 0;
    let pending = 0;
    card.entries.forEach(({ task, slot }) => {
      if (String(slot.room || '').trim()) done += 1;
      else pending += 1;
    });
    const venueTypes = [];
    card.entries.forEach(({ task, slot }) => {
      resolveScheduleSlotVenueTypes(slot, task).forEach(t => {
        if (!venueTypes.includes(t)) venueTypes.push(t);
      });
    });
    const lockedRooms = [...new Set(card.entries.map(e => String(e.slot.lockedRoom || '').trim()).filter(Boolean))];
    const remarks = [...new Set(card.entries.map(e => String(e.slot.venueRemark || '').trim()).filter(Boolean))];
    const unitIds = [...new Set(card.entries.map(({ task, slot }) =>
      scheduleUnitId(task.id, getScheduleSlotHourKey(task, slot) || getPrimaryHourKey(task))
    ))];
    const slotIds = card.entries.map(e => e.slot.id).filter(Boolean);
    let planned = 0;
    let limit = 0;
    card.entries.forEach(({ task, slot }) => {
      const hourKey = getScheduleSlotHourKey(task, slot) || getPrimaryHourKey(task);
      const info = getScheduleTaskGroupHeadcountInfo(task, hourKey);
      planned += info.planned;
      limit += info.limit;
    });
    return {
      ...card,
      codes: summary.codes,
      codeLabel: summary.codeLabel,
      nameLabel: nameParts.join(' / ') || '',
      groupNames: summary.groupNames,
      groupLabel: summary.groupLabel,
      groupTotal: summary.groupTotal,
      planned,
      limit,
      done,
      pending,
      complete: pending === 0 && done > 0,
      isPending: pending > 0 || done === 0,
      venueTypes,
      venueLabel: venueTypes.length
        ? venueTypes.map(getScheduleVenueTypeLabel).join('、')
        : '—',
      lockedRoomLabel: lockedRooms.length ? lockedRooms.join('、') : '—',
      remarkLabel: remarks.length ? remarks.join('；') : '—',
      timeLabel: formatScheduleRoomSlotTimeLabel({
        weekday: card.weekday,
        periodFrom: card.periodFrom,
        periodTo: card.periodTo
      }),
      unitIds,
      slotIds,
      primaryTaskId: summary.primaryTaskId,
      primaryHourKey: card.entries[0]
        ? (getScheduleSlotHourKey(card.entries[0].task, card.entries[0].slot) || getPrimaryHourKey(card.entries[0].task))
        : ''
    };
  }).sort((a, b) => {
    if (a.weekday !== b.weekday) return a.weekday - b.weekday;
    if (a.periodFrom !== b.periodFrom) return a.periodFrom - b.periodFrom;
    return a.codeLabel.localeCompare(b.codeLabel, 'zh-CN');
  });
  scheduleRoomMergedCardsById = new Map(cards.map(c => [c.mergeId, c]));
  return cards;
}

function getScheduleRoomMergedCards(tasks) {
  return buildScheduleRoomMergedSlotCards(tasks);
}

/** 左侧选中卡片的上课周次并集（用于右侧排课周次回显） */
function getScheduleRoomMergedCardWeeks(card) {
  if (!card?.entries?.length) return [];
  const weeks = new Set();
  card.entries.forEach(({ task, slot }) => {
    parseWeeksString(slot?.weeks || task?.weeks || '').forEach(w => weeks.add(w));
  });
  return [...weeks].sort((a, b) => a - b);
}

/** 排教室：选课后将右侧周次格子同步为所选节次周次 */
function syncScheduleRoomViewWeeksFromCard(card) {
  const weeks = getScheduleRoomMergedCardWeeks(card);
  scheduleDetailViewWeeks = weeks;
  scheduleDraftWeeks = weeks.length ? formatScheduleWeekList(weeks) : '';
  const hidden = scheduleDetailEl('schedule-detail-weeks');
  if (hidden) hidden.value = scheduleDraftWeeks;
}

function selectScheduleRoomMergedCard(mergeId) {
  const card = scheduleRoomMergedCardsById.get(mergeId);
  if (!card) return;
  const active = scheduleActiveFromCourseList
    && card.slotIds.length
    && card.slotIds.every(id => scheduleSelectedSlotIds.has(id))
    && scheduleActiveTaskId === card.primaryTaskId;
  if (active) {
    scheduleActiveTaskId = null;
    scheduleActiveHourType = '';
    scheduleCourseExplicitlyCleared = true;
    scheduleActiveFromCourseList = false;
    scheduleSelectedSlotIds.clear();
    resetScheduleRoomTimetableFilterState();
    renderScheduleDetailPage();
    return;
  }
  scheduleCourseExplicitlyCleared = false;
  scheduleActiveFromCourseList = true;
  scheduleActiveTaskId = card.primaryTaskId;
  scheduleActiveHourType = card.primaryHourKey;
  scheduleVenueSettingsRequested = false;
  scheduleRoomTimetableExpanded = false;
  scheduleSelectedSlotIds = new Set(card.slotIds);
  const task = getScheduleActiveTask();
  // 先同步所选节次周次，再 init（避免被「保留旧筛选」逻辑挡住）
  syncScheduleRoomViewWeeksFromCard(card);
  initScheduleDraftForTask(task);
  scheduleSelectedSlotIds = new Set(card.slotIds);
  syncScheduleRoomFilterFromActiveCard();
  renderScheduleDetailPage();
}

function toggleScheduleRoomMergedCardCheck(mergeId, checked) {
  const card = scheduleRoomMergedCardsById.get(mergeId);
  if (!card) return;
  card.unitIds.forEach(id => {
    if (checked) scheduleDetailSelectedIds.add(id);
    else scheduleDetailSelectedIds.delete(id);
  });
  updateScheduleUndoBar();
  if (scheduleBatchDetailContext) {
    renderScheduleDetailCourseList(getScheduleDetailTasks(), scheduleActiveTaskId);
  }
}

/** 左侧课程列表选中时，取当前合并卡片（与 selectScheduleRoomMergedCard 高亮口径一致） */
function getScheduleActiveRoomMergedCard() {
  if (scheduleDetailPhase !== 'room' || !scheduleActiveFromCourseList) return null;
  if (!scheduleSelectedSlotIds.size || !scheduleActiveTaskId) return null;
  for (const card of scheduleRoomMergedCardsById.values()) {
    if (card.primaryTaskId !== scheduleActiveTaskId) continue;
    if (!card.slotIds.length || !card.slotIds.every(id => scheduleSelectedSlotIds.has(id))) continue;
    return card;
  }
  return null;
}

/** 左侧选中课程的排课场地（一级场地类型），用于过滤教室列表 */
function getScheduleActiveRoomCardVenueTypes() {
  const card = getScheduleActiveRoomMergedCard();
  if (!card?.venueTypes?.length) return [];
  return normalizeScheduleVenueTypes(card.venueTypes)
    .filter(t => t !== SCHEDULE_VENUE_TYPE_NONE);
}

/** 选中课程节次上的锁定教室并集 */
function getScheduleActiveRoomLockedRooms() {
  const card = getScheduleActiveRoomMergedCard();
  if (!card) return [];
  const rooms = new Set();
  card.entries.forEach(({ slot }) => {
    const lr = String(slot?.lockedRoom || '').trim();
    if (lr) rooms.add(lr);
  });
  return [...rooms];
}

/** 选中合并卡片的上课节次需求 */
function getScheduleActiveRoomPeriodNeed() {
  const card = getScheduleActiveRoomMergedCard();
  if (!card) return null;
  return {
    weekday: Number(card.weekday),
    periodFrom: Number(card.periodFrom),
    periodTo: Number(card.periodTo || card.periodFrom)
  };
}

/** 节次是否落在当前选中课程的上课时段内（用于教室列表格着色） */
function isScheduleRoomPeriodInCourseTime(periodNo, periodNeed) {
  if (!periodNeed) return false;
  const p = Number(periodNo);
  const pf = Number(periodNeed.periodFrom);
  const pt = Number(periodNeed.periodTo || periodNeed.periodFrom);
  if (!pf || !p) return false;
  return p >= pf && p <= pt;
}

function resetScheduleRoomTimetableFilterState() {
  scheduleRoomTimetableFilterDraft = {};
  scheduleRoomTimetableFilterApplied = null;
  scheduleRoomTimetableExpanded = false;
  scheduleRoomFilterMode = 'venueType';
  scheduleRoomFilterLockedRooms = [];
}

/** 选课后同步教室筛选：锁定教室并集 / 场地类型 */
function syncScheduleRoomFilterFromActiveCard() {
  if (scheduleDetailPhase !== 'room') return;
  const card = getScheduleActiveRoomMergedCard();
  if (!card) return;
  const lockedRooms = getScheduleActiveRoomLockedRooms();
  const venueTypes = normalizeScheduleVenueTypes(card.venueTypes || [])
    .filter(t => t !== SCHEDULE_VENUE_TYPE_NONE);
  const primaryVenue = venueTypes[0] || '';
  if (lockedRooms.length) {
    scheduleRoomFilterMode = 'lockedRoom';
    scheduleRoomFilterLockedRooms = lockedRooms;
    scheduleRoomTimetableFilterDraft = primaryVenue ? { venueType: primaryVenue } : {};
    scheduleRoomTimetableFilterApplied = { lockedRoomUnion: true };
  } else {
    scheduleRoomFilterMode = 'venueType';
    scheduleRoomFilterLockedRooms = [];
    scheduleRoomTimetableFilterDraft = primaryVenue ? { venueType: primaryVenue } : {};
    scheduleRoomTimetableFilterApplied = { ...scheduleRoomTimetableFilterDraft };
  }
  ensureScheduleRoomTimetableFilterOptions();
  const venueSel = scheduleDetailEl('srtf-venue-type');
  if (venueSel) {
    venueSel.value = primaryVenue || '';
    venueSel.disabled = lockedRooms.length > 0;
  }
}

/** 联排占用在教室行上的起止节次（待定优先于已锁定） */
function getScheduleRoomEntryPeriodRange(room, slot) {
  if (!slot) return null;
  const roomKey = String(room || '').trim();
  const hold = slot.id ? scheduleRoomPendingBySlot.get(slot.id) : null;
  if (hold && String(hold.room || '').trim() === roomKey) {
    const from = Number(hold.periodFrom);
    const to = Number(hold.periodTo || hold.periodFrom);
    if (from) return { from, to: to >= from ? to : from };
  }
  const from = Number(slot.periodFrom);
  const to = Number(slot.periodTo || slot.periodFrom);
  if (!from) return null;
  return { from, to: to >= from ? to : from };
}

/**
 * 排教室课表：联排节次合并跨度。
 * 若当前节次是联排的中间/尾部则 isContinuation=true（跳过渲染）；
 * 若是起点则 span>=1（用 colspan 合并显示一张卡片）。
 */
function resolveScheduleRoomLinkedCellSpan(room, weekday, periodNo, tasks, weekFilter, occupancyCells) {
  const state = getScheduleRoomCellState(room, weekday, periodNo, tasks, weekFilter);
  let entries = [];
  if (state === 'locked' || state === 'pending') {
    entries = getScheduleRoomHoldCellEntries(room, weekday, periodNo, tasks, weekFilter, state);
  }
  if (!entries.length && occupancyCells?.length) {
    entries = occupancyCells.map(c => ({ task: c.task, slot: c.slot }));
  }
  if (!entries.length) {
    return { state, span: 1, entries: [], isContinuation: false };
  }
  const ranges = entries.map(({ slot }) => {
    const range = getScheduleRoomEntryPeriodRange(room, slot);
    return range ? { ...range, slotId: slot.id } : null;
  }).filter(Boolean);
  if (!ranges.length) {
    return { state, span: 1, entries, isContinuation: false };
  }
  const minFrom = Math.min(...ranges.map(r => r.from));
  if (minFrom < Number(periodNo)) {
    return { state, span: 0, entries, isContinuation: true };
  }
  const ownIds = new Set(ranges.map(r => r.slotId));
  let span = Math.max(...ranges.map(r => r.to - Number(periodNo) + 1));
  span = Math.max(1, Math.min(span, SCHEDULE_ROOM_LINKED_PERIOD_MAX));
  const maxPeriod = getScheduleRoomMaxPeriodNo();
  span = Math.min(span, maxPeriod - Number(periodNo) + 1);
  while (span > 1) {
    let ok = true;
    for (let p = Number(periodNo) + 1; p < Number(periodNo) + span; p++) {
      const st = getScheduleRoomCellState(room, weekday, p, tasks, weekFilter);
      if (st !== 'locked' && st !== 'pending') { ok = false; break; }
      const other = getScheduleRoomHoldCellEntries(room, weekday, p, tasks, weekFilter, st);
      if (other.some(e => e.slot?.id && !ownIds.has(e.slot.id))) { ok = false; break; }
    }
    if (ok) break;
    span -= 1;
  }
  return { state, span, entries, isContinuation: false };
}

/** 排教室课表格：指定锁定/待定单元格内的课程节次 */
function getScheduleRoomHoldCellEntries(room, weekday, periodNo, tasks, weekFilter, state) {
  const roomKey = String(room || '').trim();
  if (!roomKey || !state || state === 'empty') return [];
  const wd = Number(weekday);
  const pNo = Number(periodNo);
  const entries = [];
  const seen = new Set();
  for (const task of tasks || []) {
    for (const slot of normalizeTaskTimeSlots(task)) {
      if (!slot?.id || seen.has(slot.id)) continue;
      if (!slotMatchesWeekFilter(slot, task, weekFilter)) continue;
      let matched = false;
      if (state === 'any') {
        const hold = scheduleRoomPendingBySlot.get(slot.id);
        if (hold
          && String(hold.room || '').trim() === roomKey
          && Number(hold.weekday) === wd) {
          const pf = Number(hold.periodFrom);
          const pt = Number(hold.periodTo || hold.periodFrom);
          if (pNo >= pf && pNo <= pt) matched = true;
        }
        if (!matched && Number(slot.weekday) === wd && String(slot.room || '').trim() === roomKey) {
          const pf = Number(slot.periodFrom);
          const pt = Number(slot.periodTo || slot.periodFrom);
          if (pNo >= pf && pNo <= pt) matched = true;
        }
      } else if (state === 'pending') {
        const hold = scheduleRoomPendingBySlot.get(slot.id);
        if (hold
          && String(hold.room || '').trim() === roomKey
          && Number(hold.weekday) === wd) {
          const pf = Number(hold.periodFrom);
          const pt = Number(hold.periodTo || hold.periodFrom);
          if (pNo >= pf && pNo <= pt) matched = true;
        }
        if (!matched && isScheduleRoomSlotPending(slot)
          && Number(slot.weekday) === wd
          && String(slot.room || '').trim() === roomKey) {
          const pf = Number(slot.periodFrom);
          const pt = Number(slot.periodTo || slot.periodFrom);
          if (pNo >= pf && pNo <= pt) matched = true;
        }
      } else if (state === 'locked') {
        if (isScheduleRoomSlotPending(slot)) continue;
        if (Number(slot.weekday) === wd && String(slot.room || '').trim() === roomKey) {
          const pf = Number(slot.periodFrom);
          const pt = Number(slot.periodTo || slot.periodFrom);
          if (pNo >= pf && pNo <= pt) matched = true;
        }
      }
      if (!matched) continue;
      seen.add(slot.id);
      entries.push({ task, slot });
    }
  }
  return entries;
}

/** 当前选中课程在指定教室格内的节次（用于右键锁定/撤回） */
function getScheduleRoomCellActionEntries(room, weekday, periodNo, tasks, weekFilter) {
  const all = getScheduleRoomHoldCellEntries(room, weekday, periodNo, tasks, weekFilter, 'any');
  if (scheduleActiveTaskId) {
    const own = all.filter(e => e.task.id === scheduleActiveTaskId);
    if (own.length) return own;
  }
  return all;
}

function isOwnScheduleRoomPendingCell(room, weekday, periodNo, tasks, weekFilter) {
  return getScheduleRoomCellActionEntries(room, weekday, periodNo, tasks, weekFilter)
    .some(e => isScheduleRoomSlotPending(e.slot));
}

/** 当前选中节次是否已在该教室格锁定（非待定） */
function isOwnScheduleRoomLockedCell(room, weekday, periodNo, tasks, weekFilter) {
  const roomKey = String(room || '').trim();
  const wd = Number(weekday);
  const pNo = Number(periodNo);
  return getScheduleSelectedSlotEntries().some(({ task, slot }) => {
    if (!slot?.id || isScheduleRoomSlotPending(slot)) return false;
    if (String(slot.room || '').trim() !== roomKey) return false;
    if (Number(slot.weekday) !== wd) return false;
    if (!slotMatchesWeekFilter(slot, task, weekFilter)) return false;
    const pf = Number(slot.periodFrom);
    const pt = Number(slot.periodTo || slot.periodFrom);
    return pNo >= pf && pNo <= pt;
  });
}

/** 打开「他课已占用教室」时间冲突弹窗（硬冲突，不可继续） */
function openScheduleRoomOccupiedTimeConflictModal(room, weekday, periodNo) {
  const entries = getScheduleSelectedSlotEntries();
  if (!entries.length) return;
  const conf = detectScheduleRoomAssignConflicts(entries, room);
  if (!conf.roomTime?.length) {
    const at = `${getScheduleWeekdayLabel(weekday)}第${periodNo}节`;
    conf.roomTime.push(`${at} · ${room} 已被其他课程占用`);
    recomputeScheduleRoomOnlyConflictFlags(conf);
  }
  openSchedulePlaceConflictModal(conf, null);
}

/** 合并上课节次汇总：与左侧卡片 codeLabel / groupLabel 口径一致 */
function summarizeScheduleRoomMergedEntries(entries) {
  const list = entries || [];
  const codes = [...new Set(list.map(e => formatScheduleCourseCode(e.task.code)).filter(Boolean))];
  const groupNames = [];
  let groupTotal = 0;
  list.forEach(({ task, slot }) => {
    const hourKey = getScheduleSlotHourKey(task, slot) || getPrimaryHourKey(task);
    const info = getScheduleTaskGroupHeadcountInfo(task, hourKey);
    info.names.forEach(n => { if (n && !groupNames.includes(n)) groupNames.push(n); });
    groupTotal += info.groupTotal;
  });
  const groupLabel = groupNames.length ? groupNames.join('、') : '—';
  return {
    codes,
    codeLabel: codes.join('\\') || '—',
    groupNames,
    groupLabel,
    groupTotal,
    groupText: groupTotal > 0 ? `${groupLabel}（${groupTotal}）` : groupLabel,
    primaryTaskId: list[0]?.task?.id || '',
    colorIdx: getTaskScheduleColorIndex(list[0]?.task?.id)
  };
}

/** 同一起止周、同大节次、同教师的合并上课条目分组 */
function groupScheduleRoomHoldEntriesByMergeKey(entries) {
  const groups = new Map();
  (entries || []).forEach(({ task, slot }) => {
    const weeks = String(slot.weeks || task.weeks || '').trim() || '—';
    const weekday = Number(slot.weekday);
    const periodFrom = Number(slot.periodFrom);
    const periodTo = Number(slot.periodTo || slot.periodFrom);
    const teacherKey = getScheduleTaskTeacherMergeKey(task);
    const key = [weeks, weekday, periodFrom, periodTo, teacherKey].join('|');
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push({ task, slot });
  });
  return [...groups.values()];
}

function buildScheduleRoomHoldCellBlockHtml(summary, variant) {
  return `<span class="schedule-grid-block schedule-grid-block-rich schedule-room-hold-block is-${variant} is-c${summary.colorIdx || 0}">
    <span class="schedule-grid-line schedule-grid-code">${escapeHtml(summary.codeLabel)}</span>
    <span class="schedule-grid-line schedule-grid-group">${escapeHtml(summary.groupText)}</span>
  </span>`;
}

function buildScheduleRoomHoldCellContent(entries, variant) {
  const mergedGroups = groupScheduleRoomHoldEntriesByMergeKey(entries).slice(0, 3);
  if (!mergedGroups.length) return '';
  const colCount = Math.min(mergedGroups.length, 3);
  return `<div class="schedule-grid-multi" style="--sch-cols:${colCount}">`
    + mergedGroups.map(g => buildScheduleRoomHoldCellBlockHtml(summarizeScheduleRoomMergedEntries(g), variant)).join('')
    + '</div>';
}

function getScheduleRoomCellState(room, weekday, periodNo, tasks, weekFilter) {
  const roomKey = String(room || '').trim();
  if (!roomKey) return 'empty';
  const wd = Number(weekday);
  const pNo = Number(periodNo);
  const inPeriod = (pf, pt) => pNo >= pf && pNo <= (pt || pf);
  for (const hold of scheduleRoomPendingBySlot.values()) {
    if (String(hold.room || '').trim() !== roomKey || Number(hold.weekday) !== wd) continue;
    const pf = Number(hold.periodFrom);
    const pt = Number(hold.periodTo || hold.periodFrom);
    if (inPeriod(pf, pt)) return 'pending';
  }
  for (const task of tasks || []) {
    for (const slot of normalizeTaskTimeSlots(task)) {
      if (!slotMatchesWeekFilter(slot, task, weekFilter)) continue;
      if (Number(slot.weekday) !== wd) continue;
      if (String(slot.room || '').trim() !== roomKey) continue;
      const pf = Number(slot.periodFrom);
      const pt = Number(slot.periodTo || slot.periodFrom);
      if (!inPeriod(pf, pt)) continue;
      if (isScheduleRoomSlotPending(slot)) return 'pending';
      return 'locked';
    }
  }
  return 'empty';
}

function getScheduleRoomMaxPeriodNo() {
  const term = getActiveOfferingTermSetting()?.termCode || getSelectedScheduleTimeSettingTerm();
  const periods = ensureSchedulePeriods(term) || [];
  return periods.reduce((m, p) => Math.max(m, Number(p.periodNo) || 0), 0);
}

function scoreScheduleRoomTimeMatch(room, need, tasks, weekFilter) {
  if (!need || !room) return { tier: 9, freeBonus: 0, overlapRatio: 0 };
  const { weekday, periodFrom, periodTo } = need;
  const needCount = periodTo - periodFrom + 1;
  let freeCount = 0;
  for (let p = periodFrom; p <= periodTo; p++) {
    if (getScheduleRoomCellState(room, weekday, p, tasks, weekFilter) === 'empty') freeCount++;
  }
  if (freeCount === 0) return { tier: 9, freeBonus: 0, overlapRatio: 0 };
  if (freeCount < needCount) {
    return { tier: 2, freeBonus: 0, overlapRatio: freeCount / needCount };
  }
  let spanStart = periodFrom;
  let spanEnd = periodTo;
  const maxP = getScheduleRoomMaxPeriodNo();
  while (spanStart > 1 && getScheduleRoomCellState(room, weekday, spanStart - 1, tasks, weekFilter) === 'empty') spanStart--;
  while (spanEnd < maxP && getScheduleRoomCellState(room, weekday, spanEnd + 1, tasks, weekFilter) === 'empty') spanEnd++;
  const freeSpan = spanEnd - spanStart + 1;
  if (freeSpan > needCount) return { tier: 1, freeBonus: freeSpan - needCount, overlapRatio: 1 };
  return { tier: 0, freeBonus: 0, overlapRatio: 1 };
}

function showScheduleRoomCellToast(message, durationMs = 3000) {
  const el = scheduleDetailEl('schedule-room-cell-toast') || document.getElementById('schedule-room-cell-toast');
  if (!el) return;
  el.textContent = message;
  el.hidden = false;
  if (scheduleRoomCellToastTimer) clearTimeout(scheduleRoomCellToastTimer);
  scheduleRoomCellToastTimer = setTimeout(() => {
    el.hidden = true;
    scheduleRoomCellToastTimer = null;
  }, durationMs);
}

function syncScheduleRoomPendingMapFromTasks(tasks) {
  scheduleRoomPendingBySlot.clear();
  (tasks || []).forEach(task => {
    normalizeTaskTimeSlots(task).forEach(slot => {
      if (!slot?.id || !slot.roomPending) return;
      const room = String(slot.room || '').trim();
      if (!room) return;
      scheduleRoomPendingBySlot.set(slot.id, {
        room,
        weekday: Number(slot.weekday),
        periodFrom: Number(slot.periodFrom),
        periodTo: Number(slot.periodTo || slot.periodFrom)
      });
    });
  });
}

function getScheduleRoomPendingHoldForSelected() {
  const entries = getScheduleSelectedSlotEntries();
  return entries.filter(e => isScheduleRoomSlotPending(e.slot));
}

function pendingRoomsFromHold(targetSet) {
  scheduleRoomPendingBySlot.forEach(hold => {
    const r = String(hold?.room || '').trim();
    if (r) targetSet.add(r);
  });
}

function renderScheduleRoomHoldActions() {
  const bar = scheduleDetailEl('schedule-room-hold-bar');
  const wrap = scheduleDetailEl('schedule-room-hold-actions');
  if (!bar || !wrap) return;
  const isRoom = scheduleDetailPhase === 'room';
  bar.hidden = !isRoom;
  if (!isRoom) {
    bar.style.display = 'none';
    return;
  }
  bar.style.display = '';
  const selected = getScheduleSelectedSlotEntries();
  const pending = selected.filter(e => isScheduleRoomSlotPending(e.slot));
  const hasRoom = selected.some(e => String(e.slot?.room || '').trim());
  const readonly = isScheduleDetailReadonly();
  const lockBtn = scheduleDetailEl('btn-schedule-room-hold-lock');
  const revokeBtn = scheduleDetailEl('btn-schedule-room-hold-revoke');
  if (lockBtn) lockBtn.disabled = readonly || pending.length === 0;
  if (revokeBtn) revokeBtn.disabled = readonly || (pending.length === 0 && !hasRoom);
}

function renderScheduleRoomGridFooter() {
  const shell = scheduleDetailEl('schedule-room-grid-shell');
  const footer = scheduleDetailEl('schedule-room-grid-footer');
  const btn = scheduleDetailEl('btn-schedule-room-grid-expand');
  if (!footer || !btn) return;
  const isRoom = scheduleDetailPhase === 'room';
  if (shell) shell.classList.toggle('is-room-mode', isRoom);
  if (!isRoom || !hasScheduleRoomTimetableCourseContext()) {
    footer.hidden = true;
    return;
  }
  const showExpand = getScheduleRoomTimetableHasMoreRows();
  const expanded = scheduleRoomTimetableExpanded;
  if (!showExpand && !expanded) {
    footer.hidden = true;
    return;
  }
  footer.hidden = false;
  btn.textContent = expanded ? '收起教室列表' : '展开更多教室';
}

/** 写入教室待定（已通过冲突校验或用户选择继续排课） */
function commitScheduleRoomCellPending(room, weekday, periodNo) {
  const entries = getScheduleSelectedSlotEntries();
  if (!entries.length) return;
  const need = getScheduleActiveRoomPeriodNeed();
  const wd = Number(need?.weekday || weekday);
  const pf = need?.periodFrom ?? periodNo;
  const pt = need?.periodTo ?? periodNo;
  const roomKey = String(room || '').trim();
  const weekFilter = getScheduleDetailTimetableWeekFilter();
  const taskSet = new Set();
  const nextSelected = new Set();
  entries.forEach(({ task, slot }) => {
    if (!slot?.id) return;
    const applied = applyScheduleRoomToSlotForWeeks(task, slot, roomKey, weekFilter);
    const target = applied || slot;
    markScheduleRoomSlotPending(target, {
      room: roomKey,
      weekday: wd,
      periodFrom: pf,
      periodTo: pt
    });
    taskSet.add(task);
    nextSelected.add(target.id);
  });
  if (weekFilter.length && nextSelected.size) {
    scheduleSelectedSlotIds = nextSelected;
  }
  taskSet.forEach(task => {
    persistTaskSchedule(task);
    syncScheduleTaskRoom(task);
  });
  markScheduleDirty();
  renderScheduleDetailPage();
  renderScheduleConflictPage();
  renderSchedulePublishPage();
}

function assignScheduleRoomCellPending(room, weekday, periodNo) {
  const entries = getScheduleSelectedSlotEntries();
  if (!entries.length) return;
  const hasFinalLock = entries.some(e => {
    const r = String(e.slot?.room || '').trim();
    return r && !isScheduleRoomSlotPending(e.slot);
  });
  if (hasFinalLock) {
    showScheduleRoomCellToast('该课程已锁定教室，请先撤回后再排');
    return;
  }
  const need = getScheduleActiveRoomPeriodNeed();
  const wd = Number(need?.weekday || weekday);
  const pf = need?.periodFrom ?? periodNo;
  const pt = need?.periodTo ?? periodNo;
  const roomKey = String(room || '').trim();
  const ownPendingRooms = new Set(
    entries
      .map(e => scheduleRoomPendingBySlot.get(e.slot?.id)?.room || (isScheduleRoomSlotPending(e.slot) ? e.slot.room : ''))
      .filter(Boolean)
      .map(r => String(r).trim())
  );
  const tasks = getScheduleDetailTasks();
  const weekFilter = getScheduleDetailTimetableWeekFilter();
  for (let p = pf; p <= pt; p++) {
    const st = getScheduleRoomCellState(roomKey, wd, p, tasks, weekFilter);
    if (st === 'locked') {
      openScheduleRoomOccupiedTimeConflictModal(roomKey, wd, p);
      return;
    }
    if (st === 'pending' && !ownPendingRooms.has(roomKey)) {
      showScheduleRoomCellToast('该时段已被待定占用，请重新选择');
      return;
    }
  }
  const conf = detectScheduleRoomAssignConflicts(entries, roomKey);
  if (conf.hasConflict) {
    const pending = conf.canContinue
      ? {
        action: 'roomAssign',
        run: () => commitScheduleRoomCellPending(roomKey, weekday, periodNo)
      }
      : null;
    openSchedulePlaceConflictModal(conf, pending);
    return;
  }
  commitScheduleRoomCellPending(roomKey, weekday, periodNo);
}

function lockScheduleRoomEntries(entries) {
  if (scheduleDetailPhase !== 'room' || isScheduleDetailReadonly()) return false;
  if (!entries?.length) return false;
  const taskSet = new Set();
  let changed = false;
  entries.forEach(({ task, slot }) => {
    if (!slot?.id || !isScheduleRoomSlotPending(slot)) return;
    clearScheduleRoomSlotPending(slot);
    taskSet.add(task);
    changed = true;
  });
  if (!changed) return false;
  taskSet.forEach(task => persistTaskSchedule(task));
  markScheduleDirty();
  renderScheduleDetailPage();
  renderScheduleConflictPage();
  renderSchedulePublishPage();
  return true;
}

function lockScheduleRoomHold() {
  if (scheduleDetailPhase !== 'room') return;
  lockScheduleRoomEntries(getScheduleRoomPendingHoldForSelected());
}

function revokeScheduleRoomEntries(entries) {
  if (scheduleDetailPhase !== 'room' || isScheduleDetailReadonly()) return false;
  if (!entries?.length) return false;
  const taskSet = new Set();
  let changed = false;
  entries.forEach(({ task, slot }) => {
    if (!slot?.id) return;
    let slotChanged = false;
    if (isScheduleRoomSlotPending(slot)) {
      clearScheduleRoomSlotPending(slot);
      slotChanged = true;
    }
    if (String(slot.room || '').trim()) {
      slot.room = '';
      slotChanged = true;
    }
    if (slotChanged) {
      taskSet.add(task);
      changed = true;
    }
  });
  if (!changed) return false;
  taskSet.forEach(task => {
    persistTaskSchedule(task);
    syncScheduleTaskRoom(task);
  });
  markScheduleDirty();
  renderScheduleDetailPage();
  renderScheduleConflictPage();
  renderSchedulePublishPage();
  return true;
}

function revokeScheduleRoomHold() {
  if (scheduleDetailPhase !== 'room') return;
  revokeScheduleRoomEntries(getScheduleSelectedSlotEntries());
}

function onScheduleRoomGridCellClick(room, weekday, periodNo, ev) {
  if (scheduleGridSuppressClick) { scheduleGridSuppressClick = false; return; }
  if (scheduleDetailPhase !== 'room' || isScheduleDetailReadonly()) return;
  if (!hasScheduleRoomTimetableCourseContext()) return;
  ev?.stopPropagation?.();
  const tasks = getScheduleDetailTasks();
  const weekFilter = getScheduleDetailTimetableWeekFilter();
  const state = getScheduleRoomCellState(room, weekday, periodNo, tasks, weekFilter);
  if (state === 'pending' && !isOwnScheduleRoomPendingCell(room, weekday, periodNo, tasks, weekFilter)) {
    // 待定占用：提示换教室，不作为「教室时间冲突」
    showScheduleRoomCellToast('该时段已被待定占用，请重新选择');
    return;
  }
  if (state === 'locked') {
    if (isOwnScheduleRoomLockedCell(room, weekday, periodNo, tasks, weekFilter)) {
      showScheduleRoomCellToast('该课程已锁定教室，请先撤回后再排');
      return;
    }
    // 他课已派教室占用 = 教室时间冲突
    openScheduleRoomOccupiedTimeConflictModal(room, weekday, periodNo);
    return;
  }
  const periodNeed = getScheduleActiveRoomPeriodNeed();
  if (!isScheduleRoomPeriodInCourseTime(periodNo, periodNeed)) {
    showScheduleRoomCellToast('该节次不在当前课程上课时间内');
    return;
  }
  assignScheduleRoomCellPending(room, weekday, periodNo);
}

function hasScheduleRoomTimetableCourseContext() {
  return scheduleDetailPhase === 'room'
    && scheduleActiveFromCourseList
    && !!scheduleActiveTaskId;
}

function getScheduleRoomTimetableBasePool() {
  const ctx = scheduleBatchDetailContext;
  let rows = (SCHEDULE_ROOM_META || []).slice();
  if (ctx?.type === 'venueType' && ctx.venueType) {
    rows = rows.filter(r => {
      const roomType = r.roomType || r.classroomTypeZh || r.classroomType || '';
      const cat = getVenueCategoryForClassroomType(roomType) || mapScheduleVenueTypeValue(roomType);
      return cat === ctx.venueType;
    });
  }
  const lockedRooms = scheduleRoomFilterLockedRooms.length
    ? scheduleRoomFilterLockedRooms
    : getScheduleActiveRoomLockedRooms();
  if (lockedRooms.length) {
    const set = new Set(lockedRooms.map(r => String(r).trim()).filter(Boolean));
    return rows.filter(r => set.has(String(r.room || '').trim()));
  }
  const cardVenueTypes = getScheduleActiveRoomCardVenueTypes();
  if (cardVenueTypes.length) {
    rows = rows.filter(r => scheduleRoomMatchesVenueTypeFilters(r, cardVenueTypes));
  }
  return rows;
}

function isScheduleRoomLockedByOthers(room, lockIndex) {
  return !!getScheduleRoomLockInfo(room, lockIndex)?.locked;
}

function applyScheduleRoomTimetableUserFilters(rows) {
  if (!scheduleRoomTimetableFilterApplied) return rows;
  const f = scheduleRoomTimetableFilterApplied;
  return (rows || []).filter(r => {
    if (f.room) {
      const q = String(f.room).trim().toLowerCase();
      const name = String(r.room || '').trim().toLowerCase();
      if (!name.includes(q)) return false;
    }
    if (f.building && r.building !== f.building) return false;
    if (f.roomType) {
      const rt = r.roomType || r.classroomTypeZh || '';
      if (rt !== f.roomType) return false;
    }
    if (f.venueType && !scheduleRoomMatchesVenueTypeFilters(r, [f.venueType])) return false;
    if (f.seatsMin != null || f.seatsMax != null) {
      const seats = getScheduleRoomAvailableSeats(r);
      if (f.seatsMin != null && seats < f.seatsMin) return false;
      if (f.seatsMax != null && seats > f.seatsMax) return false;
    }
    if (f.equipment && String(r.equipment || '') !== f.equipment) return false;
    if (f.software && String(r.software || '') !== f.software) return false;
    if (f.remark) {
      const rm = getScheduleRoomInfoRemark(r);
      if (rm !== f.remark) return false;
    }
    return true;
  });
}

function getScheduleRoomTimetableHasMoreRows() {
  if (!hasScheduleRoomTimetableCourseContext() || scheduleRoomTimetableExpanded) return false;
  const lockIndex = buildScheduleLockedRoomOwnerIndex();
  const all = applyScheduleRoomTimetableUserFilters(getScheduleRoomTimetableBasePool());
  const unlocked = all.filter(r => !isScheduleRoomLockedByOthers(r.room, lockIndex));
  return all.length > unlocked.length;
}

function ensureScheduleRoomTimetableFilterOptions() {
  if (scheduleDetailPhase !== 'room') return;
  const pool = getScheduleRoomTimetableBasePool();
  const fill = (id, values) => {
    const sel = scheduleDetailEl(id);
    if (!sel) return;
    const cur = sel.value || '';
    const vals = [...new Set(values.filter(v => v !== undefined && v !== null && String(v).trim() !== ''))];
    vals.sort((a, b) => String(a).localeCompare(String(b), 'zh-CN'));
    sel.innerHTML = '<option value="">全部</option>' + vals.map(v =>
      `<option value="${escapeHtml(String(v))}">${escapeHtml(String(v))}</option>`
    ).join('');
    if (cur && vals.some(v => String(v) === cur)) sel.value = cur;
    else sel.value = scheduleRoomTimetableFilterDraft[id.replace('srtf-', '').replace('room-type', 'roomType').replace('venue-type', 'venueType')] || '';
  };
  fill('srtf-building', pool.map(r => r.building));
  fill('srtf-room-type', pool.map(r => r.roomType || r.classroomTypeZh || ''));
  const venueSel = scheduleDetailEl('srtf-venue-type');
  if (venueSel) {
    const cur = venueSel.value || '';
    venueSel.innerHTML = '<option value="">全部</option>' + getScheduleRoomTypeFilterValues().map(v =>
      `<option value="${escapeHtml(v)}">${escapeHtml(getScheduleVenueTypeLabel(v))}</option>`
    ).join('');
    venueSel.value = cur || scheduleRoomTimetableFilterDraft.venueType || '';
  }
  fill('srtf-equipment', pool.map(r => r.equipment));
  fill('srtf-software', pool.map(r => r.software));
  fill('srtf-remark', pool.map(r => getScheduleRoomInfoRemark(r)).filter(Boolean));
}

function readScheduleRoomTimetableFilterDraftFromDom() {
  const draft = {};
  const room = scheduleDetailEl('srtf-room')?.value || '';
  const building = scheduleDetailEl('srtf-building')?.value || '';
  const roomType = scheduleDetailEl('srtf-room-type')?.value || '';
  const venueType = scheduleDetailEl('srtf-venue-type')?.value || '';
  const seatsMinRaw = scheduleDetailEl('srtf-seats-min')?.value || '';
  const seatsMaxRaw = scheduleDetailEl('srtf-seats-max')?.value || '';
  const seatsMin = Number(seatsMinRaw);
  const seatsMax = Number(seatsMaxRaw);
  const equipment = scheduleDetailEl('srtf-equipment')?.value || '';
  const software = scheduleDetailEl('srtf-software')?.value || '';
  const remark = scheduleDetailEl('srtf-remark')?.value || '';
  if (room.trim()) draft.room = room.trim();
  if (building) draft.building = building;
  if (roomType) draft.roomType = roomType;
  if (venueType) draft.venueType = venueType;
  if (seatsMinRaw && !Number.isNaN(seatsMin)) draft.seatsMin = seatsMin;
  if (seatsMaxRaw && !Number.isNaN(seatsMax)) draft.seatsMax = seatsMax;
  if (equipment) draft.equipment = equipment;
  if (software) draft.software = software;
  if (remark) draft.remark = remark;
  return draft;
}

function syncScheduleRoomOnlyDetailPanels() {
  const isRoom = scheduleDetailPhase === 'room';
  ['schedule-detail-room-filter-panel', 'schedule-room-hold-bar'].forEach(id => {
    const el = scheduleDetailEl(id);
    if (!el) return;
    el.hidden = !isRoom;
    if (!isRoom) el.style.display = 'none';
    else el.style.display = '';
  });
  const viewSettings = scheduleDetailEl('schedule-detail-view-settings');
  if (viewSettings) {
    viewSettings.hidden = isRoom;
    viewSettings.style.display = isRoom ? 'none' : '';
  }
}

function syncScheduleRoomTimetableFilterPanel() {
  syncScheduleRoomOnlyDetailPanels();
  if (scheduleDetailPhase !== 'room') return;
  ensureScheduleRoomTimetableFilterOptions();
}

function queryScheduleRoomTimetableFilter() {
  if (scheduleDetailPhase !== 'room') return;
  scheduleRoomTimetableFilterDraft = readScheduleRoomTimetableFilterDraftFromDom();
  scheduleRoomTimetableFilterApplied = { ...scheduleRoomTimetableFilterDraft };
  // 锁定教室并集模式下场地类型仅回显，不参与二次过滤
  if (scheduleRoomFilterMode === 'lockedRoom' && scheduleRoomFilterLockedRooms.length) {
    delete scheduleRoomTimetableFilterApplied.venueType;
    scheduleRoomTimetableFilterApplied.lockedRoomUnion = true;
  }
  renderScheduleDetailPage();
}

function resetScheduleRoomTimetableFilter() {
  if (scheduleDetailPhase !== 'room') return;
  scheduleRoomTimetableExpanded = false;
  scheduleRoomTimetableFilterDraft = {};
  scheduleRoomTimetableFilterApplied = null;
  SCHEDULE_ROOM_TIMETABLE_FILTER_FIELDS.forEach(f => {
    const el = scheduleDetailEl(f.id);
    if (el) {
      el.value = '';
      if (f.id === 'srtf-venue-type') el.disabled = false;
    }
  });
  SCHEDULE_ROOM_TIMETABLE_SEAT_RANGE_FIELDS.forEach(id => {
    const el = scheduleDetailEl(id);
    if (el) el.value = '';
  });
  SCHEDULE_ROOM_TIMETABLE_TEXT_FIELDS.forEach(id => {
    const el = scheduleDetailEl(id);
    if (el) el.value = '';
  });
  syncScheduleRoomFilterFromActiveCard();
  renderScheduleDetailPage();
}

function toggleScheduleRoomTimetableExpand() {
  if (scheduleDetailPhase !== 'room') return;
  scheduleRoomTimetableExpanded = !scheduleRoomTimetableExpanded;
  renderScheduleDetailPage();
}

/** 排教室课表行：教室清单（场地类型 / 锁定教室并集 + 匹配度排序） */
function getScheduleRoomTimetableRows() {
  if (scheduleDetailPhase !== 'room') return [];
  const lockIndex = buildScheduleLockedRoomOwnerIndex();
  const tasks = getScheduleDetailTasks();
  const weekFilter = getScheduleDetailTimetableWeekFilter();
  const need = getScheduleActiveRoomPeriodNeed();
  const hasCourseCtx = hasScheduleRoomTimetableCourseContext();
  let rows = getScheduleRoomTimetableBasePool();
  // 未选课程：展示全部教室（含已锁定）；选中课程后默认仅未锁定，可展开更多
  if (hasCourseCtx && !scheduleRoomTimetableExpanded) {
    rows = rows.filter(r => !isScheduleRoomLockedByOthers(r.room, lockIndex));
  }
  rows = applyScheduleRoomTimetableUserFilters(rows);
  return rows.sort((a, b) => {
    const seatDiff = getScheduleRoomAvailableSeats(a) - getScheduleRoomAvailableSeats(b);
    if (seatDiff !== 0) return seatDiff;
    if (!hasCourseCtx || !need) {
      return String(a.room || '').localeCompare(String(b.room || ''), 'zh-CN');
    }
    const scoreA = scoreScheduleRoomTimeMatch(a.room, need, tasks, weekFilter);
    const scoreB = scoreScheduleRoomTimeMatch(b.room, need, tasks, weekFilter);
    if (scoreA.tier !== scoreB.tier) return scoreA.tier - scoreB.tier;
    if (scoreA.tier <= 1 && scoreB.freeBonus !== scoreA.freeBonus) return scoreB.freeBonus - scoreA.freeBonus;
    if (scoreA.tier === 2 && scoreB.overlapRatio !== scoreA.overlapRatio) return scoreB.overlapRatio - scoreA.overlapRatio;
    return String(a.room || '').localeCompare(String(b.room || ''), 'zh-CN');
  });
}

/**
 * 排教室侧课程列表行：仅含已排时间节次的学时单元（按学时类型分行，不去重）。
 * 按时间/场地类型详情作用域时，仅保留匹配节次的学时单元。
 * opts.ignoreDetailScope=true：菜单汇总等场景忽略当前详情作用域。
 */
function getScheduleRoomCourseRows(tasks, opts = {}) {
  const ctx = scheduleBatchDetailContext;
  const scoped = !opts.ignoreDetailScope
    && ctx
    && (ctx.phase || scheduleDetailPhase) === 'room'
    && (ctx.type === 'weekday' || ctx.type === 'venueType');
  return getScheduleUnitRows(tasks).filter(row => {
    if (!taskHasScheduledTimeSlots(row.task)) return false;
    const key = normalizeScheduleHourKey(row.unit.key);
    return normalizeTaskTimeSlots(row.task).some(s => {
      if (!s.weekday || !s.periodFrom) return false;
      if (key !== 'merged' && getScheduleSlotHourKey(row.task, s) !== key) return false;
      if (scoped && !scheduleRoomSlotMatchesDetailScope(s, row.task, ctx)) return false;
      if (!scheduleRoomSlotIsAssignable(s, row.task)) return false;
      return true;
    });
  });
}

/** 某学时单元的排教室完成态（按该学时类型下已排节次是否都有 room；尊重详情作用域） */
function getScheduleUnitRoomArrangeState(task, hourKey) {
  const ctx = scheduleBatchDetailContext;
  const scoped = ctx && (ctx.phase || scheduleDetailPhase) === 'room'
    && (ctx.type === 'weekday' || ctx.type === 'venueType');
  if (scoped) {
    return getScheduleUnitRoomArrangeStateFiltered(task, hourKey, (slot, t) =>
      scheduleRoomSlotMatchesDetailScope(slot, t, ctx)
    );
  }
  return getScheduleUnitRoomArrangeStateFiltered(task, hourKey, (slot, t) =>
    scheduleRoomSlotIsAssignable(slot, t)
  );
}

function renderScheduleDetailCourseList(tasks, activeTaskId) {
  const mount = scheduleDetailEl('schedule-detail-course-list');
  if (!mount) return;
  const isRoom = scheduleDetailPhase === 'room';
  const pendingLabelEl = scheduleDetailEl('schedule-detail-course-tabs')?.querySelector('[data-sch-tab-pending-label]');
  const doneLabelEl = scheduleDetailEl('schedule-detail-course-tabs')?.querySelector('[data-sch-tab-done-label]');
  if (pendingLabelEl) pendingLabelEl.textContent = '未排完';
  if (doneLabelEl) doneLabelEl.textContent = '已排完';
  syncScheduleDetailCourseTabs();

  if (isRoom) {
    const cards = getScheduleRoomMergedCards(tasks);
    const unset = cards.filter(c => getScheduleRoomMergedCardArrangeStatus(c) === 'unset');
    const hold = cards.filter(c => getScheduleRoomMergedCardArrangeStatus(c) === 'hold');
    const locked = cards.filter(c => getScheduleRoomMergedCardArrangeStatus(c) === 'locked');
    const allCountEl = scheduleDetailEl('schedule-tab-all-count');
    const unsetCountEl = scheduleDetailEl('schedule-tab-unset-count');
    const holdCountEl = scheduleDetailEl('schedule-tab-hold-count');
    const lockedCountEl = scheduleDetailEl('schedule-tab-locked-count');
    if (allCountEl) allCountEl.textContent = cards.length;
    if (unsetCountEl) unsetCountEl.textContent = unset.length;
    if (holdCountEl) holdCountEl.textContent = hold.length;
    if (lockedCountEl) lockedCountEl.textContent = locked.length;
    const tab = normalizeScheduleCourseTab(scheduleCourseTab);
    const list = tab === 'unset' ? unset
      : (tab === 'hold' ? hold
        : (tab === 'locked' ? locked : cards));
    let html = list.map(card => {
      const status = getScheduleRoomMergedCardArrangeStatus(card);
      const active = scheduleActiveFromCourseList
        && card.primaryTaskId === activeTaskId
        && card.slotIds.length
        && card.slotIds.every(id => scheduleSelectedSlotIds.has(id))
        ? ' is-active' : '';
      const statusCls = status === 'locked' ? ' is-done'
        : (status === 'hold' ? ' is-hold' : '');
      const checked = card.unitIds.length && card.unitIds.every(id => scheduleDetailSelectedIds.has(id))
        ? ' checked' : '';
      const groupText = card.groupTotal > 0
        ? `${card.groupLabel}（${card.groupTotal}）`
        : card.groupLabel;
      const roomStatusIcon = getScheduleRoomMergedCardStatusIconHtml(card);
      const scopeType = getScheduleScopeType(scheduleBatchDetailContext);
      // 按时间排：场地类型可跳转按场地类型排；按场地类型排：星期可跳转按时间排
      const timeHtml = scopeType === 'venueType'
        ? formatScheduleRoomWeekdayJumpTimeHtml(card)
        : escapeHtml(card.timeLabel || '—');
      const venueHtml = scopeType === 'weekday'
        ? formatScheduleRoomVenueTypeJumpHtml(card)
        : escapeHtml(card.venueLabel || '—');
      return `<li class="schedule-detail-course-li">
        <label class="schedule-detail-course-check" onclick="event.stopPropagation()">
          <input type="checkbox"${checked} onchange="toggleScheduleRoomMergedCardCheck('${escapeHtml(card.mergeId)}', this.checked)">
        </label>
        <button type="button" class="schedule-detail-course-item${active}${statusCls}" onclick="selectScheduleRoomMergedCard('${escapeHtml(card.mergeId)}')">
          <span class="schedule-detail-course-code">${escapeHtml(card.codeLabel)}${roomStatusIcon}</span>
          <span class="schedule-detail-course-fields">
            <span class="sdc-field"><i class="sdc-k">上课小组</i><b class="sdc-v sdc-v-wrap">${escapeHtml(groupText)}</b></span>
            <span class="sdc-field"><i class="sdc-k">计划人数</i><b class="sdc-v">${card.planned || '—'}</b></span>
            <span class="sdc-field"><i class="sdc-k">上限人数</i><b class="sdc-v">${card.limit || '—'}</b></span>
            <span class="sdc-field"><i class="sdc-k">教师</i><b class="sdc-v sdc-v-wrap">${escapeHtml(card.teacherLabel || '—')}</b></span>
            <span class="sdc-field"><i class="sdc-k">起止周</i><b class="sdc-v sdc-v-wrap">${escapeHtml(card.weeks)}</b></span>
            <span class="sdc-field"><i class="sdc-k">节次时间</i><b class="sdc-v sdc-v-wrap">${timeHtml}</b></span>
            <span class="sdc-field"><i class="sdc-k">场地类型</i><b class="sdc-v sdc-v-wrap${scopeType === 'weekday' ? ' sdc-v-teachers' : ''}">${venueHtml}</b></span>
            <span class="sdc-field"><i class="sdc-k">锁定教室</i><b class="sdc-v sdc-v-wrap">${escapeHtml(card.lockedRoomLabel)}</b></span>
            <span class="sdc-field"><i class="sdc-k">场地备注</i><b class="sdc-v sdc-v-wrap">${escapeHtml(card.remarkLabel)}</b></span>
          </span>
        </button>
      </li>`;
    }).join('');
    if (!html) {
      const emptyMsg = tab === 'locked'
        ? '暂无已锁定教室的节次'
        : (tab === 'hold'
          ? '暂无待定教室的节次'
          : (tab === 'unset' ? '暂无未排教室的节次' : '暂无已排课表节次'));
      html = `<li class="text-muted" style="padding:12px;font-size:12px">${emptyMsg}</li>`;
    }
    mount.innerHTML = html;
    return;
  }

  // 排时间侧与菜单页同口径（课程已在 getScheduleDetailTasks 截断，学时单元≤10）
  const rows = getScheduleTimeArrangeUnitRows(tasks);
  const activeHourKey = getScheduleActiveHourKey();
  const pending = rows.filter(r => !r.unit.complete);
  const done = rows.filter(r => r.unit.complete);
  const allCountEl = scheduleDetailEl('schedule-tab-all-count');
  const pendingCountEl = scheduleDetailEl('schedule-tab-pending-count');
  const doneCountEl = scheduleDetailEl('schedule-tab-done-count');
  if (allCountEl) allCountEl.textContent = rows.length;
  if (pendingCountEl) pendingCountEl.textContent = pending.length;
  if (doneCountEl) doneCountEl.textContent = done.length;
  const tabHost = scheduleDetailEl('schedule-detail-course-tabs');
  tabHost?.querySelectorAll('.schedule-detail-tab').forEach(btn => {
    btn.classList.toggle('is-active', btn.dataset.tab === scheduleCourseTab);
  });
  const renderItem = (row) => {
    const { task, unit, unitId } = row;
    const itemDone = !!unit.complete;
    const active = (task.id === activeTaskId && unit.key === activeHourKey) ? ' is-active' : '';
    const doneCls = itemDone ? ' is-done' : '';
    const checked = scheduleDetailSelectedIds.has(unitId) ? ' checked' : '';
    const weeksLabel = getScheduleCourseWeeksLabel(task, unit.key);
    const weeklyHours = getScheduleUnitWeeklyHours(task, unit.key);
    const weeklyLabel = weeklyHours > 0 ? String(weeklyHours) : '—';
    const hoursCls = unit.done > unit.total ? 'hr-over' : (unit.complete ? 'hr-done' : 'hr-todo');
    const hourTypeLabel = unit.label || getScheduleHourTypeLabel(unit.key);
    const statusField = `<span class="sdc-field sdc-field-status"><i class="sdc-k">${escapeHtml(hourTypeLabel || '学时')}</i><b class="sdc-v ${hoursCls}">${unit.done}/${unit.total}</b></span>`;
    const sharedFields = `<span class="sdc-field"><i class="sdc-k">上课小组</i><b class="sdc-v sdc-v-wrap">${escapeHtml(formatScheduleGroupNamesWithCount(task, unit.key))}</b></span>
          <span class="sdc-field"><i class="sdc-k">授课教师</i><b class="sdc-v sdc-v-wrap sdc-v-teachers">${formatScheduleTeacherNameLinksHtml(task)}</b></span>`;
    const hoursStatusIcon = getScheduleUnitHoursStatusIconHtml(unit);
    return `<li class="schedule-detail-course-li">
      <label class="schedule-detail-course-check" onclick="event.stopPropagation()">
        <input type="checkbox"${checked} onchange="toggleScheduleDetailCourseCheck('${escapeHtml(unitId)}', this.checked)">
      </label>
      <button type="button" class="schedule-detail-course-item${active}${doneCls}" onclick="selectScheduleDetailCourse('${escapeHtml(task.id)}','${escapeHtml(unit.key)}')">
        <span class="schedule-detail-course-code">${escapeHtml(formatScheduleCourseCode(task.code))}${hoursStatusIcon}</span>
        <span class="schedule-detail-course-fields">
          ${sharedFields}
          <span class="sdc-field"><i class="sdc-k">起止周</i><b class="sdc-v">${escapeHtml(weeksLabel)}</b></span>
          <span class="sdc-field"><i class="sdc-k">周学时</i><b class="sdc-v">${escapeHtml(weeklyLabel)}</b></span>
          ${statusField}
        </span>
      </button>
    </li>`;
  };
  const list = scheduleCourseTab === 'done' ? done : (scheduleCourseTab === 'pending' ? pending : rows);
  let html = list.map(renderItem).join('');
  if (!html) {
    const emptyMsg = scheduleCourseTab === 'done'
      ? '暂无已排完的学时'
      : (scheduleCourseTab === 'pending' ? '暂无未排完的学时' : '暂无课程');
    html = `<li class="text-muted" style="padding:12px;font-size:12px">${emptyMsg}</li>`;
  }
  mount.innerHTML = html;
}

function renderScheduleDetailSlotsTable(task) {
  const tbody = document.getElementById('schedule-detail-slots-body');
  if (!tbody) return;
  if (!task) {
    renderScheduleEmptyRow(tbody, 9, '请从左侧选择课程');
    return;
  }
  const slots = normalizeTaskTimeSlots(task);
  if (!slots.length) {
    renderScheduleEmptyRow(tbody, 9, '暂未安排时段，请在上方课表中点击空格添加');
    return;
  }
  tbody.innerHTML = slots.map((slot, idx) => `<tr>
    <td class="col-index">${idx + 1}</td>
    <td><code>${escapeHtml(formatScheduleCourseCode(task.code))}</code></td>
    <td>${escapeHtml(task.groupLabel || '—')}</td>
    <td class="col-center"><code>${escapeHtml(getScheduleTaskTeacherId(task))}</code></td>
    <td class="col-center">${escapeHtml(String(getScheduleTaskHours(task)))}</td>
    <td class="col-center">${escapeHtml(getScheduleWeekdayLabel(slot.weekday))}</td>
    <td class="col-center">${escapeHtml(formatScheduleSlotPeriodLabel(slot))}</td>
    <td>${escapeHtml(slot.weeks || task.weeks || '—')}</td>
    ${scheduleOpsCell(`openScheduleTimeslotModal('${escapeHtml(task.id)}','${escapeHtml(slot.id)}')`, `removeScheduleTaskSlot('${escapeHtml(task.id)}','${escapeHtml(slot.id)}')`)}
  </tr>`).join('');
}

function renderScheduleTimePage() {
  const tbody = document.getElementById('schedule-time-body');
  rebuildScheduleTermSelects();
  renderScheduleOfferingHint('schedule-time-hint');
  rebuildScheduleBatchFilterOptions();
  if (!ensureCourseOfferingPlan()) {
    renderScheduleEmptyRow(tbody, 11, '请先在「开课计划生成」中生成当前学期开课计划');
    return;
  }
  ensureScheduleGlobalDemo();
  let rows = filterScheduleBatchSummaryRows(buildScheduleBatchSummaries());
  const status = document.getElementById('schedule-time-filter-status')?.value || '';
  rows = filterScheduleArrangeRowsByStatus(rows, status);
  if (!rows.length) {
    renderScheduleEmptyRow(tbody, 11, status ? '暂无匹配记录' : '暂无专业批次数据，请先在开课管理中完成合分班');
    return;
  }
  tbody.innerHTML = rows.map((row, idx) => {
    const canArrange = canScheduleArrangeAction('time', row.programmeKey);
    const programmeCode = row.programmeCode || getProgrammeCode(row.programmeKey) || '—';
    return `<tr>
    <td class="col-index">${idx + 1}</td>
    <td><code>${formatIntakeDisplay(row.intake)}</code></td>
    <td class="col-center"><code>${escapeHtml(programmeCode)}</code></td>
    <td>${escapeHtml(row.programmeName)}</td>
    <td class="col-center"><code>${escapeHtml(row.schoolCode)}</code></td>
    <td class="col-center">${row.courseCount}</td>
    <td class="col-center">${row.groupCount || 0}</td>
    <td class="col-center">${row.doneUnits}</td>
    <td class="col-center">${row.pendingUnits ? `<span class="status draft">${row.pendingUnits}</span>` : '0'}</td>
    <td class="col-center">${renderScheduleArrangeStatusBadge(row)}</td>
    <td class="col-center actions">
      ${renderScheduleDetailLaunchLink({ type: 'batch', programmeKey: row.programmeKey, intake: row.intake }, 'time', canArrange ? '排课' : '查看')}
    </td>
  </tr>`;
  }).join('');
}

/*
function renderScheduleTimePageOld() {
  // 原教学班平铺列表已改为批次汇总 + 详情页排课
}
*/

function renderScheduleDetailPage() {
  const titleEl = scheduleDetailEl('schedule-time-detail-title');
  const weeksEl = scheduleDetailEl('schedule-detail-weeks');
  const ctx = scheduleBatchDetailContext;
  if (!ctx) {
    renderScheduleDetailCourseList([], null);
    renderScheduleTimetableGrid('', [], null);
    return;
  }
  ensureScheduleTasksFromOffering();
  scheduleDetailPhase = ctx.phase || scheduleDetailPhase || 'time';
  if (titleEl) titleEl.textContent = getScheduleDetailTitle();
  wireScheduleDetailBackControls();
  const rootEl = scheduleDetailEl('schedule-detail-breadcrumb-root');
  const midEl = scheduleDetailEl('schedule-detail-breadcrumb-mid');
  if (rootEl) rootEl.textContent = getScheduleDetailBackLabel();
  if (midEl) midEl.textContent = getScheduleDetailMidLabel();
  const readonly = isScheduleDetailReadonly();
  const pageRoot = document.querySelector('.schedule-detail-page.active')
    || document.getElementById(scheduleDetailPhase === 'room' ? 'page-schedule-room-detail' : 'page-schedule-time-detail');
  if (pageRoot) pageRoot.classList.toggle('is-schedule-readonly', readonly);
  syncScheduleViewSettingControls();
  renderScheduleScopeSwitcher();
  const tasks = getScheduleDetailTasks()
    .sort((a, b) => a.code.localeCompare(b.code));
  if (scheduleDetailPhase === 'room') syncScheduleRoomPendingMapFromTasks(tasks);
  // 排教室侧：当前选中课若不在合并节次列表中则清空选中
  if (scheduleDetailPhase === 'room' && scheduleActiveTaskId) {
    const listed = getScheduleRoomMergedCards(tasks);
    if (!listed.some(c => c.primaryTaskId === scheduleActiveTaskId || c.entries.some(e => e.task.id === scheduleActiveTaskId))) {
      scheduleActiveTaskId = null;
      scheduleActiveHourType = '';
      scheduleSelectedSlotIds.clear();
    }
  } else if (scheduleActiveTaskId && !tasks.some(t => t.id === scheduleActiveTaskId)) {
    scheduleActiveTaskId = null;
    scheduleActiveHourType = '';
  }
  // 不再默认选中课程，需用户从左侧列表主动点击
  const activeTask = tasks.find(t => t.id === scheduleActiveTaskId) || null;
  if (activeTask) {
    const activeHourKey = getScheduleActiveHourKey();
    scheduleActiveHourType = activeHourKey;
  } else {
    scheduleActiveHourType = '';
  }
  const activeHourKey = scheduleActiveHourType;
  // 切换排课单元时同步新排草稿；重渲染时保留仍有效的节次选中（避免设置场地保存后丢失）
  const activeUnitId = activeTask ? scheduleUnitId(activeTask.id, activeHourKey) : null;
  if (scheduleDraftForTaskId !== activeUnitId) {
    const prevSelected = new Set(scheduleSelectedSlotIds);
    initScheduleDraftForTask(activeTask);
    if (prevSelected.size) {
      const validIds = new Set();
      tasks.forEach(t => {
        normalizeTaskTimeSlots(t).forEach(s => {
          if (s?.id && prevSelected.has(s.id)) validIds.add(s.id);
        });
      });
      scheduleSelectedSlotIds = validIds;
    }
  }
  renderScheduleDetailCourseList(tasks, scheduleActiveTaskId);
  const term = getActiveOfferingTermSetting()?.termCode || getSelectedScheduleTimeSettingTerm();
  renderScheduleTimetableGrid(term, tasks, scheduleActiveTaskId);
  if (weeksEl) weeksEl.value = scheduleWeekSource();
  renderScheduleDetailWeekGrid(activeTask);
  renderScheduleDetailRoom(activeTask);
  syncScheduleRetakeDetectPanel();
  syncScheduleRoomTimetableFilterPanel();
  renderScheduleRoomHoldActions();
  renderScheduleRoomGridFooter();
  // 排教室侧：取消课表卡片「排课场地」勾选项
  const cardRoomOpt = scheduleDetailEl('sch-card-room')?.closest('.schedule-view-opt');
  if (cardRoomOpt) cardRoomOpt.hidden = scheduleDetailPhase === 'room';
  renderScheduleDetailModeUi(activeTask);
  renderScheduleDetailSaveStatus();
  updateScheduleUndoBar(tasks);
}

/** 课表查询（入学批次）底部：展示「是否排课」为否的课程 */
function renderScheduleIntakeNoScheduleList(programmeKey, intake) {
  const mount = document.getElementById('schedule-intake-tt-no-schedule');
  const body = document.getElementById('schedule-intake-tt-no-schedule-body');
  if (!mount || !body) return;
  const rows = getScheduleNoScheduleTasksForBatch(programmeKey, intake);
  mount.hidden = !rows.length;
  if (!rows.length) {
    body.innerHTML = '';
    return;
  }
  body.innerHTML = rows.map(task => `<tr>
    <td><code>${escapeHtml(formatScheduleCourseCode(task.code))}</code></td>
    <td>${escapeHtml(task.name || '—')}</td>
    <td>${escapeHtml(formatScheduleTeacherIdName(task))}</td>
    <td>${escapeHtml(formatScheduleGroupNames(task))}</td>
    <td>${escapeHtml(getScheduleCourseWeeksLabel(task))}</td>
  </tr>`).join('');
}

/** 更新「已排教室将随改时间清空」校验提示（仅排时间侧重排时） */
function updateScheduleRoomClearHint(entries, { isRoom = false, readonly = false } = {}) {
  const hint = scheduleDetailEl('schedule-detail-room-clear-hint');
  if (!hint) return;
  const list = entries || [];
  const hasAssignedRoom = !isRoom && !readonly && list.length > 0
    && list.some(e => String(e.slot?.room || '').trim());
  hint.hidden = !hasAssignedRoom;
  if (!hasAssignedRoom) return;
  hint.className = 'schedule-detail-op-hint is-warn';
  hint.innerHTML = list.length === 1
    ? '<strong>校验提示：</strong>该节次已经安排上课教室，更改时间后将清空已排教室。'
    : '<strong>校验提示：</strong>所选节次中已有安排上课教室，更改时间后将清空已排教室。';
}

/** 根据是否选中节次，更新编辑提示、按钮显隐与提示文案 */
function renderScheduleDetailModeUi(activeTask) {
  const editHint = scheduleDetailEl('schedule-detail-edit-hint');
  const tip = scheduleDetailEl('schedule-timetable-tip');
  const cancelBtn = scheduleDetailEl('btn-schedule-slot-cancel');
  const saveBtn = scheduleDetailEl('btn-schedule-save');
  const undoBtn = scheduleDetailEl('btn-schedule-undo');
  const isRoom = scheduleDetailPhase === 'room';
  const readonly = isScheduleDetailReadonly();
  const legendHost = scheduleDetailEl('schedule-conflict-legend');
  if (legendHost) {
    legendHost.hidden = false;
    legendHost.style.display = '';
    legendHost.querySelectorAll('[data-sch-leg]').forEach(el => {
      const kind = el.getAttribute('data-sch-leg');
      // 排时间侧不展示教室冲突图例；排教室侧仅展示教室三类冲突；预重修图例仅重修检测进行中显示
      let show = isRoom ? kind === 'room' : kind === 'time';
      if (kind === 'retake') show = !isRoom && isScheduleRetakeDetectActive();
      el.hidden = !show;
      el.style.display = show ? '' : 'none';
    });
  }
  if (saveBtn) saveBtn.disabled = !activeTask || readonly;
  const entries = getScheduleSelectedSlotEntries();
  const count = entries.length;
  if (cancelBtn) {
    cancelBtn.hidden = !count || isRoom || readonly;
    cancelBtn.textContent = count > 1 ? `取消排所选 ${count} 个时段` : '取消排该时段';
  }
  if (undoBtn && readonly) undoBtn.disabled = true;
  const weekGrid = scheduleDetailEl('schedule-detail-week-grid');
  if (weekGrid) weekGrid.classList.toggle('is-readonly', readonly);
  updateScheduleVenueSaveUi();
  if (readonly && !isRoom) {
    if (editHint) {
      editHint.className = 'schedule-detail-op-hint is-readonly';
      editHint.innerHTML = '<strong>查看模式：</strong>该范围已提交，仅可查看排课结果；可右键已排课程查看冲突，或单击冲突空格查看冲突信息，不可排课、修改场地或提交。';
    }
    updateScheduleRoomClearHint([], { isRoom, readonly });
    if (tip) tip.textContent = '已提交范围只读；可从左侧选择课程查看冲突着色，右键已排课程或单击带冲突色的空格查看冲突信息。';
    return;
  }
  if (isRoom) {
    syncScheduleRoomTimetableFilterPanel();
    renderScheduleRoomHoldActions();
    const weekFilterOn = !!(scheduleDetailViewWeeks && scheduleDetailViewWeeks.length);
    const weekScopeTip = weekFilterOn
      ? `当前仅针对第 ${scheduleDetailViewWeeks.join('、')} 周派教室（卡片周次同步显示所选周；超出部分保留原教室）。`
      : '';
    if (editHint) {
      editHint.className = 'schedule-detail-op-hint';
      const venueFilter = getScheduleActiveRoomCardVenueTypes();
      const lockedRooms = getScheduleActiveRoomLockedRooms();
      const venueFilterTip = lockedRooms.length
        ? `教室列表已按锁定教室（${lockedRooms.join('、')}）筛选。`
        : (venueFilter.length
          ? `教室列表已按场地类型「${formatScheduleVenueTypesLabel(venueFilter)}」筛选。`
          : '');
      editHint.innerHTML = activeTask
        ? `<strong>排课表教室：</strong>课表仅显示当前课程组已排节次；默认列出符合要求的未锁定教室，可点底部「展开更多教室」查看全部。点击空白节次格待定占用，再点「锁定」持久化派教室。${weekFilterOn ? '有周次筛选时课表仅显示所选周次。' : ''}${venueFilterTip ? `<br>${venueFilterTip}` : ''}冲突判定：教室时间（硬）、座位数（软）、场地类型。`
        : '<strong>排课表教室：</strong>未选课程时右侧展示全部教室及已占用节次；请从左侧选择课程后再派教室，也可使用下方教室筛选条件查询。';
    }
    updateScheduleRoomClearHint([], { isRoom, readonly });
    if (tip) {
      tip.textContent = activeTask
        ? (count > 1
          ? `已选 ${count} 个节次。${weekScopeTip || ''}点击有冲突色的节次可查看教室冲突明细。`
          : (weekScopeTip || '课表仅显示当前课程组；点击已排节次可选中查看，点击冲突空格可查看冲突信息。'))
        : (weekFilterOn
          ? `当前展示第 ${scheduleDetailViewWeeks.join('、')} 周已排节次；右侧为全部教室，请从左侧选择课程后派教室。`
          : '右侧展示全部教室；请从左侧选择课程后按上课时间派教室。');
    }
    return;
  }
  syncScheduleRoomOnlyDetailPanels();
  renderScheduleRoomHoldActions();
  if (count) {
    if (editHint) {
      editHint.className = 'schedule-detail-op-hint is-editing';
      const moveHint = count === 1 ? '，或点击课表空格移动其时间' : '，或点击课表空格整体平移';
      editHint.innerHTML = scheduleVenueSettingsRequested
        ? `<strong>重排模式</strong> — 修改上方周次可即时生效；场地类型 / 备注需点「保存」后写入所选节次${moveHint}。`
        : `<strong>重排模式</strong> — 修改上方周次可即时生效${moveHint}；右键已排节次可「设置场地类型」。冲突节次以颜色标记；点击已排课表或冲突空格可弹窗查看冲突信息。`;
    }
    updateScheduleRoomClearHint(entries, { isRoom, readonly });
    if (tip) {
      tip.textContent = scheduleVenueSettingsRequested
        ? (count === 1
          ? '修改场地后点「保存」；点击其他空格可移动该节次；「取消排该时段」删除所选。'
          : '修改场地后点「保存」；点击空格整体平移；「取消排所选」批量删除。')
        : (count === 1
          ? '点击其他空格可移动该节次时间；再点已排节次可加选/取消并查看冲突；右键可设置场地类型；「取消排该时段」删除所选。'
          : '点击空格将所选节次整体平移；继续点已排节次可加选/取消并查看冲突；右键可设置场地类型；「取消排所选」批量删除。');
    }
  } else {
    const retakeDetectTip = isScheduleRetakeDetectActive()
      ? '<br><strong>重修检测中：</strong>可继续从左侧选择课程并排课；落点会叠加检测着色冲突提醒，无需退出检测。'
      : '';
    if (editHint) {
      editHint.className = 'schedule-detail-op-hint';
      editHint.innerHTML = activeTask
        ? `<strong>新排模式：</strong>选中课程后设置周次，点击课表空格或已排格（卡片/空白）均可落点并检测冲突；场地类型默认取开课任务维护值，未维护时为普通教室。再次点击左侧课程可取消选中。<br><strong>重排模式：</strong>未选左侧课程时点击已排卡片可选中节次（不切换课程列表）；右键「设置场地类型」可改场地，或点击空格移动 / 整体平移。${retakeDetectTip}`
        : `请从左侧选择要排课的课程；未选中课程时课表展示全部已排课，点击已排卡片可选中节次（不关联左侧列表）。再次点击已选课程可取消选中。${retakeDetectTip}`;
    }
    updateScheduleRoomClearHint([], { isRoom, readonly });
    if (tip) {
      tip.textContent = activeTask
        ? (isScheduleRetakeDetectActive()
          ? '重修检测中仍可排课：课表按上方周次展示，点击空格或已排格空白落点；检测着色冲突会一并提醒。'
          : '课表按上方选中周次展示；点击空格或已排格均可按当前周次排课并检测冲突；右键已排节次可设置场地类型。')
        : (isScheduleRetakeDetectActive()
          ? '重修检测中：可直接右键空格查看检测冲突；也可从左侧选择课程后继续排课。'
          : '未选课程时课表显示全部已排课；点击已排卡片可选中节次（不切换左侧列表）；请先从左侧选择课程后再排课。');
    }
  }
}

/** 统计一组课程中未指定教室的已排节次数量（按节次维度） */
function countScheduleRoomPendingSlots(tasks) {
  let n = 0;
  (tasks || []).forEach(t => normalizeTaskTimeSlots(t).forEach(s => { if (!s.room) n++; }));
  return n;
}

/** 按教师聚合的排课行 */
function getScheduleTeacherGroupRows() {
  const map = new Map();
  getScheduleTaskRows().forEach(t => {
    getScheduleTaskTeacherEntries(t).forEach(({ staffId, name }) => {
      if (!map.has(staffId)) map.set(staffId, { teacherId: staffId, name, tasks: [] });
      const g = map.get(staffId);
      if (name && (!g.name || /[、,，;/；]/.test(g.name))) g.name = name;
      g.tasks.push(t);
    });
  });
  return [...map.values()].sort((a, b) => a.teacherId.localeCompare(b.teacherId)).map(g => {
    const tasks = consolidateScheduleTasksByCourse(g.tasks);
    const meta = SCHEDULE_TEACHER_META[g.teacherId] || {};
    const poolPick = buildMockTeacherPickerPool().find(t => t.staffId === g.teacherId);
    const stats = buildScheduleTimeArrangeMenuStats(tasks);
    const courseLabel = [...new Set(stats.scopedTasks.map(t => `${formatScheduleCourseCode(t.code)} ${t.name}`))].join('、');
    const schoolCode = poolPick?.schoolCode
      || tasks[0]?.schoolCode
      || getProgrammeSchoolCode(tasks[0]?.programmeKey)
      || '';
    return {
      teacherId: g.teacherId,
      name: resolveScheduleTeacherName(g.teacherId, meta.name || poolPick?.name || g.name),
      dept: meta.dept || poolPick?.departmentCode || '—',
      staffType: meta.staffType || poolPick?.teacherType || '—',
      schoolCode,
      tasks, courseLabel, courseCount: stats.courseCount,
      groupCount: stats.groupCount,
      doneUnits: stats.doneUnits,
      totalUnits: stats.groupCount,
      pendingUnits: stats.pendingUnits
    };
  });
}

function filterScheduleArrangeRowsByStatus(rows, status) {
  if (status === 'done') return rows.filter(r => r.pendingUnits === 0 && r.doneUnits > 0);
  if (status === 'pending') return rows.filter(r => r.pendingUnits > 0);
  return rows;
}

function getScheduleTimeListRowKey(kind, row) {
  if (kind === 'teacher') return row.teacherId;
  if (kind === 'course') return row.code;
  return `${row.programmeKey}|${row.intake}`;
}

function filterScheduleArrangeRowsBySubmit(rows, kind, submit) {
  if (submit === 'submitted') return rows.filter(r => isScheduleTimeScopeSubmitted(kind, getScheduleTimeListRowKey(kind, r)));
  if (submit === 'unsubmitted') return rows.filter(r => !isScheduleTimeScopeSubmitted(kind, getScheduleTimeListRowKey(kind, r)));
  return rows;
}

function renderScheduleArrangeStatusBadge(row) {
  if (row.pendingUnits > 0) return '<span class="badge badge-gray">未排完</span>';
  if (row.doneUnits > 0) return '<span class="badge badge-green">已排完</span>';
  return '<span class="badge badge-gray">未排完</span>';
}

function renderScheduleTeacherPage() {
  const tbody = document.getElementById('schedule-teacher-body');
  rebuildScheduleTermSelects();
  const termEl = document.getElementById('schedule-teacher-filter-term');
  if (termEl) { const term = getActiveOfferingTermSetting(); termEl.value = term ? formatCourseTermDisplay(term.termCode) : ''; }
  renderScheduleOfferingHint('schedule-teacher-hint');
  ensureScheduleGlobalDemo();
  if (!ensureScheduleTasksFromOffering()) {
    renderScheduleEmptyRow(tbody, 11, '暂无课程数据，请先在开课管理中完成开课计划');
    return;
  }
  let rows = getScheduleTeacherGroupRows();
  const idQ = (document.getElementById('schedule-teacher-filter-id')?.value || '').trim().toLowerCase();
  const nameQ = (document.getElementById('schedule-teacher-filter-name')?.value || '').trim().toLowerCase();
  const deptQ = (document.getElementById('schedule-teacher-filter-dept')?.value || '').trim().toLowerCase();
  const status = document.getElementById('schedule-teacher-filter-status')?.value || '';
  if (idQ) rows = rows.filter(r => r.teacherId.toLowerCase().includes(idQ));
  if (nameQ) rows = rows.filter(r => (r.name || '').toLowerCase().includes(nameQ));
  if (deptQ) rows = rows.filter(r => (r.dept || '').toLowerCase().includes(deptQ));
  rows = filterScheduleArrangeRowsByStatus(rows, status);
  if (!rows.length) {
    renderScheduleEmptyRow(tbody, 11, status ? '暂无匹配记录' : '暂无课程数据，请先在开课管理中完成开课计划');
    return;
  }
  tbody.innerHTML = rows.map((r, idx) => {
    const canArrange = canScheduleArrangeActionAny('time', (r.tasks || []).map(t => t.programmeKey));
    return `<tr>
    <td class="col-index">${idx + 1}</td>
    <td><code>${escapeHtml(r.teacherId)}</code></td>
    <td>${escapeHtml(r.name)}</td>
    <td>${escapeHtml(r.dept)}</td>
    <td class="col-center">${escapeHtml(r.staffType)}</td>
    <td class="col-center">${r.courseCount}</td>
    <td class="col-center">${r.groupCount || 0}</td>
    <td class="col-center">${r.doneUnits}</td>
    <td class="col-center">${r.pendingUnits ? `<span class="status draft">${r.pendingUnits}</span>` : '0'}</td>
    <td class="col-center">${renderScheduleArrangeStatusBadge(r)}</td>
    <td class="col-center actions">${renderScheduleDetailLaunchLink({ type: 'teacher', teacherId: r.teacherId }, 'time', canArrange ? '排课' : '查看')}</td>
  </tr>`;
  }).join('');
}

function resetScheduleTeacherQuery() {
  ['schedule-teacher-filter-id', 'schedule-teacher-filter-name', 'schedule-teacher-filter-dept', 'schedule-teacher-filter-status'].forEach(id => {
    const el = document.getElementById(id); if (el) el.value = '';
  });
  renderScheduleTeacherPage();
}

/** 按课程聚合的排课行 */
function getScheduleCourseGroupRows() {
  const map = new Map();
  consolidateScheduleTasksByCourse(getScheduleTaskRows()).forEach(t => {
    if (!map.has(t.code)) map.set(t.code, { code: t.code, name: t.name, tasks: [] });
    map.get(t.code).tasks.push(t);
  });
  return [...map.values()].sort((a, b) => a.code.localeCompare(b.code)).map(g => {
    const stats = buildScheduleTimeArrangeMenuStats(g.tasks);
    const dept = SCHEDULE_COURSE_DEPT[g.code]
      || (SCHEDULE_TEACHER_META[getScheduleTaskTeacherId(g.tasks[0])]?.dept)
      || '—';
    const schoolCode = g.tasks[0]?.schoolCode || getProgrammeSchoolCode(g.tasks[0]?.programmeKey) || '';
    return {
      code: g.code, name: g.name, dept, schoolCode, tasks: g.tasks,
      groupCount: stats.groupCount,
      doneUnits: stats.doneUnits,
      totalUnits: stats.groupCount,
      pendingUnits: stats.pendingUnits
    };
  });
}

